quests[1052] = { id = 1052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Scharlachroten Pfad", description = "Wir vom Scharlachroten Kreuzzug erheben Anspruch auf die Festungen zwischen Hearthglen und Tirisfal. Wir sind recht stolz auf unsere Bastionen der Säuberung in ganz Lordaeron.\n\nIhr habt Euch gegen die Untoten in Desolace bewiesen. Doch die wahre Bedrohung durch die Seuche liegt in Lordaeron.\n\nBegebt Euch nach Southshore in den östlichen Königreichen. Sucht dort nach einem Kreuzzügler namens Raleigh der Andächtige. Gebt ihm dieses Empfehlungsschreiben, das mein Siegel trägt, dann wird er Euch zu einem ehrwürdigen Ort in unserem Scharlachroten Kloster führen.", sourceObjective = "Bringt Raleigh dem Andächtigen in Southshore Bruder Antons Empfehlungsschreiben.", progress = "Wer ist da? Was wollt Ihr von mir?", completion = "Bruder Anton verbreitet immer noch die Lehren des scharlachroten Kreuzzuges? So, so...", sourceObjectiveStatus = "unverified-source-field" }
quests[1053] = { id = 1053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Namen des Lichts", description = "Einst diente ich dem Scharlachroten Kreuzzug mit Ehre, Treue und Stolz. Ich hielt das Ziel, das sie verfolgten, für edel: Azeroth von den Untoten befreien.\n\nAls ich jedoch im Kloster in Tirisfal weilte, erkannte ich, dass sie langsam den Bezug zur Wirklichkeit verloren. Jetzt halten sie jeden für verseucht, der nicht das Wams des Kreuzzuges trägt. Unschuldige Männer und Frauen wurden gefoltert, weil sie angeblich verseucht waren. \n\nDer Scharlachrote Kreuzzug muss im Namen des Lichts zerschlagen werden. Ihr, {name}, müsst ihr wahnwitziges Regime beenden.", sourceObjective = "Tötet Hochinquisitor Whitemane, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Raleigh dem Andächtigen in Southshore.", completion = "Die Jünger des Lichts sind nicht erpicht darauf, ihr Leben zu lassen, doch müssen wir akzeptieren, dass manche Umstände es erforderlich machen, solche Opfer für das Wohl des Königreiches und des gesamten Planeten zu bringen.\n\nDurch Eure Taten im Kloster habt Ihr vielen Unschuldigen das Leben gerettet, {name}. Ich verbeuge mich vor Eurer Beharrlichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[1054] = { id = 1054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Auswahl der Bedrohung", description = "Direkt im Norden Astranaars leben die Furbolgs vom Distelfellstamm. Meine Späher berichten, dass ihre Zahl sich in den letzten Monaten erhöht hat. Sollten es zu viele werden, könnten sie den Mut finden, Astranaar direkt anzugreifen.\n\nTötet so viele von ihnen, wie Ihr könnt, aber bringt mir den Schädel ihres Häuptlings zum Beweis dafür, dass ihr Bemühen im Keim erstickt wurde ... vorläufig.\n\nIch bleibe hier in Astranaar und warte auf Kunde von Euch. Elune sei mit Euch.", sourceObjective = "Bringt Raene Wolfrunner in Astranaar Dal Blutklaues Schädel.", progress = "Die Verderbnis der Furbolgs hat aus Ashenvale ein Zerrbild seines einstigen Glanzes gemacht.", completion = "Gut gemacht, {name}.\n\nDie Furbolgs sind eine ständige Bedrohung. Hoffentlich wird sie das noch eine Weile in Schach halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1055] = { id = 1055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raenes Säuberung", description = "Die Rute, jetzt wieder heil, liegt in Euren Händen. Shael'dryn wird von Eurem Erfolg hören wollen.", sourceObjective = "Kehrt zu Shael'dryn beim Mondbrunnen zurück.", completion = "Ihr habt es geschafft, {name}! Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[1056] = { id = 1056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Steinkrallengipfel", description = "Die Waldgeister sagten mir, dass Ihr mutig und zu reisen gewillt seid.\n\nIm Süden, nicht weit vom Mystralsee entfernt, liegt ein Tunnel namens Steinkrallenpfad. Durch diesen Tunnel gelangt Ihr in ein Gebiet, das im Steinkrallengebirge als Scherwindklippe bekannt ist. Dort angelangt reist südwestlich weiter, am Felskesselsee vorbei und dann nach Norden, den steilen Abhang hinauf, bis Ihr den Steinkrallengipfel erreicht.\n\nDort werdet Ihr von Hüter Albagorm erwartet. Tut, was er sagt, {race}.\n\nDie Reise wird gefährlich.", sourceObjective = "Reist zu Bewahrer Albagorm auf dem Steinkrallengipfel.", completion = "Endlich seid Ihr da. Ich sehe, Faldreas hat auf die Waldgeister gehört...", sourceObjectiveStatus = "unverified-source-field" }
quests[1057] = { id = 1057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung des verbrannten Tals", description = "Als Beschützer der Waldgeister könnt Ihr sicher unschwer erraten, warum ich beunruhigt bin.\n\nIhr seid durch diese Berge gereist, um diesen Gipfel zu erreichen. Sicherlich habt Ihr das Zerrbild gesehen, zu dem das Land geworden ist. Gier hat zur Zerstörung dieser heiligen Hügel geführt.\n\nDie gierige motorisierte Armee der Industrialisten hat das verbrannte Tal im Süden in Brand gesteckt. Was noch schlimmer ist, die Blutfurien, die in unser Land eingedrungen sind, lassen uns nicht dorthin, um mit der Neuanpflanzung zu beginnen.\n\nVertreibt diese elenden Harpyien, {name}!", sourceObjective = "Bewahrer Albagorm auf dem Steinkrallengipfel möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt.", completion = "Jetzt, da die Blutfurien einen solch großen Verlust erlitten haben, können wir vielleicht endlich ernsthaft an den Wiederaufbau des Landes gehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[1058] = { id = 1058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'Zils Waldmagie", description = "Ich bin ja so aufgeregt!\n\nDrei kleine Käfige mit drei kleinen Elfen! Aber was tun wir nur mit unseren süßen Baumschützer-Freunden? Na, lassen wir sie doch... wie nennen sie das doch gleich... Waldmagie schmecken!\n\nIch brauche einen ordentlichen Schuss Steinkrallensaft. Dann brauche ich ein paar Mondlichtläuferschnurrhaare von diesen schrecklichen Katzen. Das schreit nach einer Menge Renneraugen - man kann nie genug Augen haben. Oh, und bevor wir es vergessen, die wertvolle Schuppe eines Siechdrachen.\n\nSchnell zum Steinkrallengipfel, {name}, damit ich etwas Waldmagie zusammenbrauen kann!", sourceObjective = "Hexendoktor Jin'Zil in Malaka'jin möchte 5 Portionen Steinkrallensaft, 5 Schnurrhaare eines Mondlichtläufers, 30 Renner-Augen und die Schuppe eines Siechdrachen.", progress = "Seht Euch nur unsere armen kleinen Elfenfreunde an. Eingesperrt in einen Käfig und weit und breit kein Wald, in dem sie herumtollen können!\n\nNun, habt Ihr etwas Saft für mich gefunden? Was ist mit den Schnurrhaaren der Mondlichtläufer? Ihr habt nicht zufällig diese Siechdrachen-Schuppe dabei?\n\nUnd die Augen! Ich brauche jede Menge Augen! Ohne eine ordentliche Portion Augen kann man einfach keine starke Waldmagie zusammenbrauen!", completion = "Oh, wie glücklich werden diese kleinen Waldnymphen sein! Mit diesem Spezialgebräu werden sie sich ganz wie zu Hause fühlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1059] = { id = 1059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung des verbrannten Tals", description = "Die Blutfurien wurden besiegt. Sie werden sich jedoch schon bald wieder neu gruppieren, wenn wir nichts unternehmen.\n\nGanz weit im Süden des Brachlandes liegt ein Land, das als Tausend Nadeln bekannt ist. Wenn Ihr in Tausend Nadeln nach Westen reist bis zum üppigen Waldrand von Feralas, stoßt Ihr auf einen Druiden namens Falfindel Waywarder.\n\nDieser große und weise Druide kann große Waldgeister herbeirufen, die bei der Rekultivierung des verbrannten Tals helfen können.\n\nErzählt ihm von unserer Notlage! Sucht ihn sofort auf!", sourceObjective = "Reist zu Falfindel Waywarder an der Grenze zwischen Tausend Nadeln und Feralas.", completion = "Es war sehr klug von Bewahrer Albagorm, Euch so schnell zu entsenden.\n\nLasst uns sehen, ob wir nicht Hilfe aus dem großen Wald herbeirufen könnten, damit wir zum verbrannten Tal reisen können, bevor es zu spät ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[1060] = { id = 1060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brief an Jin'Zil", description = "Ihr habt mir sehr geholfen, {name}. Ihr seid ein echter Glücksbringer, wie eine Hasenpfote, und ich möchte, dass Ihr Euch das hier einmal anseht.\n\nDie Harpyien stammen nicht aus dem Brachland. Sie kommen aus einem Ort namens Steinkrallengebirge, ganz weit nordwestlich von hier. Dort könnte es möglicherweise gefährlich für Euch sein, aber dieser Brief muss an einen alten Freund von mir überbracht werden, der dort lebt, ein Hexendoktor mit dem Namen Jin'Zil.\n\nEr wird sich freuen zu hören, dass Serena Blutfeder tot ist, und ich glaube, Ihr werdet das Steinkrallengebirge sehr interessant finden.", sourceObjective = "Überbringt Jin'Zil in seiner Höhle im Steinkrallengebirge Darsoks Brief.", progress = "Ihr scheint mir ein fragwürdiger Charakter zu sein. Wollt Ihr mir etwas zeigen?", completion = "Ah, ein Brief von Darsok. Ich habe seit Jahren nichts mehr von ihm gehört.\n\nDie letzte Blutfeder ist also tot, was? Das sind gute Neuigkeiten. Ich kann mich noch daran erinnern, als mein Freund Rokhan mit diesem verrückten Mok'Nathal auszog, um ihre ältere Schwester zu töten. Ah, könnte man doch noch mal jung sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1061] = { id = 1061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister des Steinkrallengebirges", description = "Die Geister des Steinkrallengebirges sind verärgert, weil Goblins und ihre Gefolgsleute das Land ausplündern und brandschatzen. Das Land rief um Hilfe, und jene, die auf so etwas achten... haben es gehört.\n\nSeereth Stonebreak, eine aufstrebende Schamanin der Horde, wurde in das Steinkrallengebirge geschickt. Sie berichtet von umfangreichen Rodungen durch die Goblins und bittet um Hilfe.\n\nTrefft Euch im Steinkrallengebirge mit Seereth. Um zu ihr zu gelangen, folgt der Straße westlich aus Crossroads im Brachland. Sie hat in der Nähe des Hochwipfeltals ein Lager aufgeschlagen.", sourceObjective = "Sprecht im Steinkrallengebirge mit Seereth Stonebreak.", completion = "Ah, {class}. Sehr gut. Wir werden Eure Fähigkeiten brauchen, um diese Brandschatzer zu bekämpfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1062] = { id = 1062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin-Eindringlinge", description = "Die von Goblins geleitete Venture Company ist in das Steinkrallengebirge umgezogen, um dort Bäume zu fällen und ganze Waldflächen zu brandroden. Die Geister dort sind außer sich vor Schmerz und Wut. Wir müssen der Venture Company Einhalt gebieten!\n\nBegebt Euch nach Nordwesten, jenseits des Hochwipfeltals, und zur Scherwindklippe. Ihr werdet dort die Goblins und ihre Gefolgsleute bei der Arbeit vorfinden - zeigt ihnen, dass die Horde eine Ausbeutung des Steinkrallengebirges nicht billigt. Zeigt es ihnen in der Sprache, die sie am besten verstehen...\n\nGewalt.", sourceObjective = "Tötet 15 Holzfäller der Venture Co. und kehrt dann zu Seereth Stonebreak an der Grenze des Steinkrallengebirges und dem Brachland zurück.", completion = "Tapfer, tapfer, {name}.\n\nWir werden letztendlich die Weisheit der Taurenältesten benötigen, um die Geister des Steinkrallengebirges zu beschwichtigen, aber...\n\nDer \"Personalabbau\" bei der Venture Company ist schon ein guter Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[1063] = { id = 1063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ältestengreisin", description = "Um die Geister des Steinkrallengebirges wirklich zu beschwichtigen, müssen wir uns an die Taurenältesten wenden.\n\nIch kenne nicht viele ihrer Anführer, aber einen Namen kenne ich: Magatha. Ich habe gehört, dass sie sehr alt sein soll und sehr viel weiß. Wenn jemand die Tauren um geistige Hilfe bitten kann, dann sie.\n\nMagatha lebt in der Tauren-Hauptstadt Thunder Bluff auf der Anhöhe der Ältesten - dem Steilhang im Nordosten der Stadt. Sprecht mit Magatha und berichtet ihr von der Not im Steinkrallengebirge.", sourceObjective = "Sprecht in Thunder Bluff mit Magatha.", completion = "Ich entbiete Euch meinen Gruß. Seid Ihr wegen eines Rates gekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[1064] = { id = 1064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hilfe der Verlassenen", description = "Die Tauren sind mit dem Land verbunden, und es schmerzt mich, von der Not im Steinkrallengebirge zu hören. Ich fürchte jedoch, dass wir zunächst die Krankheit ausmerzen müssen, bevor wir das Land heilen können.\n\nIst es nicht eine glückliche Fügung, dass wir mit den Verlassenen verbündet sind? Sie wissen viel über Krankheiten. Ich glaube, sie werden uns helfen können, was das gegenseitige Vertrauen zwischen unseren Völkern stärken wird.\n\nSprecht mit Apothekerin Zamah. Sie ist eine Gelehrte und Botschafterin der Verlassenen. Ihr findet sie bei den Teichen der Visionen unterhalb der Anhöhe der Geister.", sourceObjective = "Sprecht bei den Teichen der Visionen mit der Apothekerin Zamah.", completion = "Magatha hat mir Euer Kommen angekündigt, {name}. Obwohl mein Herz nicht mehr schlägt, sorge ich mich doch um die Geister des Steinkrallengebirges.\n\nDie Verlassenen brennen darauf, auf jede erdenkliche Weise zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1065] = { id = 1065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Tarrens Mühle", description = "Um die Venture Company aus dem Steinkrallengebirge zu vertreiben, müssen wir extreme Maßnahmen ergreifen. Extrem, aber ohne Blutvergießen.\n\nEiner meiner Kollegen hat vielleicht genau das Werkzeug, das wir benötigen. Er heißt Lydon und wohnt in Tarrens Mühle im Vorgebirge von Hillsbrad, das im weit entfernten Lordaeron liegt.\n\nUm nach Hillsbrad zu gelangen, reist mit dem Zeppelin in unsere Hauptstadt, nach Undercity. Geht von dort aus nach Norden nach Tirisfal, dann südwestlich nach Silberwald und südlich nach Hillsbrad.\n\nSucht Lydon auf und gebt ihm diese Notiz. Sie wird ihm alles erklären.", sourceObjective = "Bringt Apotheker Lydon in Tarrens Mühle Zamahs Notiz.", progress = "Ah, bringt Ihr mir meine neuesten Versuchskaninchen?", completion = "Eine Notiz von Zamah? Es muss dringend sein, wenn sie mir von so weit her eine Nachricht zukommen lässt. Mal sehen, was sie schreibt...\n\nAh, großartig! Ich weiß genau, was zu tun ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[1066] = { id = 1066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut Unschuldiger", description = "Ich werde ein Toxin herstellen, mit dem wir der Venture Company die Gewalt entziehen und sie schwach und sanftmütig werden lassen. Das sollte das Problem der Horde im Steinkrallengebirge lösen, meint Ihr nicht?\n\nUm das Toxin herzustellen, benötige ich jedoch das Blut Unschuldiger, eine Zutat, an die man nur schwer herankommt.\n\nGlücklicherweise beschäftigt das Syndikat, das ist eine Gruppe menschlicher Briganten in dieser Region, Schattenmagier ... und diese Magier beschaffen sich das Blut Unschuldiger für ihre eigenen unappetitlichen Machenschaften.\n\nIhr finded die Schattenmagier des Syndikats in der Burg Durnholde im Südosten.", sourceObjective = "Bringt Apotheker Lydon in Tarrens Mühle 5 Phiolen mit dem Blut Unschuldiger.", progress = "Habt Ihr die Schattenmagier des Syndikats gefunden und von ihnen Blut bekommen?", completion = "Sehr gut! Das Syndikat hat Euch doch hoffentlich nicht allzu viele Schwierigkeiten gemacht?\n\nWie ich erwähnte, kommt man nicht leicht an das Blut Unschuldiger heran. Wir haben Glück, dass die Schattenmagier des Syndikats uns diese schwierige Arbeit abgenommen haben.\n\nWartet bitte einen Moment, während ich mein Gebräu herstelle ...", sourceObjectiveStatus = "unverified-source-field" }
quests[1067] = { id = 1067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Thunder Bluff", description = "Hier habt Ihr das Toxin. Wenn Ihr es gegen die Venture Company einsetzt, sollte es positive, vielleicht sogar ansteckende Ergebnisse erzielen. Ich muss sagen, es ist ziemlich aufregend zu sehen, dass mein Werk tatsächlich eingesetzt wird!\n\nBringt es aber erst der Apothekerin Zamah, bevor Ihr es einsetzt. Sie muss eine Anwendungsmethode für das Toxin entwickeln, um einen größtmöglichen Effekt zu erzielen.", sourceObjective = "Bringt Apothekerin Zamah in Thunder BluffLydons Toxin.", progress = "Ihr seid zurück, {name}. Bringt Ihr Hilfe von Apotheker Lydon?", completion = "Ein Toxin von Apotheker Lydon? Sehr gut. Wie ich Lydon kenne, wird dieses Toxin äußerst wirkungsvoll gegen die Venture Company sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[1068] = { id = 1068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreddermaschinen", description = "Es gibt eine Verbindung zwischen der spirituellen Magie der Schamanen und der natürlichen Magie der Druiden. Deshalb können die Schamanen auch das Flehen der Geister des Steinkrallengebirges hören. Vieles, das sie flüstern, verstehe ich nicht, aber eine Nachricht, eine Vision, ist eindeutig ...\n\nIch hatte die Vision zweier menschenähnlicher Maschinen, die auf der Scherwindklippe nordwestlich des Hochwipfeltals mit ungeheuerlicher Geschwindigkeit Bäume fällten. Diese Metallbestien müssen aufgehalten werden!\n\nIn meiner Vision trugen diese Maschinen seltsame Symbole:\n\nXT:4 und XT:9.", sourceObjective = "Vernichtet die Schredder XT:4 und XT:9 und kehrt dann zu Seereth Stonebreak an der Grenze zwischen dem Steinkrallengebirge und dem Brachland zurück.", completion = "Die Zerstörung der Maschinen XT:4 und XT:9 hat viele der Geister des Steinkrallengebirges besänftigt, {name}. Hoffen wir, dass sich die Venture Company aufgrund dieses Verlustes aus diesen Bergen zurückziehen wird.\n\nGeschieht dies nicht, fürchte ich, dass die Gräueltaten, die dieser Ort bereits erleiden musste, nur ein fahler Vorgeschmack auf das sind, was ihm noch bevorsteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1069] = { id = 1069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eier der Kluftmoosspinnen", description = "Omeletts aus Spinneneiern sind der letzte Schrei in Booty Bay! Das Problem ist nur... dass es in Booty Bay keine Eier gibt.\n\nDas riecht nach einer Geschäftsidee!\n\nAn der Scherwindklippe und im Sishircanyon nordwestlich im Steinkrallengebirge, lebt die Kluftmoosspinne. Bringt mir ihre Eier, dann werde ich Euch reichlich entlohnen!\n\nAn der Scherwindklippe sind die Eihaufen unter den noch verbliebenen Bäumen zu finden.\n\nIm Sishircanyon... tja, wenn Ihr einen schwachen Magen habt, solltet Ihr vielleicht nur die Eier an der Scherwindklippe sammeln...", sourceObjective = "Bringt Mebok Mizzyrix in Ratchet 15 Kluftmooseier.", progress = "Habt Ihr die Eier, {name}? Ich habe mit Werftmeister Dizzywig bereits eine Transportvereinbarung getroffen!", completion = "Ihr habt sie! Danke!\n\nIch werde sie Dizzywig schicken, der sie dann nach Booty Bay verschifft. Ich kann den Profit schon fast schmecken!\n\nHier ist Euer Anteil, {name}. Ohne Euch hätte ich dieses Geschäft nicht machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[1070] = { id = 1070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wache halten im Steinkrallengebirge", description = "Hallo, {name}.\n\nSo wie Ihr ausseht, scheint Ihr voller Reiselust zu sein. Wart Ihr schon mal im Steinkrallengebirge? Es ist ein Land, das von der Venture Company und anderen Feinden der Nachtelfen heimgesucht wird.\n\nErst neulich schickte Schildwache Wolfrunner meine Freundin Kaela Shadowspear dorthin, um zu untersuchen, was mit dem Land geschehen ist, aber ich habe seitdem nichts mehr von ihr gehört. Was mir noch mehr Sorgen macht ist, dass die Allianz sie zusammen mit einem Gnomen-Magier losgeschickt hat ... das deutet definitiv auf Probleme hin.\n\nWürdet Ihr sie suchen und mir dann Bericht erstatten?", sourceObjective = "Sucht Kaela Shadowspear, die auf der Scherwindklippe im Steinkrallengebirge den Taleingang beobachtet.", completion = "Ah, Ihr seid auf Taras Geheiß aus Ashenvale gekommen - wie sehr ich sie vermisse, mein Heimatland und meine Freunde. Sie muss mit ihren Schildwachen sehr beschäftigt sein, wenn sie Abenteurer für andere Aufgaben rekrutieren muss. Ich bin sehr stolz auf sie.\n\nEs ist mir eine Freude, Eure Bekanntschaft zu machen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1071] = { id = 1071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Aufschub des Gnoms", description = "Wisst Ihr, {name}, ich bin Mitglied der Erleuchteten Vereinigung der Arkanologie, Alchimie und Ingenieurwissenschaften, und es ist mein Ziel... nein, meine PFLICHT!, den Nachtelfen zu zeigen, dass eine Mischung aus Magie, Mixturen und Mechanismen dazu beitragen kann, ihren Wald zu retten.\n\nEs ist jedoch ein Kampf gegen Windmühlen, und die Goblins vermehren sich wie die Kaninchen, wie es scheint. Ich hatte sogar nicht mal Zeit, um meine neuesten Erfindungen zu bauen!\n\nIch brauche etwas Zeit, um zu planen und zu organisieren. Dazu brauche ich jedoch Eure Hilfe bei der Eindämmung der Goblins auf der Scherwindklippe im Osten...", sourceObjective = "Tötet 10 Holzfäller der Venture Co. und 10 Roder der der Venture Co. und kehrt dann zu Gaxim Rustfizzle im Steinkrallengebirge zurück.", progress = "Wie läuft die Schlacht bei Euch, {name}?", completion = "Vielen Dank für Eure Hilfe, {name}. Ihr kommt gerade rechtzeitig zurück.\n\nIch glaube, ich habe den perfekten Plan... Sprengstoff. Nein, das ist noch nicht der Plan, aber ein Teil des Plans.\n\nSeht Ihr, ich habe hochexplosiven Sprengstoff benutzt - keine Sorge, der ist gar nicht so gefährlich, wie alle meinen -, um den Goblins ein bisschen Angst einzujagen. Ich kann sie mit ein paar gezielt platzierten Sprengungen entlang des Gebirgsrandes ziemlich gut zusammentreiben, aber mir gehen langsam die Vorräte aus...", sourceObjectiveStatus = "unverified-source-field" }
quests[1072] = { id = 1072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein alter Kollege", description = "Das Gerät, das mir vorschwebt, wird meine am weitesten entwickelte Erfindung sein. Aber wir brauchen einen speziellen Trank, wenn es funktionieren soll. Ich glaube, wir sollten uns gleich an das gute Zeug halten, immerhin könnte das unsere letzte Mission sein.\n\nUnd deshalb brauchen wir einen hochwirksamen Sprengstoff: Nitromirglyceronium.\n\nDie einzige Person, die NG-5 herstellen kann, ist ein alter Freund von mir: Lomac Gearstrip. Sucht in Tüftlerstadt nach ihm.\n\nWenn Ihr ihn überreden könnt, uns etwas NG-5 herzustellen, kann ich mich an die Platzierung meiner Geräte machen.", sourceObjective = "Sprecht mit Lomac Gearstrip in Ironforge.", completion = "Ahhh... Gaxim hat Euch geschickt? Woher weiß ich, dass Ihr mich nicht belügt? Hmm? Hmm...?", sourceObjectiveStatus = "unverified-source-field" }
quests[1073] = { id = 1073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stümperhaftigkeit + Chemikalien = Riesenspaß!", description = "Hahaha... Ihr braucht Nitromirglyceronium, um Goblins daran zu hindern, einen Wald zu zerstören?!\n\nEs ist mir egal, ob Ihr Gaxim kennt oder nicht... Ich würde Euch das Zeug allein schon deshalb geben, weil ich sehen will, wie Ihr oder sie in klitzekleine Fetzen explodieren.\n\nEs gibt allerdings ein Problem: Ich hab nichts mehr.\n\nAber ich sag Euch was: Bringt mir die richtigen Tränke, dann stelle ich sofort etwas für Euch her.\n\nDas Mindeste, was Ihr tun könnt, ist, mir ein paar Eurer Alchimisten-Fertigkeiten vorzuführen, bevor ich Euch eine Kostprobe meiner größten Erfindung gebe.", sourceObjective = "Bringt Lomac Ritzeldreh in Eisenschmiede 4 schwache Manatränke und 2 Elixiere der schwachen Seelenstärke.", progress = "Ohne die Tränke kann ich kein Nitromirglyceronium herstellen... sie sind für die Herstellung unbedingt erforderlich.", completion = "Das sollte klappen.\n\nWenn ich es nicht besser wüsste, Fremdling, würde ich sagen, Ihr kennt Euch ein bisschen mit Alchimie aus. Gut, gut... in der Welt dreht sich nicht alles immer nur um Schwerter oder Zauberei, wisst Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[1074] = { id = 1074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stümperhaftigkeit + Chemikalien = Riesenspaß!", description = "Bitte sehr, Fremdling. Seid jedoch vorsichtig damit... das Zeug ist hochexplosiv.\n\nFalls Ihr wirklich ein Freund von Gaxim seid, grüßt ihn von mir. Falls nicht, dann viel Spaß beim Selbst-in-die-Luft-jagen.", sourceObjective = "Bringt Gaxim Rustfizzle im Steinkrallengebirge das Nitromirglyceronium.", progress = "Ah, prima, prima, Ihr seid zurück.", completion = "Ihr habt Eure Aufgabe fehlerfrei erledigt, {name}.\n\nNG-5 ist die wichtigste Komponente in diesem Rezept zur Zündung der Wagen mit Dynamit.\n\nWas? Ja, Dynamit... ganze Wagenladungen. Das ist das perfekte Ablenkungsmanöver... Ihr werdet es schon sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1075] = { id = 1075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Rolle von Mauren", description = "Gut, wenden wir uns jetzt dem Teil meines Planes mit der Fernzündung zu... oh, das hab ich ja noch gar nicht erklärt, stimmt's?\n\nAlso dann mal die Kurzversion: Mit etwas Magie kann ich dafür sorgen, dass der Sprengstoff hochgeht, ohne dass Ihr dabei sein müsst. Ich bastele ein Gerät zusammen, bei dem Ihr nur einen Knopf drücken müsst, damit das NG-5 explodiert, wenn Ihr bereit seid.\n\nIch brauche jedoch einen Zauber von einem Freund in Stormwind - er heißt Collin Mauren. Ihr findet ihn im dortigen Magierviertel. Er ist ein Mensch, daher solltet Ihr ihn kaum verfehlen können.", sourceObjective = "Sucht Collin Mauren in Stormwind auf.", completion = "Tja, dieser Zauber, den Ihr benötigt... einen, mit dem man Sprengstoff aus der Entfernung zünden kann... hmmm.", sourceObjectiveStatus = "unverified-source-field" }
quests[1076] = { id = 1076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufel in Westfall", description = "Ah, ich glaube, ich hab's. Ein Nachrichtenzauber... Er dürfte den Effekt haben, nachdem er sucht.\n\nIch muss eine Rolle herstellen, auf die der Zauber geprägt ist. Dazu benötige ich die Überreste eines Staubteufels.\n\nWarum geht Ihr nicht nach Westfall und sucht eine dieser elenden Kreaturen, während ich den Rest der Komponenten sammle? Sie sind gefährlich, aber ich bin mir sicher, dass Ihr schon damit klarkommt, zumal Ihr sogar gewillt seid, an einem von Gaxims Experimenten teilzunehmen.\n\nIch werde hier sein, wenn Ihr zurückkommt.", sourceObjective = "Bringt Collin Mauren in Stormwind die Überreste eines Staubteufels.", progress = "Hallo, {name}. Habt Ihr die Komponente gefunden, die ich benötige?", completion = "Einen kleinen Moment noch, dann habe ich die Rolle für Euch fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[1077] = { id = 1077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speziallieferung für Gaxim", description = "Bitte sehr, {name}. Das sollte funktionieren.\n\nBitte grüßt Gaxim von mir, wenn Ihr ihn das nächste Mal seht. Ich freue mich schon so darauf, von diesem Abenteuer zu hören, wenn Ihr es überstanden habt.\n\nLebt wohl.", sourceObjective = "Bringt Gaxim Rustfizzle im Steinkrallengebirge die Rolle der Nachrichtenübermittlung.", progress = "Haha! Ihr seid zurück! Habt Ihr ihn? Habt Ihr den Zauber?", completion = "Das ist perfekt, {name}. Gut gemacht.\n\nDieser Zauber in Verbindung mit dem NG-5 ergibt einen perfekten Sprengstoff mit Fernzündung.\n\nWir werden eine perfekte Ablenkung für Euch schaffen, damit Ihr hineinschleichen und alle Briefe und Ingenieurspläne der Venture Company stehlen könnt.\n\nDas wird ihre Rodungsaktionen behindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[1078] = { id = 1078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche für Mauren", description = "Immer wieder fragen mich Reisende über das Steinkrallengebirge aus. Scheint ein beliebter Ort unter Abenteurern zu sein; spielt keine Rolle, ob man Flügeldrachen oder Elementare sucht, oder ob man Geschäfte mit der Venture Company machen will.\n\nIm verbrannten Tal tief im Steinkrallengebirge gab es mal eine Basiliskenart, deren Schuppen, wenn man sie zu Staub zermahlte, ein wunderbares Reagenz für einige der Zauber ergab, die ich ersonnen habe.\n\nWenn diese Basilisken noch leben, hätte ich liebend gern ein paar ihrer Schuppen.\n\nLasst Euch Zeit, ich hab keine Eile, aber ich kann Euch gut bezahlen.", sourceObjective = "Bringt Collin Mauren in Stormwind 8 kristallisierte Schuppen.", progress = "Hallo, {name}.\n\nSeid Ihr mit den Schuppen schon wieder aus dem Tal im Steinkrallengebirge zurück?", completion = "Das ist perfekt, {name}. Vielen, vielen Dank.\n\nVielleicht kann ich Euch eines Tages einmal so helfen, wie Ihr mir geholfen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1079] = { id = 1079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimoperation Alpha", description = "Das ist es, {name}. Seht genau hin. Die Geräte sind fertig und einsatzbereit.\n\nNehmt diese Blätter - sie erklären mehr über die Zünder und den Sprengstoff und wo Ihr ihn platzieren solltet.\n\nDenkt daran, der Erfolg Eurer Mission hängt nicht davon ab, wie viel Schaden Ihr anrichtet. Der Erfolg von Plan Alpha hängt davon ab, dass Ihr die Ingenieurspläne der Venture Company aus dem Sägewerk südlich des Felskesselsees holt.", sourceObjective = "Holt die Ingenieurspläne der Venture Company aus dem Sägewerk auf der Scherwindklippe.", progress = "Habt Ihr die Pläne, {name}?", completion = "Einfach erstaunlich! Das versetzt der Venture Company einen Riesenschlag.\n\nJetzt können wir Schwächen an ihren Maschinen aufdecken und ihre Entwürfe für unsere eigenen Kreationen ausnutzen. Das ist heute wahrlich ein Freudentag.", sourceObjectiveStatus = "unverified-source-field" }
quests[1080] = { id = 1080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimoperation Beta", description = "Plan Beta funktioniert genau wie Plan Alpha, {name}.\n\nWir stiften Verwirrung und stehlen dann ihre wertvollen Dokumente.\n\nWir müssen unbedingt diese Dokumente haben... vergesst das nicht.\n\nDie Blätter, die Ihr bereits habt, zeigen Euch, wo Ihr den Sprengstoff platzieren müsst. Kommt mir nur heil und mit diesen Dokumenten zurück...", sourceObjective = "Holt die Dokumente der Venture Company aus der Scherwindmine am Ostende der Scherwindklippe.", progress = "Wie ist es gelaufen, {name}?", completion = "Unglaublich, {name}! Kaela und die Schildwachen werden überglücklich sein. Mit Euren Fertigkeiten und meinen Erfindungen sind wir unschlagbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1081] = { id = 1081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrandes Empfang", description = "{name}, ich bin mir sicher, dass Tyrande Whisperwind Euch persönlich für Eure Teilnahme an dieser Mission danken wollen wird.\n\nEs mag auf den ersten Blick zwar nicht so aussehen, aber Ihr habt dazu beigetragen, etwas in Gang zu setzen, das unsere Position im Steinkrallengebirge erheblich stärken wird.\n\nFalls Ihr Euch als unseren Verbündeten im Kampf gegen diese Gräueltaten betrachtet, sucht Tyrande im Tempel des Mondes in Darnassus auf.", sourceObjective = "Sucht Tyrande Whisperwind in Darnassus auf.", completion = "Hallo, {name}. Ich habe tatsächlich schon von Euch gehört, und obwohl Ihr noch so jung seid, freue ich mich zu sehen, welchen Lebensweg Ihr eingeschlagen habt.\n\nIhr würdet mir eine große Ehre erweisen, wenn Ihr das hier als Zeichen meiner Anerkennung annehmen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1082] = { id = 1082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten für Schildwache Thenysil", description = "{name}, Ihr habt Großes geleistet, indem Ihr uns hier geholfen habt.\n\nDie Schildwachen von Ashenvale werden Euch reichlich belohnen, wenn Ihr ihnen mitteilt, dass Gaxim und ich noch am Leben sind. Sagt ihnen, dass wir beim Aufhalten der Venture Company und der Heilung des Landes gute Fortschritte machen.\n\nSucht Tara Thenysil in Astranaar auf. Sie wird sich freuen, dass Ihr mit guten Neuigkeiten kommt.", sourceObjective = "Kehrt zu Schildwache Thenysil in Ashenvale zurück.", completion = "Danke, {name}. Ihr habt den Schildwachen einen großen Dienst erwiesen.\n\nIch freue mich, dass es Kaela... und auch Gaxim gut geht.\n\nIhr habt Eure Anerkennung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[1083] = { id = 1083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Geister", description = "Ich weiß nicht genau, was die Venture Company dem Tal angetan hat, aber es ist offensichtlich, dass es von den dortigen Kreaturen überwältigt wurde.\n\nSie steckten den Wald in Brand und benutzten ihre zerstörerischen Erfindungen, um so viel wie möglich des Tals zu zerstören.\n\nIn ihrer Dummheit haben sie jedoch auch noch etwas anderes entfesselt: brennende Geister, Elementare der Flammen, der Steine und der Wut.\n\nDas Land wird Elune nicht mehr lächeln sehen, solange diese Kreaturen frei herumstreifen.\n\nBringt mir ihre glimmenden Überreste, um mir zu zeigen, dass Ihr sie dezimiert habt.", sourceObjective = "Bringt Kaela Shadowspear im Steinkrallengebirge 8 glimmende Überreste der Feuerelementare des verbrannten Tals.", progress = "Als ich das verbrannte Tal zum ersten Mal sah, hätte ich fast geweint, {name}.", completion = "Die Überreste unseres Feindes... Eure Kraft hat uns gute Dienste geleistet, {name}. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[1084] = { id = 1084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verletzte Urtume", description = "Es scheint mir offensichtlich, dass die Beschützer des Tales - die Treants - irgendetwas damit zu tun hatten, dass die Venture Company zurückgeschlagen wurde. Leider wurden selbst diese einst so großen Wächter jetzt verderbt.\n\nGaxim glaubt, dass ihre Verderbnis irgendwie mit den Waffen zusammenhängt, die die Goblins während ihres Rückzuges benutzten.\n\nIch bat ihn, eine Probe von einem verwundeten Treant zu nehmen und sie zu untersuchen, um herauszufinden, ob das wirklich stimmt.\n\nBringt mir ein paar Späne, damit der Gnom mehr darüber herausfinden kann ...", sourceObjective = "Bringt Kaela Shadowspear im Steinkrallengebirge ein Stück eines zerfressenen Spans.", progress = "Ich habe das Gefühl, Gaxim wird einen Verwendungszweck für den Span finden, ungeachtet dessen, wofür die Venture Company ihn in der Vergangenheit benutzt haben mag.", completion = "Danke, {name}.\n\nDas sollte mehr als ausreichend sein, damit Gaxim herausfinden kann, wie die Treants verderbt wurden. Ich werde ihm das sofort bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1085] = { id = 1085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wache halten im Steinkrallengebirge", description = "Die Lage hier im Steinkrallengebirge ist offensichtlich düster, wenn Nachtelfen und Gnome zusammenarbeiten.\n\nDie Venture Company hat das Land verwüstet und ich habe einen Großteil meines Leben damit zugebracht, der Zerstörung ein Ende zu setzen.\n\nMan sollte Gaxim nicht vorschnell beurteilen; er versteht die Notwendigkeit, warum wir zusammenarbeiten müssen.\n\nWenn Ihr uns helfen wollt, sprecht zunächst mit Gaxim.\n\nEs tut mir Leid, dass ich Euch jetzt noch nicht mit guten Neuigkeiten zu Tara zurückschicken kann. Aber vielleicht schon bald.", sourceObjective = "Sprecht mit Gaxim.", completion = "Tückisch... tückisch und gefährlich ist das Land.\n\nAber ich bin hier, um den Nachtelfen zu zeigen, dass es durch die gute alte Ingenieurskunst und einen Tick Magie ein bisschen sicherer werden kann.\n\nWisst Ihr, der Magie total abzuschwören, würde den Nachtelfen nicht helfen - sie brauchen sie. Die Welt braucht sie. Und nimmt man Ingenieurskunst und Alchimie noch dazu, kann nichts mehr schiefgehen. Die Möglichkeiten sind endlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[1086] = { id = 1086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flugapparathafen", description = "Das Toxin ist bereit. Jetzt muss es nur noch ausgeliefert werden. Ihr, {name}, müsst es ausliefern.\n\nDie Venture Company muss irgendwelche Mittel und Wege haben, Nachrichten und leichte Fracht zwischen ihrem Hauptquartier und dem Betrieb im Steinkrallengebirge hin- und herzuschicken. Es könnte ein kleiner Flugplatz sein - nicht groß genug für einen Zeppelin, aber vielleicht für einen Flugapparat. Ihr müsst die Gebiete, die von der Venture Company kontrolliert werden, durchsuchen und diesen Flugplatz finden, falls er existiert. Solltet Ihr ihn finden, platziert das Toxin dort.\n\nPlatziert es und lauft, was Ihr könnt.", sourceObjective = "Bringt den Toxinvernebler zum Flugplatz der Venture Company und kehrt dann zu Apothekerin Zamah zurück.", completion = "Ihr habt den Flugplatz gefunden? Gut gemacht, {name}! Die Goblins waren sicher ziemlich überrascht von Eurer Lieferung! Hoffen wir, dass das Toxin den Weg zu ihrem Hauptquartier findet.\n\nIhr habt Eurem Volk gute Dienste geleistet, und ich rate Euch, dass Ihr Euch nicht mit Schuldgefühlen quält, die Ihr vielleicht wegen der Vergiftung der Venture Company hegt. Sie hat noch viel Schlimmeres verdient.\n\nUnd wenn die Verlassenen ihren Verbündeten noch ein Körnchen Wissen vermitteln können, dann dies hier:\n\nScheut Euch nicht, dunkle Wege zu begehen... wenn Euch solche Wege zum Sieg führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1087] = { id = 1087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarius' Vermächtnis", description = "Ihr könnt Euch nicht vorstellen, wie groß mein Hass auf dieses elende Land ist. Solche Leute wie Cenarius und die Kaldoreidruiden auf dem Gipfel benutzen ihre lächerlichen Mächte, um den Magiefluss zu stoppen, sogar noch so weit von ihrem lächerlichen Besitz entfernt ... ihren geliebten Wäldern.\n\nIch wünschte, ich könnte nach Jaedenar zurückkehren und im Fluss der Magie baden, aber mein Meister erlaubt mir erst dorthin zurückzukehren, wenn meine Arbeit getan ist.\n\nZweifellos liebt Ihr die Nachtelfen und ihre Verbündeten genauso wenig wie ich. Helft mir, dann haben wir vielleicht beide etwas davon.", sourceObjective = "Tötet für Brealyn Firehand in Sonnenfels 4 Söhne des Cenarius, 4 Töchter des Cenarius und 4 cenarische Botaniker.", progress = "Kanalisieren von Magie ist, als würde man mit einem löcherigen Eimer Wasser aus einem Brunnen schöpfen.", completion = "Ich kann es bereits spüren... ja... oh süße Macht... die rauschende Flut. Die Kaldorei sind töricht, dass sie die Geschenke dieser Welt verschmähen und das Durchströmen der Magie unterbinden, die singend durch unsere Adern fließt.\n\nWas ist das Leben doch für ein fahler Abklatsch ohne ihre brennende Umarmung!", sourceObjectiveStatus = "unverified-source-field" }
quests[1088] = { id = 1088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordanus", description = "Sie dachten, dass man den Fluss der Magie zum Erliegen bringen könnte. Sie haben sich geirrt. Sie dachten, dass sie Ordanus verstecken könnten, aber ich will seinen Kopf!\n\nDie Magie gewährt mir Durchblick. Ja... da ist er. Ein Scheideweg... auf dem Wipfel eines großen Baumes in Ashenvale. Ein Name... Raynewood. Einer der ältesten Söhne des Waldgottes. Sie haben ihn aus dem Wipfel geschleust, bevor ich ihn finden konnte, aber ihm läuft langsam die Zeit davon.\n\nBringt ihn mir, dann teile ich ein großes Geschenk mit Euch.", sourceObjective = "Bringt Braelyn Firehand in der Nähe von Sonnenfels Ordanus' Kopf.", progress = "Als mein Meister mich auf den Gipfel des Steinkrallengebirges beorderte, erwartete ich, dass ich einfach nur die Nachtelfen beseitigen musste, die in den heiligen Ruinen unseres antiken Tempels von Azshara herumwimmelten und seine Heiligkeit plünderten... aber Ordanus schlüpfte mir zwischen den Fingern hindurch.", completion = "Ich kannte Ordanus einst, aber das ist schon lange her. Er besaß die Arroganz seiner Art und stellte sich selbst noch über die Hochgeborenen.\n\nJetzt trägt er seinen Kopf nicht mehr so hoch, nicht wahr, {name}?\n\nIch versprach Euch eine Belohnung, und die sollt Ihr haben. Kommt mit mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[1089] = { id = 1089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Höhlenbau", description = "Die Druiden errichteten den Krallenbau auf dem Steinkrallengipfel, in dem sie viele mächtige Gegenstände aufbewahren.\n\nSie haben sich ein komplexes Schema ausgedacht, damit sie nicht in die falschen Hände gelangen.\n\nGlücklicherweise konnte ich einem von ihnen... ein paar Details entlocken.\n\nVersteckt in einer kleinen Laterne am Eingang des Baus werdet Ihr den Torhüterschlüssel finden. Damit könnt Ihr die Behälter öffnen, die über den ganzen Bau verteilt sind. Mit den Gegenständen aus diesen Behältern wiederum könnt Ihr ihren Hort öffnen, der sich in einem der zentralen Bereiche befindet.", sourceObjective = "Begebt Euch zum Höhlenbau auf den Steinkrallengipfel. Benutzt den Torhüterschlüssel, um Euch die versteckten Gegenstände der Druiden zu besorgen. Benutzt diese Gegenstände, um den Hort des Krallenbaus zu öffnen.", progress = "In den Stein sind drei Schlüssellöcher eingearbeitet.", completion = "Als die drei Schlüssel in die jeweiligen Öffnungen gesteckt werden, tauchen inmitten des glimmenden Lichtes ein paar Gegenstände auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[1090] = { id = 1090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzos Befehle", description = "Wisst Ihr, ich war hier einst die zweitwichtigste Person. Das hat sich alles geändert, als Gerenzo hier übernahm. Hat meinen Boss Ziz Fizziks gefeuert und mich zum Arbeiten nach unten in die Minen geschickt. Ziz sagte mir aber, dass ich hier bleiben und Informationen sammeln solle. Sein neuer Boss wird uns gut bezahlen, wenn wir rausfinden, was Gerenzo plant.\n\nEgal, was ich weiß ist, dass Gerenzo befohlen hat, dass Riesenmengen von diesem gold-grünen Erz abgebaut werden sollen. Ich hol Euch eine Probe, damit Ihr sie Ziz bringen könnt, aber Ihr müsst Euch vor Patrouillen hüten, während ich es hole.", sourceObjective = "Nehmt das rätselhafte Erz, nachdem Piznik es fertig abgebaut hat.", completion = "Danke, {name}. Sah für einen Moment ziemlich riskant aus und wir haben vielleicht etwas zu viel Aufmerksamkeit auf uns gelenkt.\n\nDas Wichtigste ist aber, dass wir eine Erzprobe haben, die wir so schnell wie möglich zu Ziz bringen sollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1091] = { id = 1091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaelas Update", description = "{name}, bringt Kaela diese Briefe. Ich bin mir sicher, dass sie das interessiert. Oder zumindest die Schildwachen.\n\nErzählt Ihr unbedingt, wie erfolgreich wir waren und dass wir es ohne ein bisschen Magie nie geschafft hätten.", sourceObjective = "Bringt Kaela Shadowspear die Dokumente der Venture Company.", progress = "Ja, {name}? Was kann ich für Euch tun?", completion = "Das ist in der Tat interessant.\n\nIhr und Gaxim habt das sehr gut gemacht, {name}. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[1092] = { id = 1092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzos Befehle", description = "Ich glaube, ich sollte auch langsam darüber nachdenken, hier zu verschwinden. Es wird nicht lange dauern, bis die da oben erfahren, was hier gelaufen ist, und ich bin sicher, dass die keinen großen Wert darauf legen, mich wiederzusehen.\n\nIch schleich mich raus und treff mich mit Ziz. Hoffentlich kann er mir einen neuen Job besorgen!\n\nIch werde versuchen, hier ein bisschen Ordnung zu schaffen, aber Ihr solltet die Erzprobe sofort zu Ziz bringen. Er sagte mir, dass er irgendwo an der Westseite der Scherwindklippe sein Lager aufgeschlagen hat. Viel Glück.", sourceObjective = "Bringt Ziz Fizziks im Steinkrallengebirge das unbekannte Erz.", progress = "Kann ich Euch irgendwie helfen?", completion = "Ahhh, ich wusste, dass es richtig war, Piznik zu sagen, dass er dort bleiben soll. Die Ingenieure in Undermine werden sich das bestimmt unbedingt ansehen wollen...\n\nNatürlich werde ich ein kleines Stückchen für mich behalten, aber das müssen sie ja nicht unbedingt wissen, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[1093] = { id = 1093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superschnitter 6000", description = "Schrecklich, was die Venture Company hier getan hat, was? Was haben die sich dabei gedacht? Eine Goblin-Firma, die einen Gnom anheuert!\n\nEin Glück für mich, dass Sputtervalve ein Genie erkennt, wenn es vor ihm steht. Hat mich eingestellt, gleich nachdem ich gefeuert wurde!\n\nSagte mir, sie wollten eine riesige Holzfällmaschine bauen, und Sput möchte, dass ich für ihn die Pläne dazu stehle. Leider wird Gerenzo - dieser verdammte Gnom - mich umlegen, sobald er mich sieht ... würdet Ihr vielleicht die Pläne für mich stehlen? Ihr solltet sie bei einem ihrer Maschinenführer finden.", sourceObjective = "Besorgt für Ziz Fizziks im Steinkrallengebirge die Blaupausen für den Superschnitter 6000.", progress = "Habt Ihr die Pläne gefunden? Ich brenne darauf, meinen neuen Boss zu beeindrucken. Hoffentlich überzeugt ihn das von meiner Loyalität - soweit man ihn überhaupt überzeugen kann... Goblin-Ehre, Ihr wisst schon. Vielleicht ist er dann geneigt, sich mein ziemlich beeindruckendes Genie zu Nutze zu machen.", completion = "He, ist es das, für was ich es halte? Großartig!\n\nDann sehen wir mal. Ähhh... wie soll denn das jemand verstehen... versteh einer die Denkweise von Gnomen. Ich sag Euch was, ich wundere mich, dass sie Räder bauen können, ganz zu schweigen von diesen Flugapparaten, die sie so sehr lieben.", sourceObjectiveStatus = "unverified-source-field" }
quests[1094] = { id = 1094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Instruktionen", description = "In diesem Umschlag befinden sich alle Informationen, die ich mir schnappen konnte, bevor sie mich vor die Tür setzten... Interne Dokumente der Venture Company, ein paar Handbücher, technisches Zeugs... Oh, und natürlich die Blaupausen für den Superschnitter 6000.\n\nSputtervalve hat sich bei Ratchet im Brachland niedergelassen. Sollte nicht schwer sein, ihn zu finden. Er ist ein kleiner, grüner Kerl.", sourceObjective = "Bringt Sputtervalve im Brachland den versiegelten Umschlag.", progress = "Hallo! Wie kann ich Euch helfen?", completion = "Fizziks, hä? Kann nicht sagen, dass ich ihm traue, aber diese Informationen scheinen ganz brauchbar. Was würde ich darum geben, die Venture Company endlich los zu sein.\n\nDie haben sich allerdings ein paar recht gute Maschinen ausgedacht... Ich kann nicht bestreiten, dass wir von ein paar Verbesserungen, die sie entwickelt haben, ganz gut profitiert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[1095] = { id = 1095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Instruktionen", description = "Die Tatsache, dass die Venture Company diesen Gnom angestellt hat, hat in Undermine für einiges Aufsehen gesorgt. Die Handelsbarone finden es nicht gut, dass Razdunk mit Gerenzo gemeinsame Sache macht.\n\nRiddlevox hat mich gebeten, mich um das Problem zu kümmern und ich bin mir sicher, dass einer oder zwei dieser Handelsbarone ihn dazu angewiesen haben. Natürlich hat mir der Direktor das nicht erzählt. Sagen wir einfach, ich hätte so eine Ahnung.\n\nWie dem auch sei, Gerenzo muss entfernt werden und es wäre eine passende Prüfung, das Fizzik erledigen zu lassen.", sourceObjective = "Bringt Ziz Fizziks im Steinkrallengebirge die neuen Befehle.", completion = "Gerenzo eliminieren? Also das ist eine Sache, gegen die ich nichts einzuwenden habe.\n\nGnome an sich sind ja schon schlimm genug, aber was ich alles über Gerenzo gehört habe, schlägt dem Fass den Boden aus. Offenbar war er einer der leitenden Ingenieure in Gnomeregan, wo er an einem Geheimprojekt mitwirkte - wir konnten Dun Morogh nie gut genug infiltrieren, um genauere Einzelheiten darüber herauszufinden. Es war ein Fehlschlag. Unseren Berichten nach soll das, was immer es auch war, ihnen buchstäblich um die Ohren geflogen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1096] = { id = 1096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzo Wrenchwhistle", description = "Ich habe Gerenzo einmal getroffen, und lasst mich Euch eines sagen, er ist nicht gerade eine Schönheit. Sein Fleisch sieht aus, als würde es faulen. Dazu hat er noch überall an seinem Körper Metallteile und Zeugs angeflanscht und sogar einige seiner Körperteile durch mechanische ersetzt.\n\nNordöstlich von hier, weit oberhalb des Felskesselsees in der Nähe des Wasserrades beaufsichtigt Gerenzo die gesamte Stätte. Ich könnte mich unmöglich bis da hinauf durchkämpfen und schon gar nicht mich mit Gerenzo anlegen ... Aber Ihr seht aus, als könntet Ihr es schaffen.\n\nWenn Ihr ihn für mich tötet, soll es Euer Schaden nicht sein!", sourceObjective = "Bringt Ziz Fizziks im Steinkrallengebirge Gerenzo Wrenchwhistles mechanischen Arm.", progress = "Sputtervalve wird einen Beweis für Gerenzos Tod haben wollen. Ich glaube, dieser mechanische Arm wird reichen.", completion = "Man sehe sich dieses Ding an... so was kann sich auch nur ein Gnom ausdenken. Ich kann nicht verstehen, warum man sich einen Arm abschneidet und durch so was ersetzt, wenn man doch beide Arme behalten und einfach einen dritten ansetzen könnte!\n\nGnome, ich sag's Euch...\n\nZumindest ist Gerenzo jetzt außer Gefecht. Hoffentlich ist das Beweis genug und Sputtervalve bringt mich in einer der Tüftlerverband-Werkstätten in Gadgetzan oder sogar Undermine unter.", sourceObjectiveStatus = "unverified-source-field" }
quests[1097] = { id = 1097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elmores Aufgabe", description = "In Stormwind gibt es einen Zwergen-Waffenschmied namens Grimand Elmore, der mal angedeutet hat, dass er Hilfe bei einer Lieferung bräuchte. Ich glaube, er möchte ein Paket in seine Heimat im Norden schicken.\n\nIhr habt da ein paar schöne kräftige Beine! Falls Ihr also an ein wenig Beinarbeit interessiert seid, sprecht mit Grimand. Wir könnten Euch hier unten brauchen, aber wir müssen auch unsere Bande mit den Zwergen stärken.\n\nIhr findet Grimand Elmore im Waffenladen im Zwergendistrikt von Stormwind, im nordöstlichen Teil der Stadt.", sourceObjective = "Sprecht mit Grimand Elmore.", completion = "Ihr seid hier, um mir mit meiner Lieferung zu helfen? Sehr gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[1098] = { id = 1098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todespirscher in Shadowfang", description = "Als Vorbereitung auf einen Überfall auf Shadowfang wurden zwei Todespirscher in die Burg geschickt, um Informationen zu sammeln. Das war vor mehreren Tagen und sie sind noch nicht wieder zurück, aber wir brauchen ihren Bericht, wenn wir auf einen erfolgreichen Angriff hoffen wollen!\n\nDas ist Eure Aufgabe, {name}. Geht zu Burg Shadowfang im Süden und sucht die Todespirscher Adamant und Vincent. Findet sie und helft ihnen, falls es erforderlich ist.\n\nDiese Mission ist nicht nur gefährlich, sondern auch lebenswichtig, {name}. Versagt bitte nicht.", sourceObjective = "Sucht die Todespirscher Adamant und Vincent.", completion = "Vincents Körper liegt zerschmettert und leblos da.\n\nTodespirscher Adamant wird Hadrec zwar seinen Bericht schicken... aber was immer Vincent zusätzlich noch wusste, wird für immer sein Geheimnis bleiben.\n\nSeine Hand jedoch umklammert ein kleines Stück Plunder...", sourceObjectiveStatus = "unverified-source-field" }
quests[1099] = { id = 1099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Goblins haben gewonnen!" }
quests[1100] = { id = 1100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lonebrows Tagebuch", description = "Ihr öffnet langsam das verwitterte Tagebuch des Henrig Lonebrow...", sourceObjective = "Lest Henrig Lonebrows Tagebuch.", progress = "So bekümmert, wie Ihr ausseht, würde ich sagen, dass etwas nicht stimmt...", completion = "Ihr sagt, Ihr habt das Tagebuch bei einem verstorbenen Zwerg gefunden? Gebt mir einen Moment Zeit, um durch die Seiten zu stöbern...", sourceObjectiveStatus = "unverified-source-field" }
quests[1101] = { id = 1101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Greisin des Krals", description = "Armer Heralath! Und dieser Zwerg... Lonebrow. Was war er doch für eine mutige Seele.\n\nSo viel Heldenmut darf nicht umsonst gewesen sein. Diese Greisin... Charlga Razorflank... muss aufgehalten werden.\n\nSicher, es wird gefährlich werden, den Kral zu bespitzeln. Wir haben keine Zeit, um Darnassus zu informieren. {name}, stellt eine Gruppe zusammen, um die Greisin zu erschlagen.\n\nBringt mir Razorflanks Medaillon zum Beweis ihres Ablebens.", sourceObjective = "Bringt Falfindel Waywarder in Thalanaar Razorflanks Medaillon.", progress = "Solange Charlga Razorflank im Kral von Razorfen Truppen rekrutiert, ist dieses Land in großer Gefahr.", completion = "Der Greisin wurde der Garaus gemacht. Das sind phantastische Neuigkeiten, {name}.\n\nIn diesen gefährlichen Zeiten ist es erfrischend, jemanden zu sehen, der so mutig ist wie Ihr.\n\nDa Razorflanks Diener beseitigt sind, können wir jetzt unsere Studien in diesem Gebiet fortsetzen. Vielleicht erfahren wir ja jetzt mehr darüber, was die Ruhestätte Agammagans verderbt hat.\n\nIch fürchte allerdings, dass die Antwort auf diese Frage auch mit Verrat zu tun hat ...", sourceObjectiveStatus = "unverified-source-field" }
quests[1102] = { id = 1102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schreckliches Schicksal", description = "Es war edel von unserem Anführer Cairne, unser Volk hier in Thunder Bluff zu vereinen.\n\nIch kann jenen jedoch nicht vergeben, die uns so leicht aus dem Land unserer Vorfahren vertrieben haben. Jahrhundertelang lebte mein Volk im südlichen Brachland. Das Land war uns heilig. Aber wir wurden von zahllosen Feinden vertrieben.\n\nEin schreckliches Schicksal erwartet die Greisin Charlga Razorflank, die im Kral von Razorfen eine abscheuliche Armee zusammenzieht.\n\nBringt mir Razorflanks Herz, damit ich in Frieden sterben kann, {name}.", sourceObjective = "Bringt Auld Stonespire in Thunder Bluff Razorflanks Herz.", progress = "Sobald ich weiß, dass die elenden Bestien des Krals von Razorfen aus ihrem elenden Unterschlupf vertrieben wurden, kann ich in Frieden ruhen, in dem Wissen, dass Rache geübt wurde. \n\nHabt Ihr die Stacheleber aus dem Kral vertrieben? Bringt Ihr mir gute Neuigkeiten in Form von Razorflanks Herz?", completion = "Wie ich sehe, kennt der widerliche Stamm des Krals von Razorfen jetzt den Schmerz meines Volkes. Das geschieht den elenden Bestien recht.\n\nJemanden von heiligem Boden zu vertreiben ist eine Sünde, die nur durch die schlimmste Form der Rache gesühnt werden kann.\n\nDanke, {name}, dass Ihr mir in diesen Zeiten der Not geholfen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1103] = { id = 1103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Seid gegrüßt, <Bruda/Schwesta>! Seid auch Ihr gekommen, um das Wasser hier zu läutern und Islen Euer Wissen zu beweisen?\n\nIch habe den verderbten Wassergeist gerade selbst bezwungen und bin grad dabei, die Armschienen un' verbleibenden Wassertropfen in die Kohlenpfanne zu geben.\n\nWas'n das? Ahhh. Tiev versteht nur zu gut, wenn wat falsch läuft. Tja, Tiev kann Euch echt helfen, wenn Ihr den Wassergeist wieda seh'n wollt.\n\nBringt mir 'in Wassersapta von Islen als Beweis, dass Ihr bereit seid, un' ich bin bereit, meinen Teil beizutrag'n.", sourceObjective = "Bringt Tiev Mordune im Silberwald ein Wassersapta, wenn Ihr nicht mit der schwachen Wassermanifestation gesprochen habt.", progress = "Habt Ihr dat Sapta, Bruda?\n\nIch kenne noch jemanden, der Probleme hatte, nachdem er den verderbten Wassergeist besiegt hadde - hat wohl zu lange gewartet und kam für seinen Jeschmack zu schnell aus der Geisterwelt. Würde nich gern seh'n, dass dat noch wem passiert, also werde ich hier noch 'ne Weile wart'n und sichergehen, dat sonst keiner meine Hilfe braucht.", completion = "Ahhh, dann seid Ihr bereit...\n\nIch werde dann mal meine Sachen in die Kohlenpfanne leg'n und Ihr könnt denn auch mit'm Geist red'n.\n\nUn' macht Euch keine Sorg'n darüber, mit'm Sapta in die Geisterwelt zu seh'n... der alde Tiev kennt'n Trick oder zwei zur Funktion der Saptamagie.\n\nKommt schon, begebt Euch mit mir zum Schrein und lasst uns zusamm'n mit den Geistern sprech'n, Bruda.", sourceObjectiveStatus = "unverified-source-field" }
quests[1104] = { id = 1104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salziges Gift", description = "Ich habe so viele Pläne für unseren Raketenwagen! So viele! Und ich muss sie alle ausprobieren!!!\n\nIch arbeite gerade an einem neuen Treibstoff; an einem, der wirklich, wirklich, wirklich heiß ist! Die Mixtur stimmt zwar noch nicht ganz, aber ich glaube, ich weiß, was noch fehlt...\n\nDie Skorpide, die die schimmernde Ebene durchwandern, haben ein Gift mit Unmengen Salz darin. Es ist einzigartig! Und es ist genau das, was ich brauche!\n\nBringt mir das Gift und vertraut mir: unser Wagen wird fliegen!", sourceObjective = "Bringt Fizzle Brassbolts in der schimmernden Ebene 6 Einheiten salziges Skorpidgift.", progress = "Hi, hi, hi! Habt Ihr das Gift???", completion = "Toll! Dieses Gift wird wunderbar funktionieren! Danke, {name}!\n\nJetzt muss ich ihn nur noch einkochen lassen, Skipper-Otomer und einen Nagakatalysator hinzufügen, und... Mist! Wo sind meine Notizen?!", sourceObjectiveStatus = "unverified-source-field" }
quests[1105] = { id = 1105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehärtete Schalen", description = "Mein Bruder arbeitet an einem neuen Treibstoff für seinen Raketenwagen. Er ist brillant, ehrlich. So brillant, dass... Ich glaube, der neue Treibstoff, den er da entwickelt, ist stark genug, um sich durch das Chassis des Wagens zu fressen!\n\nIch würde gern die Treibstofftanks verstärken, bevor das passiert.\n\nDie Schildkröten draußen auf der Ebene haben sehr starke Panzer. Ich möchte daraus neue Tanks für unseren Raketenwagen bauen. Tanks, die den neuen Treibstoff meines Bruders aushalten.\n\nIhr seht mir verantwortungsbewusst genug aus. Holt Ihr mir solche Panzer?", sourceObjective = "Bringt Wizzle Brassbolts in der schimmernden Ebene 9 gehärtete Schildkrötenpanzer.", progress = "Mein Bruder macht Fortschritte mit seinem neuen Treibstoff, und das macht mir Sorgen. Ich muss so bald wie möglich mit meiner Arbeit mit einem Schildkrötenpanzer-Treibstofftank beginnen!\n\nHabt Ihr die Panzer schon, {name}?", completion = "Ihr habt sie! Danke, {name}!\n\nWow, diese Panzer sind härter als ich dachte! He, ich ruiniere mir bestimmt einen ganzen Kasten voller Werkzeuge, wenn ich daran arbeite!", sourceObjectiveStatus = "unverified-source-field" }
quests[1106] = { id = 1106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Martek der Verbannte", description = "Ich entwickle einen neuen Motor, mit dem der Wagen so schnell wie der Wind wird! Schnell genug, um zu fliegen, ich weiß es! Ich muss nur ein paar Kolben herstellen, die sehr, sehr große Belastungen aushalten. All meine bisherigen Versuche sind fehlgeschlagen, weil ich die Kolben einfach nicht robust genug herstellen kann!\n\nAber es gibt jemanden, der wissen könnte, wie es geht.\n\nSein Name ist Martek der Verbannte. Er ist ein großartiger Schmied und weiß mehr über Metall als alle anderen. Bringt ihm diesen Brief, ich weiß, dass er helfen kann!\n\nAber er lebt weit, weit weg - in Azeroth, im Ödland, in einem Lager, zusammen mit einem Goblin!\n\nSucht ihn!", sourceObjective = "Bringt Martek dem Verbannten im Ödland Fizzles Brief.", progress = "Tja, da habt Ihr mich also gefunden. Schön für Euch.\n\nSeid Ihr wegen der Axt hier, die ich für Gath'Ilzogg geschmiedet habe? Oder seid Ihr hier, um die Ehre der Herzogin Pamay zurückzufordern?\n\nWisst Ihr, es ist mir völlig egal, warum Ihr hier seid. Wenn Ihr hier seid um zu kämpfen, dann bringen wir's hinter uns ...", completion = "Fizzle hat Euch geschickt? Also das ändert die Sachlage! Natürlich helfe ich Euch. Fizzle und sein Bruder sind zwei der wenigen Leute, die mich nicht tot sehen wollen!\n\nFizzle will also Kolben herstellen, was? Kolben, die stark genug sind, um großen Belastungen standhalten zu können; was auch immer ihm vorschweben mag. Und wie ich Fizzle kenne, wird sein neuer Wagen ein Vulkan auf Rädern!", sourceObjectiveStatus = "unverified-source-field" }
quests[1107] = { id = 1107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verkrustete Schwanzflossen", description = "Unser Raketenwagen ist das schnellste, was es auf der Ebene gibt! So schnell, dass... ich fürchte, die Reibung reißt ihn auseinander!\n\nUm das zu verhindern, muss ich einen Stoff entwickeln, der die beweglichen Teile des Wagens überzieht. Er muss hart sein, aber nicht spröde, und er muss resistent gegen Salzkorrosion sein, sonst wird der Wagen, während er sich in der schimmernden Ebene befindet, zerfressen.\n\nHabt Ihr schon mal vom finsteren Riff gehört, {name}? Es liegt vor der Küste des Schlingendorntals. Dort leben Salzschuppenmurlocs, deren Schwanzflossen unabdingbare Zutaten zu meinem Stoff sind.", sourceObjective = "Bringt Fizzle Brassbolts in der schimmernden Ebene 10 verkrustete Schwanzflossen.", progress = "Habt Ihr die Schwanzflossen? Wenn ich unseren Wagen nicht vor seinem eigenen Tempo schützen kann, wird er bei den Rennen nicht lang halten.", completion = "Danke, {name}! Wenn ich die zermahlen und mit ein paar anderen Zutaten vermischt habe, ist mein Stoff fertig. Danach wird der Wagen vor seinem eigenen Tempo sicher sein.\n\nSofern er nicht mit irgendwas zusammenstößt...", sourceObjectiveStatus = "unverified-source-field" }
quests[1108] = { id = 1108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Indurium", description = "Ich bin nicht hier draußen, weil ich mich vor Leuten verstecken will. Das Ödland ist reich an Metall, {name}, wenn man den Mut hat, es sich zu holen.\n\nDas Metall heißt Indurium, und wie das Schicksal so spielt, soll es angeblich hohen Widerstand gegen Hitze und Belastung bieten. Das könnte genau das Richtige für Fizzles Wagen sein.\n\nAber wir sollten sichergehen. Bringt mir eine Indurium-Probe, dann kann ich seine Eigenschaften testen.\n\nEchtes Induriumerz liegt tief drinnen in Uldaman, aber die Steingrufttroggs des Ödlandes tragen manchmal Späne davon mit sich herum. Bringt mir diese Späne.", sourceObjective = "Bringt Martek dem Verbannten im Ödland 10 Induriumspäne.", progress = "Habt Ihr Induriumspäne gefunden, {name}? Meine Schmiede ist aufgeheizt und bereit, sie zu testen.", completion = "Ah ja, ausgezeichnet. Geben wir sie ins Feuer und sehen wir, wie sie sich machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[1109] = { id = 1109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go, Go, Guano!", description = "Wie Ihr seht, {name}, befassen wir uns mit einigen sehr... interessanten Experimenten in der Königlichen Apothekervereinigung.\n\nAls Meister hier ist es meine Aufgabe, die anspruchsvollsten unserer alchimistischen Versuche zu überwachen. So viel Arbeit und nur so wenig Zeit!\n\nIhr seht weit gereist aus, {class}. Vielleicht könnt Ihr mir helfen.\n\nIch brauche eine rare Substanz. Es ist dieses widerliche Zeug, das von einer raren Fledermausart stammt, die man nur in einem Dreckloch namens Kral von Razorfen findet. Bringt mir den Guano der Kral-Fledermäuse, damit wir mit unserer Arbeit beginnen können...", sourceObjective = "Bringt dem Apothekermeister Faranell in Undercity 1 Häufchen Kral-Guano.", progress = "Ah, wie ich sehe, seid Ihr zurückgekehrt. Konntet Ihr etwas Kral-Guano beschaffen?", completion = "Ausgezeichnet! Das ist genau das, was wir brauchen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1110] = { id = 1110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raketenwagenteile", description = "Hi-hi, bei den vielen Rennen, die hier stattfinden, ist es nicht verwunderlich, wenn dabei ein paar Unglücksfälle passieren. Wenn man sich in der schimmernden Ebene umschaut, sieht man ständig Spuren vergangener Unfälle - überall liegen Teile von Raketenwagen herum.\n\nUnd diese Teile bedeuten für die Gnome und Goblins bares Geld. Sie suchen ständig nach weiteren neumodischen Apparaten, um sie an ihre Autos anzubauen.\n\nAlso zieht los und bringt mir die Teile. Bringt mir einen Haufen und ich werde Euch gut bezahlen.", sourceObjective = "Bringt 30 Raketenwagenteile zu Kravel Koalbeard in der schimmernden Ebene.", progress = "{name}, seid Ihr in der Ebene gewesen? Habt Ihr mir die Ladung Teile gebracht, die ich wollte?", completion = "Boah, seh sich einer das an! Es sind ein paar echt gute Sächelchen in diesem Schrotthaufen. Ich bin sicher, die kann ich für ein schönes Sümmchen verpfänden.\n\nUnd... sehe ich da ein zerquetschtes Ohr zwischen zwei Metallteilen??? Autsch! He, mit diesem Piloten möchte ich echt nicht tauschen!\n\nDanke, {name}. Hier ist Eure Bezahlung. Und hier noch ein kostenloser Rat...\n\nWenn man verbissen genug sucht, kann man immer Kapital aus der Tragödie eines anderen schlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1111] = { id = 1111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werftmeister Dizzywig", description = "Mein Job ist es, den Leuten zu beschaffen, was sie möchten, und diese Gnome da drüben möchten Teile bestellen. Ihre Teile wurden vor einer Woche nach Ratchet geschickt, aber es war mir nicht möglich, dorthin zu reisen.\n\nAlso, seid Ihr bereit, mir die Kleinarbeit abzunehmen? Geht nach Ratchet und gebt diese Teile-Bestellung an Werftmeister Dizzywig - er wird wahrscheinlich bei den Docks sein.\n\nWenn Ihr das macht, habe ich weitere Aufträge für Euch.\n\nAufträge, bei denen eine Menge Profit rausspringen kann ...", sourceObjective = "Bringt Kravels Teile-Bestellung zu Werftmeister Dizzywig in Ratchet.", progress = "Sprecht! Sagt mir, ladet Ihr aus oder ein?", completion = "Oh, ja. Teile für Kravel. Schön, dass Ihr hier seid. Diese Dinger liegen seit Tagen hier, ich fürchtete schon, sie würden Rost ansetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1112] = { id = 1112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teile für Kravel", description = "Hier ist Kravels Paket, {name}. Und wenn Ihr es zustellt, sagt ihm bitte... wenn er weitere spezielle Lieferungen möchte, dann muss er bezahlen!", sourceObjective = "Bringt Kravels Teile zu Kravel Koalbeard in der schimmernden Ebene.", progress = "Seid Ihr in Ratchet gewesen und habt die Teile bekommen?", completion = "Prima, Ihr habt sie! Jetzt müssen wir sie zu den Gnomen bringen. Aber vorher...\n\nNehmen wir einen kleinen Gegenstand heraus...", sourceObjectiveStatus = "unverified-source-field" }
quests[1113] = { id = 1113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzen des Eifers", description = "Warum ich eine rare Art von Guano benötige, fragt Ihr Euch? Also bei diesem Experiment möchte ich wissen, wie zwei diametral entgegengesetzte chemische Substanzen aufeinander wirken, besonders wenn beide mit einem höchst toxischen Agens kombiniert werden, um die ... garstigsten Resultate zu erzielen.\n\nIn der Nordostspitze von Tirisfal liegt das Scharlachrote Kloster. Dort versammeln sich die wahnsinnigen Jünger des Scharlachroten Kreuzzuges. Tötet sie und bringt mir ihre übereifrigen Herzen.\n\nUnser Gebräu wird äußerst tückisch sein!", sourceObjective = "Apothekermeister Faranell in Undercity möchte 20 Herzen des Eifers.", progress = "Seid Ihr vom Scharlachroten Kloster zurückgekehrt? Ich brauche viele Herzen für dieses aufregende Experiment!\n\nZweifellos werden Varimathras und die dunkle Fürstin ebenfalls erfreut sein, den Scharlachroten Abschaum loszuwerden...", completion = "Was für eine Unmenge an Gekröse Ihr mir da bringt, {name}! Eure Bemühungen waren exzellent!", sourceObjectiveStatus = "unverified-source-field" }
quests[1114] = { id = 1114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für die Gnome", description = "Jetzt, wo ich habe, was ich brauche, gebt diese Teile Fizzle Brassbolts. Er wartet schon lange darauf - ich bin sicher, das kleine Teil, das ich behalten habe, wird er nicht vermissen...\n\nUnd ich würde ihn auch nicht darauf hinweisen. Es war klein und wertlos.\n\nGlaubt mir.", sourceObjective = "Bringt die empfindlichen Autoteile zu Fizzle Brassbolts.", progress = "Habt Ihr denn etwas für mich? Großartig! Lasst sehen!", completion = "Da sind sie ja! Meine Hydro-Ratschen und Repetierbolzen! Diese genügen voll und ganz. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[1115] = { id = 1115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gerüchteverbreiter", description = "Jetzt, da wir diesen Dienst für die Gnome geleistet haben, wird es Zeit, den Goblins einen Gefallen zu tun! \n\nIch habe gehört, dass der Goblin-Rennfahrer Nazz Steamboil diesen Namen nicht immer getragen hat. Ich frage mich, weshalb er ihn änderte. Ob es wohl ein Geheimnis ist und... wie viel ihm dieses Geheimnis wert ist.\n\nWenn jemand die Wahrheit kennt, dann Krazek aus Booty Bay an der Südspitze des Schlingendorntals. Sprecht mit Krazek und fragt ihn nach unserem Goblin-Rennfahrer.\n\nWenn Ihr nützliche Informationen aus ihm herausbekommt, springt vielleicht Profit für uns raus.", sourceObjective = "Sprecht mit Krazek in Booty Bay.", completion = "Ihr wollt etwas über Nazz Steamboil wissen? Er ist Rennfahrer draußen in der schimmernden Ebene, nicht?\n\nKlar kann ich über den was rauskriegen... aber leicht wird das nicht. Und es dauert.\n\nUnd kostet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1116] = { id = 1116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traumstaub im Sumpf", description = "Es ist ein großer Gefallen, diese Informationen über Nazz zu beschaffen, {name}. Ja, ein großer Gefallen. Aber Ihr habt den weiten Weg von der schimmernden Ebene auf Euch genommen... seid Ihr bereit, noch etwas weiter zu reisen?\n\nIhr könntet doch etwas für mich besorgen, während ich Kontakt mit meinen Informanten aufnehme, hm?\n\nHmm... was könnte es denn sein? Wie wäre es mit Traumstaub von den Großdrachenwelpen und Wyrmkin aus den Sümpfen des Elends? Ja, ich hätte gern etwas Traumstaub für meinen Schnupftabakbeutel!\n\nBringt ihn mir, {name}, und ich gebe Euch die gewünschten Informationen.", sourceObjective = "Bringt 10 Körnchen Traumstaub zu Krazek in Booty Bay.", progress = "Schon wieder hier? Habt Ihr meinen Traumstaub?", completion = "Seht Euch das an. Ihr habt den Traumstaub gefunden!\n\nUnd Wie hat Euch der Sumpf gefallen, {name}? Ist nicht leicht, dort eine warme Mahlzeit zu bekommen, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[1117] = { id = 1117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerüchte für Kravel", description = "Ich musste einige Gefälligkeiten erweisen, eine rare Flasche Elfenwein herschenken und mir selbst einiges zusammenreimen! Aber ich habe die Informationen, die Ihr sucht.\n\nHier, ich habe einen Brief mit einigen sehr interessanten Infos über Euren Freund Nazz Steamboil verfasst. Macht damit, was Ihr wollt - für mich wäre es zu gefährlich, ihn zu benutzen.\n\nSagt nur keinem, woher Ihr das habt!", sourceObjective = "Bringt die Goblin-Gerüchte zu Kravel Koalbeard in der schimmernden Ebene.", progress = "Habt Ihr etwas über Nazz Steamboil? Etwas, das er unbedingt geheim halten möchte?", completion = "Ach nein! Das ist interessant... sehr interessant. He, vielleicht sollte ich mich vor dem Goblin-Rennfahrer verneigen, wenn ich ihn das nächste Mal sehe.\n\nDas ist eine Menge wert, {name}. Nazz wird ganz bestimmt ein kleines Vermögen bezahlen, damit dieses Geheimnis... ein Geheimnis bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1118] = { id = 1118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück nach Booty Bay", description = "{name}, Ihr seid ein {class}, dem ich trauen kann. Ihr werdet den Auftrag erledigen und die Klappe halten.\n\nIch habe einen neuen Plan geschmiedet. Er ist riskant, aber wenn er funktioniert, könnten wir beide gut absahnen! Und ich glaube, Ihr seid der Richtige, um das durchzuziehen.\n\nAls Erstes müsst Ihr nach Booty Bay zurückkehren. Nun, ich bitte um Verzeihung, {name}. Ich weiß, meine letzte Aufgabe führte Euch dorthin. Aber sprecht diesmal mit Crank Fizzlebub.\n\nGebt ihm diesen Brief. Und wenn er um Unterstützung bittet, dann tut, was Ihr könnt, um ihm zu helfen. Es wird sich lohnen.", sourceObjective = "Bringt Kravels Plan zu Crank Fizzlebub in Booty Bay.", progress = "Hallo, hallo. Und was führt einen so edlen Eurer Art nach Booty Bay, {race}?", completion = "Verstehe. Kravel hat einen großen Plan in petto. Er ist ein finsterer Schurke - das mag ich an ihm.\n\nIhr braucht also etwas, das den Geist verwirrt, hm? Etwas Mächtiges...\n\nOb man die Mixtur nehmen könnte, die Zanzil seinen Zombies gibt...", sourceObjectiveStatus = "unverified-source-field" }
quests[1119] = { id = 1119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzils Mixtur und Fools Starkbier", description = "Ich habe herausgefunden, wie man aus Zanzils Mixtur mit Starkbier ein mächtiges Getränk macht. Fools Starkbier. Und ich glaube, genau das braucht Kravel. Probiert es einfach mal aus und lasst mich wissen, wie es wirkt.\n\nUnd behaltet das Zeug nicht zu lange unbenutzt, {name}. Zanzils Mixtur hat eine seltsame Wirkung auf die Hefe des Starkbiers und regt sie heftig an. Sie bleibt nicht ewig frisch.", sourceObjective = "Bringt Fools Starkbier zu Kravel in der schimmernden Ebene zurück.", progress = "Hallo, {name}. Konnte Fizzlebub uns helfen?", completion = "Großartig! Fizzlebub kam durch! Ich werde daran denken, wenn ich ihn wiedersehe.\n\nUnd habt Dank, {name}. Ihr macht Eure Sache großartig und wir werden beide eine Menge Geld damit verdienen...", sourceObjectiveStatus = "unverified-source-field" }
quests[1120] = { id = 1120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gnome betrunken machen", description = "Wir müssen Fools Starkbier an einem aus der Boxencrew ausprobieren. Wenn Ihr es an den Gnomen erproben wollt, hier - nehmt das Starkbier und gebt es dem Gnomen-Boxenboss.\n\nUnd wartet nicht zu lange. Das Starkbier wird mit der Zeit schlecht.", sourceObjective = "Bringt Fools Starkbier zum Gnomen-Boxenboss.", progress = "Hallo! Habt Ihr denn etwas für mich?", completion = "Starkbier? Wie aufmerksam! Danke!\n\nWir sollten nicht trinken, da das Rennen bevorsteht, aber... vielleicht können meine Jungs einen Schluck vertragen. Außerdem kann es ja so stark nicht sein, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[1121] = { id = 1121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Goblins betrunken machen", description = "Wir müssen Fools Starkbier an einem aus der Boxencrew ausprobieren. Wenn Ihr es an den Goblins erproben wollt, hier - nehmt das Starkbier und gebt es dem Goblin-Boxenboss.\n\nUnd wartet nicht zu lange. Das Starkbier wird mit der Zeit schlecht.", sourceObjective = "Bringt Fools Starkbier zum Goblin-Boxenboss.", progress = "Was glotzt Ihr denn so?", completion = "Was haben wir denn da? Fusel, hm?\n\nAlso mich stört es nicht, wenn wir ein klein wenig...", sourceObjectiveStatus = "unverified-source-field" }
quests[1122] = { id = 1122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Fizzlebub", description = "Fools Starkbier hat astrein gewirkt! Ich habe beim nächsten Rennen gesetzt... hoffen wir, das Team, das Ihr betrunken gemacht habt, hat sein Auto nummeriert!\n\nBleibt nur noch eine Aufgabe für Euch - bringt diese Notiz zu Crank Fizzlebub in Booty Bay. Er wird von dem erfolgreichen Test wissen wollen.\n\nHoffentlich bekommen wir mehr von Fools Starkbier für künftige Rennen!", sourceObjective = "Bringt den Bericht über Fools Starkbier zu Crank Fizzlebub in Booty Bay.", progress = "Hallo, {name}. Wie hat das Starkbier gewirkt? Starkes Gesöff, was?", completion = "Hier steht, Fools Starkbier war ein Erfolg. Das sind gute Neuigkeiten!\n\nWenn Ihr mehr von dem Zeug wollt, lasst es mich wissen und Ihr könnt mehr von Zanzils Mixtur sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1123] = { id = 1123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabine Saturna", description = "Für diese Aufgabe sucht Majordomus Rabine Saturna für Bewahrer Remulos in Moonglade Unterstützung bei der Erforschung des riesigen Ödlandes weit im Westen von Tanaris und Un'Goro. Er lebt in Nighthaven, dem Hauptort von Moonglade.\n\nVorher möchte ich Euch jedoch noch von der Wichtigkeit Eurer Anwesenheit in Kenntnis setzen. Es gibt zunehmend Spannungen zwischen den Nachtelfen von Darnassus und dem Zirkel des Cenarius in Moonglade. Lasst Euch nicht von völkischer Engstirnigkeit beirren und verlasst Euch auf die Weisheit Eurer Vorfahren, wenn Ihr dort mit dem Zirkel zu tun habt, {name}. Viel Glück.", sourceObjective = "Sprecht mit Rabine Saturna im Dorf Nighthaven in Moonglade. Moonglade liegt zwischen dem Teufelswald und Winterspring, und Ihr erreicht es über den Pfad, der aus der Holzschlundfeste herausführt.", completion = "Ich bin Rabine Saturna und heiße Euch im Namen von Bewahrer Remulos und allen Bewohnern dieses hochheiligen Tales aufs Herzlichste willkommen.\n\nIch weiß Euer Interesse und Euren Eifer bei der Unterstützung des Zirkels des Cenarius zu schätzen. Die Tauren haben eine unglaubliche Neigung für die Lehren des Cenarius gezeigt, und als Vertreter der Horde seid Ihr in der Sicherheit dieses Tales willkommen. Die Erhaltung Azeroths ist ein gemeinsames Ziel, das wir beide verfolgen.\n\nIhr seid hier unter Freunden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1124] = { id = 1124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einöde", description = "Westlich des Un'Goro Kraters entlang des nordwestlichen Grats liegt ein raues Ödland - Silithus. Nur wenige wissen, dass sich hier vor Urzeiten ein Krieg zwischen den Nachtelfen und einer bösartigen, außerirdischen Macht abgespielt hat. Das Böse wurde versiegelt, aber jetzt befürchten wir, dass Kräfte am Werk sind, um diesen... unaussprechlichen Horror wieder zu entfesseln.\n\nSprecht mit Layo Starstrike, einem unserer Agenten in Silithus. Sucht nach ihm in Heldenwacht, der letzten Ruhestätte der Gefallenen des Ödlandes. Gebt Ihm diesen Brief, damit erwerbt Ihr sein Vertrauen.", sourceObjective = "Sprecht in der Nähe des Friedhofs Heldenwacht in Silithus mit Layo Starstrike und zeigt ihm Rabines Brief.", progress = "Das hier ist ein zu gefährliches Land, um hier so sorglos herumzuwandern, {class}. Was führt Euch in die Ödnis von Silithus?", completion = "Rabine schickt Euch also? Tja, dann betrachtet Euch als willkommen... soweit dieses desolate und verlassene Land jemanden willkommen heißen kann.\n\nDamals, als das große Leiden das Land hier beherrschte, war ich noch nicht geboren, aber es gibt Orte in dieser Wüste, die als unheimliches Anschauungsmaterial dieser vergessenen Zeit dienen könnten. Mit Eurer Hilfe könnte es dem Zirkel des Cenarius gelingen, der Gefahr ein für alle Male ein Ende zu bereiten, einer Gefahr, die angeblich schon vor Generationen ausgerottet sein sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[1125] = { id = 1125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister vom Südwindposten", description = "Südwestlich von uns liegt ein tragischer Schauplatz - die Ruinen vom Südwindposten. Dort sollten wir mit unserer Arbeit beginnen, {name}.\n\nNach allem, was wir wissen, war dieses Dorf einst ein Stützpunkt der Nachtelfen für Operationen in Silithus. In der Zwischenzeit wurde es längst von den Silithidschwärmen überrannt, die die Wüsten durchziehen. Ich vermag mir den Horror kaum vorzustellen, als die Zerstörung des Dorfs begann...\n\nDie gequälten Geister gefallener Druiden und Schildwachen wandern ziellos durch die Ruinen. Erforscht diesen Ort und befreit die Seelen dieser unglücklichen Kreaturen, wo immer es erforderlich ist.", sourceObjective = "Befreit die Geister von 8 gequälten Druiden und 8 gequälten Schildwachen beim Südwindposten und kehrt dann zu Layo Starstrike auf den Friedhof Heldenwacht in Silithus zurück.", completion = "Ich hatte mir schon gedacht, dass dieser riesige quirlige Schwarmbau nahe den Ruinen des Dorfes irgendetwas mit seinem Untergang zu tun hat. Mir scheint, dass Euer Wirken das bestätigt hat. Die unmittelbare Nähe des Schwarmbaus stellt eine Bedrohung für unsere zukünftige Arbeit hier dar.\n\nIch danke Euch für Eure Güte, die Seelen der Gefallenen zu befreien. Das ist keine leichte Arbeit, ich weiß. Wenn Ihr bereit seid, würde ich Euch jedoch gern noch einmal um Eure Unterstützung bitten ...", sourceObjectiveStatus = "unverified-source-field" }
quests[1126] = { id = 1126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarmbau im Turm", description = "Wir müssen uns um den Schwarmbau beim Südwindposten kümmern, und ich glaube, ich weiß auch schon, wie wir an ihn herankommen. Meiner Erfahrung nach reagieren die Schwarmbauten der Silithiden empfindlich auf ihre Umgebung. Das erklärt auch ihre Angriffe, als sie die Todesschreie der Geister hörten.\n\nIm Turm sind die Silithiden am stärksten - dort, wo massenweise Wespen herumschwirren. Besteigt den Turm und scheucht den Schwarmbau auf. Meldet Euch zurück, sobald Ihr etwas erfahren habt, aber seid vorsichtig! Wenn Ihr irgendetwas Hilfreiches entdeckt, bringt es zu mir.", sourceObjective = "Besteigt den Turm beim Südwindposten und findet eine Möglichkeit, den Schwarmbau der Silithiden aufzuscheuchen. Bringt alles Ungewöhnliche, das Ihr dabei entdeckt, zu Layo Starstrike auf den Friedhof Heldenwacht in Silithus.", progress = "Na, hat es geklappt? Zumindest seid Ihr noch in einem Stück, und das ist gut. Habt Ihr etwas gefunden?", completion = "Was zum... was ist das?\n\nEs hat die Form eines... Kastens...? Total verkrustet. Wartet, da ist eine freie Stelle... ist das etwa ein Buch unter all diesem Dreck?\n\nIch glaube, Ihr habt da einen außergewöhnlichen Fund gemacht, {name}... zumindest hoffe ich das. Vielleicht ist das ein Tage- oder Logbuch aus alter Zeit, konserviert in dieser Hülle.\n\nIch glaube, ich weiß wie wir herausfinden können was es ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[1127] = { id = 1127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fools Starkbier", description = "Ihr möchtet also etwas von Fools Starkbier, hm? Denkt Ihr daran, wieder die Rennen zu besuchen...?\n\nGut, bringt mir mehr von Zanzils Mixtur und ich braue noch etwas mehr Starkbier für Euch.", sourceObjective = "Bringt 12 von Zanzils Mixturen zu Crank Fizzlebub in Booty Bay.", sourceObjectiveStatus = "unverified-source-field" }
quests[1130] = { id = 1130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Melor schickt Kunde", description = "{name}, Melor Stonehoof hat von Euren Taten gehört und Euch einen Weg geebnet.\n\nWenn Ihr ihn einschlagen möchtet, dann geht nach Thunder Bluff und sprecht mit Melor. Ihr findet ihn auf der Anhöhe der Jäger.", sourceObjective = "Sprecht mit Melor Stonehoof in Thunder Bluff.", completion = "So, {name}, Ihr seid also gekommen. Seid Ihr denn bereit, eine Reise durch ferne Länder zu beginnen?\n\nWenn ja, {class}, dann hört zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[1131] = { id = 1131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stahlbiss", description = "Manchmal jagen wir wegen Essen. Manchmal jagen wir wegen der Ehre. Und manchmal jagen wir, um der Lehren der Erdenmutter teilhaftig zu werden.\n\nDoch die Jagd, auf die ich Euch jetzt schicke, hat damit nichts zu tun. Es geht darum, eine Kreatur zu töten, die nicht unter dem Segen der Erdenmutter steht.\n\nDie Hyäne Stahlbiss streift südlich des Brachlandes durch Tausend Nadeln. Sie ist eine Tyrannin, die andere Hyänen anlockt und Furcht und Blutvergießen unter den friedlicheren Wildtieren verbreitet.\n\nSucht Stahlbiss, {name}. Sucht und besiegt sie.", sourceObjective = "Bringt Stahlbiss' Rippe zu Melor Stonehoof in Thunder Bluff.", progress = "Habt Ihr die elende Stahlbiss besiegt, {name}?", completion = "Durch den Sieg über Stahlbiss habt Ihr Tausend Nadeln von einer schrecklichen Besudelung gesäubert.\n\nUnd das, {name}, ist Eure Lektion für den heutigen Tag.", sourceObjectiveStatus = "unverified-source-field" }
quests[1132] = { id = 1132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiora Longears", description = "Ach, wieder auf See zu sein! Den Kuss des Windes zu spüren und mich von den Wellen wiegen zu lassen wie vor langer Zeit von meiner gesegneten Mutter!\n\nOh, hätte ich doch nur Euer Glück, {class}, denn ich sehe das Meer in Eurer Zukunft!\n\nMeine Aufgabe ist es, eifrige Seelen nach Kalimdor zu bringen, in das Land der unbegrenzten Möglichkeiten! Wenn Ihr Euer Glück in Übersee machen wollt, dann reist von hier mit dem Schiff in den wunderschönen Hafen Theramore. Sprecht mit meiner Partnerin, der Elfin Fiora Longears.\n\nSie wird Euer Abenteuer in Kalimdor beginnen lassen!", sourceObjective = "Sprecht mit Fiora Longears in Theramore.", completion = "Guten Tag auch! Mr. Flint im Hafen von Menethil hat Euch geschickt? Mr. Flint besitzt eine gute Charakterkenntnis. Wenn er Euch hergeschickt hat, dann gehört Ihr zweifellos nach Kalimdor!", sourceObjectiveStatus = "unverified-source-field" }
quests[1133] = { id = 1133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Astranaar", description = "Wenn Ihr gerade vom Boot von Menethil kommt, dann solltet Ihr als Erstes nach... Astranaar gehen. Ich bin sicher, ein eifriges Mitglied der Allianz kann dort viel Gutes tun. Sprecht mit Shindrell Swiftfire und bietet Eure Dienste an.\n\nAber erwähnt nicht, wer Euch geschickt hat. Shindrell kennt mich nicht...", sourceObjective = "Sprecht mit Shindrell Swiftfire in Astranaar.", completion = "Seid Ihr hier, um der Allianz Eure Dienste anzubieten, {name}? Wir sind dankbar für die Unterstützung, denn wiewohl seine Schönheit ungebrochen ist... ist Ashenvale nicht mehr so friedlich wie einst.", sourceObjectiveStatus = "unverified-source-field" }
quests[1134] = { id = 1134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prachtschwingen des Steinkrallengebirges", description = "Wir führen keinen offenen Krieg mit der Horde, aber der Frieden ist brüchig. Ihre Agenten gehen häufig gegen uns vor, aber stets heimlich.\n\nEiner dieser Feldzüge wurde uns durch geheime Informanten in Theramore enthüllt, die behaupten, dass die Orcs Gift der Prachtschwingen beim Mirkfallonsee im Steinkrallengebirge im Süden sammeln. Dann benutzen Orc-Auftragsmörder das Gift bei ihren geheimen Feldzügen gegen die Allianz!\n\nWenn das stimmt, dann müssen wir sie aufhalten, {name}. Wir müssen ihnen den Zugang zu dem Gift versperren.", sourceObjective = "Bringt 12 Prachtschwingengiftbeutel zu Shindrell Swiftfire in Astranaar.", progress = "Habt Ihr die Prachtschwingengiftbeutel, {name}. Wir dürfen nicht zulassen, dass die Orcs die Gifte der Bestien gegen uns verwenden!", completion = "Danke, {name}. Es stimmt mich traurig, Kreaturen abschlachten zu lassen, die unsere Feinde nicht freiwillig unterstützen, und doch ist es meine Pflicht.\n\nEuer Herz mag um die Prachtschwingen trauern, die Ihr abschlachten musstet, aber es dürfte Euch mit Freude erfüllen, dass Eure Verbündeten jetzt vor dem Gift der Prachtschwingen sicher sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1135] = { id = 1135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steilhanggift", description = "Wie Ihr sicher wisst, werden Flügeldrachen oft von Orcs als Reittiere gezähmt. Weniger bekannt indessen ist, dass das Gift eines Flügeldrachen in manchen Kreisen höher geschätzt wird als die Bestie selbst. Falls Ihr also keine Angst vor einer kleinen Flügeldrachenjagd habt... habe ich einen Job für Euch.\n\nEs gibt einen Ort im Land Tausend Nadeln, er liegt westlich von hier, welcher als der Steilhang bekannt ist. Die dort lebenden Steilhangflügeldrachen haben ein starkes Gift. Stark und kostbar.", sourceObjective = "Bringt 10 Steilhanggiftbeutel zu Fiora Longears in Theramore.", progress = "Habt Ihr den Steilhang gefunden, {name}? Und Glück bei den Flügeldrachen dort gehabt?", completion = "Ah, die meisten platzen förmlich vor Gift, {name}. Man findet sie normalerweise nur bei jungen Flügeldrachen oder fruchtbaren Weibchen. Das muss ein Gemetzel oben am Steilhang gewesen sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[1136] = { id = 1136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostrachen", description = "{name}, jetzt ist es Zeit, weit entfernte Länder zu bereisen. Ihr seid bereit.\n\nIhr jagt jetzt Frostrachen, einen Yeti im Alteracgebirge. Er ist schwer zu erkennen, da sein weißes Fell mit den Schneefeldern seiner Bergheimat verschmilzt. Man bekommt ihn kaum je zu sehen.\n\nAber ich zeige Euch, wie man eines solchen Geschöpfes habhaft wird. Hier, nehmt diese Rolle. Ich habe darauf vermerkt, wie man Frostrachen anlocken kann.\n\nGeht jetzt, {name}. Eure Reise ist lang und viele Herausforderungen harren Eurer. Erst wenn Ihr mit Frostrachens Mähne zurückkehrt, ist Eure Aufgabe abgeschlossen.", sourceObjective = "Bringt Frostrachens Mähne zu Melor Stonehoof in Thunder Bluff.", progress = "Seid Ihr im Alteracgebirge gewesen, {name}? Habt Ihr den scheuen Frostrachen gefunden?", completion = "Kraft und List waren erforderlich, um Frostrachen zu besiegen, {name}.\n\nEuer Weg führte Euch zu den Tälern von Tausend Nadeln und den hohen Bergen von Alterac. Eines Tages wird er Euch durch alle Länder der Erdenmutter führen, denn das ist das Leben des Jägers.", sourceObjectiveStatus = "unverified-source-field" }
quests[1137] = { id = 1137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten für Fizzle", description = "Indurium besitzt einen erstaunlichen Hitzewiderstand! Ich bin sicher, es taugt für Fizzles Kolben. Aber er braucht echtes Indurium, nicht nur die Späne.\n\nDas Erz muss tief in den Minen von Uldaman abgebaut werden, an der Nordgrenze des Ödlandes. Das ist die wahre Quelle von Indurium.\n\nBestellt Fizzle Brassbolts Grüße von mir und sagt ihm, was ich Euch gesagt habe.\n\nAngenehme Reise, {name}. Ich wäre nicht überrascht, wenn wir uns wiedersehen - wenn Fizzle von dem Indurium erfährt, schickt er Euch wahrscheinlich nach Uldaman, um es zu holen!", sourceObjective = "Sprecht mit Fizzle Brassbolts in der schimmernden Ebene.", completion = "{name}, Ihr seid zurück! Habt Ihr Martek gefunden? Ihr habt mit ihm gesprochen? Was hat er gesagt? Kann er helfen???\n\nSagt es mir, sagt es mir, sagt es mir!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[1138] = { id = 1138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeresfrüchte", description = "Ich liebe Krebse. Krebse sind die Früchte des Meeres! Man kann sie backen, grillen, kochen und braten. Man kann sie in der Pfanne braten, frittieren und kurzbraten. Es gibt Krebssalat, Krebssuppe, Krebseintopf, Pfefferkrebs, Zitronenkrebs, Peitscherwurzelkrebs und Ironforgekrebs à la Surprise. Das ... das war's eigentlich.\n\nIch angle hier gerade und daher kann ich mir keine feinen Krebsbrocken besorgen. Mann kann sie aus Riffkriechern und verkrusteten Gezeitenkriechern kratzen. Man kann viel mit ihnen anstellen. Man kann sie backen, grillen, kochen ...", sourceObjective = "Sammelt 6 feine Krebsbrocken für Gubber Blump in Auberdine.", progress = "... Zitronenkrebs, Peitscherwurzelkrebs und Ironforgekrebs à la Surprise. Das war's eigentlich.\n\nOh, hallo, {name}. Habt Ihr die feinen Krebsbrocken, von denen ich Euch erzählte?", completion = "Prima, diese feinen Krebsbrocken sind genau, was ich brauche. Danke, {name}! Ich habe das hier gefunden, als ich vor einiger Zeit geangelt habe, und ich habe keine Verwendung dafür. Vielleicht könnt Ihr etwas damit anfangen. Man kann damit allerdings ganz sicher keine guten Krebsgerichte machen.\n\nIch habe Euch doch alles über Krebse berichtet, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[1139] = { id = 1139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Tafel des Willens", description = "Wir haben den Schattenschmiedeklan ausgebremst, indem wir ihn von der Blackrockspitze abgeschnitten haben, doch Hammertoes Mission wurde noch nicht erfüllt. Sein Tod darf nicht umsonst gewesen sein. Er träumte davon, die Schrifttafel des Willens zu finden: eine Steintafel, graviert mit Magie durch die Titanen selbst, die helfen, ihren Schöpfungen Leben einzuhauchen und ihnen damit einen eigenen Willen ermöglichen. So jedenfalls heißt es in den Legenden.\n\nDennoch müssen wir die Tafel bergen, ehe der Schattenschmiedeklan sie finden kann.\n\nKehrt nach Uldaman zurück, sucht die Tafel und kommt unverzüglich wieder her.", sourceObjective = "Sucht die Tafel des Willens und bringt sie zu Berater Belgrum in Ironforge.", progress = "Hammertoes Auftrag muss aktualisiert werden, {name}. Das schulde ich ihm.\n\nNicht nur deswegen ist es zwingend, dass Ihr nach Uldaman zurückkehrt, sondern auch für die Sicherheit aller Zwerge. Wenn die Tafel den Dunkeleisenzwergen in die Hände fällt, kann niemand sagen, wie mächtig ihre Golemarmee werden könnte.", completion = "<Berater Belgrum schüttelt ungläubig den Kopf, als Ihr ihm den Steinsplitter gebt.>\n\n{name}, das ist erstaunlich. Ich muss das schnellstens zu den Magiern des Königs bringen lassen. Sie werden das Teil studieren und herausfinden, ob die Legenden wahr sind. Doch das soll ein andermal diskutiert werden. Ihr habt unserem Volk mehr geholfen, als ich für möglich hielt - danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[1140] = { id = 1140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Turm von Althalaxx", description = "Díe Schrift der Orcs ist kaum mehr als das Gekritzel eines Kindes. Viele meines Ordens spotteten, als ich ihre Sprache lernen wollte, aber ich fand es hilfreich, meine Feinde besser zu verstehen.\n\nIlkruds Gekritzel zufolge scheint Athrikus immer noch zwei Seelenedelsteine zu besitzen, und die werden in Nightrun und Satyrnaar aufbewahrt, Satyrgebiete im nordöstlichen Ashenvale.\n\nSeid vorsichtig da draußen, {name}, die bluttriefenden Tempel der Satyrn können selbst für abgebrühte {class} wie Euch beängstigend sein.", sourceObjective = "Befreit die Hochgeborenenseelen in Night Run und Satyrnaar und kehrt zu Delgren dem Läuterer in Maestras Posten zurück.", completion = "Vielleicht hat man die Satyrn schon viel zu lange im Wald geduldet. Ich spreche mit Elissa darüber, wenn ich wieder nach Auberdine reise.\n\nWie auch immer, nachdem die Seelenedelsteine zerstört sind, dürfte Athrikus' Macht sichtlich geschwunden sein. Wir müssen die Gelegenheit nutzen, ihn und seinen Kult auszurotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1141] = { id = 1141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Familie und die Angel", description = "Ich liebe das Angeln. Die Blump-Familie ist berühmt fürs Angeln. Mein Name ist Gubber Blump; ich angle.\n\nEs gibt eine Fischart, die ich hier in der Gegend gern fange. Sie heißt Dunkelküstenbarsch. Früher fuhr ich mit einem Boot hinaus, um Barsche zu angeln, aber seitdem die gemeinen Murlocs gekommen sind, fahren keine Boote mehr raus. Ich wette, dass sie auch alle Barsche aufgefressen haben.\n\nSagt, wollt Ihr mir helfen, Dunkelküstenbarsche zu fangen? Ich würde Euch eine echte Blump-Familienangel geben, wenn Ihr es tun würdet! Es ist eine wirklich gute Angel, um damit Fische zu fangen.", sourceObjective = "Fangt 6 Dunkelküstenbarsche für Gubber Blump in Auberdine.", progress = "Es gibt sehr viele gute Gerichte, für die man Dunkelküstenbarsche braucht. Man kann sie prima essen, aber ich finde, es macht noch mehr Spaß, sie zu fangen.\n\nHabt Ihr schon ein paar Dunkelküstenbarsche gefangen?", completion = "Das sind echt schöne Zackenbarsche, {name}! Danke, dass Ihr mir geholfen habt!\n\nIhr könnt mindestens so gut angeln wie meine Cousine Graun Blump. Sie hat auch einen Bart und sie riecht etwas merkwürdig, aber das hält sie nicht vom Angeln ab. Tja, ich denke, Ihr könnt auch eine Blump-Familienangel benutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1142] = { id = 1142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sterblichkeit schwindet", description = "Ich habe nicht mehr lange zu leben... so... so... schwach.\n\n... der t-t-tapfere Zwerg Lonebrow hat jemanden geschickt, Falfindel zu w-w-warnen...\n\nAber bevor ich... s-s-sterbe...\n\n... meine Frau Treshala... ihr Anhänger des Bundes mit mir... gestohlen... von einem der n-n-niederträchtigen Angreifer...\n\nB-B-Bitte sucht ihn... und bringt ihn Treshala in Darnassus zurück...\n\n... mit der Nachricht meines einsamen... Todes.", sourceObjective = "Sucht und bringt Treshalas Anhänger zu Treshala Fallowbrook in Darnassus.", progress = "Was führt Euch in mein Haus, {race}?", completion = "Nein!\n\nDas ist nicht fair. Oh grausame, unerträgliche Welt!\n\nJetzt muss ich diese Last des Kummers tragen und darf Heralaths Werk nicht mit ihm sterben lassen.\n\nEs war tapfer von Euch, von so einem gefährlichen Ort anzureisen, {name}. Doch bitte lasst mich jetzt allein.\n\nIch will in Abgeschiedenheit trauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[1143] = { id = 1143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Turm von Althalaxx", description = "Verstehe. Also wenn das stimmt, was Ihr sagt, dann ist jetzt die Zeit gekommen, endlich zuzuschlagen. Ich glaube, Athrikus residiert in der Turmspitze. Aber seid vorsichtig, er ist von vielen mächtigen Hexenmeistern umgeben, die tödlicher sind als Eure bisherigen Gegner.", sourceObjective = "Tötet Athrikus Narassin und bringt seinen Kopf zu Balthule Shadowstrike nahe des Turms von Althalaxx.", progress = "Athrikus Narassin ist ein alter und mächtiger Hexenmeister. Vielleicht sollten wir auf Delgrens Unterstützung warten, aber offenbar setzt er großes Vertrauen in Euch, wenn er Euch allein schickt.", completion = "Ich hoffe, nach dem Tod von Athrikus werden die dämonischen Kräfte in dieser Gegend zurückgedrängt. Ich zweifle nicht, dass sie sich neu formieren und zurückkehren, aber bis dahin werden wir auf die Bedrohung vorbereitet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1144] = { id = 1144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willix der Importeur", description = "Endlich ist Hilfe eingetroffen!\n\nIhr habt keine Ahnung, wie lang ich hier gefangen gehalten wurde. Ich kann mich nicht erinnern, wann ich zum letzten Mal draußen war.\n\nWisst Ihr, ich bin Unternehmer. Immer am abkupfern, wie man so sagt. Ich habe Wind davon bekommen, dass Mebok Mizzyrix gut für Rotlaubknolle aus diesem Schweinepferch hier bezahlt. Ich dachte mir, das würde ein leichtes Spiel werden. Wie Ihr sehen könnt, habe ich mich geirrt!\n\nWie auch immer, wenn Ihr so freundlich wärt, mir hier raus zu helfen, sollte es Euer Schaden nicht sein.", sourceObjective = "Führt Willix den Importeur aus dem Kral von Razorfen hinaus.", completion = "Nochmals danke, Freund! Ich sagte doch, es würde sich für Euch lohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1145] = { id = 1145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarm wächst", description = "Viele Reisende, die durch Crossroads kamen, halfen mir, Eier vom Feld der Riesen zu sammeln, und viele können Geschichten erzählen, wie tödlich diese Kreaturen sind. Ich habe genug gehört, um diese Insekten als größere Bedrohung einzustufen als meine Meister zuerst dachten.\n\nIch brauche einen Kurier, der nach Orgrimmar reist und sich mit Belgrom Rockmaul trifft. Das dürfte keine Kleinigkeit werden und es sollte nur jemand gehen, der die Aufgabe ernst nimmt.\n\nBelgrom ist für gewöhnlich vor der Halle der Kriegerhelden zu finden.", sourceObjective = "Stellt Korrans versiegelte NotizBelgrom Rockmaul in Orgrimmar zu.", progress = "Ich beneide Euch, {class}. Ihr seht wie jemand aus, der eine Weile außerhalb der Mauern von Orgrimmar gewesen ist.\n\nIch würde selbst im Namen des Kriegshäuptlings reisen, wenn Thrall nicht hier in der Stadt meiner Fertigkeiten bedürfte. Doch er ist uns ein guter Anführer und ich vertraue seinem Urteil. Ich bleibe hier, solange er mich braucht.", completion = "Ah, eine Notiz von Korran. Er ist schon seit langer Zeit ein treuer Diener. Ich fragte mich schon, wie es um seine Pflichten in Crossroads bestellt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[1146] = { id = 1146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarm wächst", description = "Korran ist also zu einer ähnlichen Schlussfolgerung hinsichtlich dieser Insekten gekommen - sie scheinen doch eine größere Bedrohung zu sein, als wir dachten.\n\nVor ein paar Tagen kehrte ein Jäger halbtot aus Tausend Nadeln zurück. Er gehörte zu einem Stoßtrupp, der geschickt wurde, um ein Ausgrabungsteam der Zwerge von der schimmernden Ebene zu verjagen. Während des Angriffs kamen noch mehr von diesen Insekten aus einer Höhle an der Grabungsstätte und hätten die Gruppe fast getötet.\n\nIhr Anführer war Moktar Krin und sie suchten Zuflucht an der Grenze der schimmernden Ebene. Bringt ihm diese Notiz.", sourceObjective = "Stellt Belgroms versiegelte NotizMoktar Krin in Tausend Nadeln zu.", progress = "Mich und meine Gruppe führt der Krieg zur schimmernden Ebene, {class}. Was führt Euch her?", completion = "Stört Euch nicht an den hallenden Echos von den Bergwänden. Die Goblins und Gnome sind draußen in der Ebene und rasen in Abscheulichkeiten der, wie sie es nennen, 'Wissenschaft' herum. Es gibt größere Bedrohungen hier in Tausend Nadeln, und eine davon tötete mehr als die Hälfte meiner Gruppe.\n\nAber wir bleiben hier, bis wir von Belgrom in Orgrimmar gehört haben. Bis dahin halten wir unsere Position hier und bleiben wachsam.", sourceObjectiveStatus = "unverified-source-field" }
quests[1147] = { id = 1147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarm wächst", description = "Hmm. Offenkundig hält Belgrom die Monster für eine Bedrohung. Er möchte sie in die Tiefen zurückgedrängt haben, aus denen sie gekommen sind.\n\nDie Zwerge zu töten, die von der Forscherliga geschickt wurden, genügte wohl nicht - jetzt muss ich eine Gruppe halbtoter Krieger in einen neuen Kampf führen. Aber selbst können wir das nicht; nicht unter diesen Bedingungen. Die Grabungsstätte liegt südlich von hier. Es sollten keine Zwerge mehr in der Gegend sein. Habt Ihr Lust, Klinge oder Stab in die Hand zu nehmen und uns zu unterstützen?", sourceObjective = "Tötet 5 Silithidsucher, 5 Silithidschwarmdrohnen sowie 5 Silithideindringlinge und kehrt zu Moktar Krin in Tausend Nadeln zurück.", completion = "Ha! Dieses Sekret, das Euch bedeckt, macht Euch nur hübscher, {name}! Leider hat es Euren Geruch nicht eben verbessert. Geht nicht zu nahe zu den Kodos; Ihr löst entweder eine Stampede aus oder macht sie lüstern.\n\nIch glaube, meine Gefährten würden zustimmen, dass Euer Geruch allein beweist, welche Hilfe Ihr uns gegen diese Insektenkreaturen wart. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1148] = { id = 1148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teile des Schwarms", description = "Ihr untersucht den Knochenpanzer gründlich. Als Ihr ihn in den Händen dreht, stellt Ihr fest, dass die Chitinplatten derart verflochten sind, dass er dadurch unglaublich hart wird. So etwas habt Ihr noch nie gesehen. Ihr untersucht den Rest des Kadavers und kommt zu dem Schluss, dass diese Kreaturen sehr kräftig und hochentwickelt sind.\n\nAls ihr einen weiteren Blick auf den Knochenpanzer werft, wird Euch klar, dass Korran diese Kreaturen gewiss gern studieren würde. Er könnte dadurch herausfinden, was diese Kreaturen sind und woher sie kommen.", sourceObjective = "Bringt 1 Silithidenherz, 5 Silithidenkrallen und 3 intakte Silithidenknochenpanzer zu Korran in Crossroads.", progress = "Ah, es ist lange her, seit Ihr mich besucht habt, {name}. Was kann ich heute für Euch tun? Ihr seht aus, als hättet Ihr jüngst das Antlitz des Krieges geschaut. Gut... gut für die Horde und gut für Euch. Je mehr Kämpfe Ihr gesehen habt, desto hilfreicher seid Ihr; und stärker.", completion = "Habt Ihr Moktar neuerdings gesehen? Er ist ständig auf der Suche nach mir. Zu meinem Bedauern muss ich hören, dass er lieber über seine kleine Kriegerschar wacht, als in den Kampf zu ziehen, aber ich bin sicher, es würde ihm gefallen, Mitglieder der Forscherliga zu töten.\n\nEs war klug, mir diese Proben zu bringen, {name}. Zusammen mit den Eiern vom Feld der Riesen sollte ich herausbekommen können, was diese Insekten sind und was sie vorhaben könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1149] = { id = 1149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test des Glaubens", description = "Ihr habt mich also gesucht, oder führt Euch das Schicksal zu mir? Einerlei. Ihr seid jetzt hier, und so wird Eure Reise erneut beginnen.\n\nDas Sein besteht aus vielen Aspekten: Geist, Körper, Verstand. Einige davon kann man anhand der Traditionen einer Kultur bewerten. Von anderen können wir nur hoffen, dass sie in uns selbst existieren. Wenn Ihr einverstanden seid, möchte ich einige der Aspekte in Euch testen.\n\nWenn Ihr besteht, werdet Ihr stärker werden. Wenn Ihr scheitert, werdet Ihr die Weite des Nether begreifen.\n\nAls Erstes ein Test des Glaubens.", sourceObjective = "Wenn Ihr festen Glaubens seid, dann springt von den Planken über Tausend Nadeln.", progress = "Glauben. Er ist wichtiger als vielen bewusst ist.\n\nManchmal ist es gar nicht wichtig, was man glaubt. Es ist nur wichtig, dass man überhaupt an etwas glaubt.", completion = "Erst wenn wir unvorhergesehenen Widersachern gegenüberstehen, begreifen wir, wie stark unser Geist ist. Ihr habt den Sprung des Glaubens gewagt, obwohl Ihr keine Garantie hattet, dass Ihr überleben würdet. Euer Verstand ist offen und Euer Geist bereit für das, was kommen wird.\n\nWenn Ihr bereit seid, wartet der nächste Test auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[1150] = { id = 1150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test der Belastbarkeit", description = "Ich sehe mit Freuden, dass Euer Mut im Lichte Eurer bisherigen Taten unerschütterlich bleibt. Da Euer Glaube stark ist, wird es Zeit, Euren Körper zu testen.\n\nAls Erstes ein Test der Belastbarkeit. Geht mit Freunden zum Bau der Wildfedern westlich vom Freiwindposten. Steigt in die Tiefen ihres Unterschlupfes hinab und zerstört ihre Nahrungsvorräte. Damit solltet Ihr deren Zorn angestachelt haben. Wenn Ihr lange genug überlebt, wird Grenka Blutkreischer Euch persönlich heimsuchen. Tötet sie und bringt mir ihre Klaue, um den Test abzuschließen.", sourceObjective = "Bringt Grenkas Klaue zu Dorn Plainstalker in Tausend Nadeln.", progress = "Ihr müsst spirituell, körperlich und geistig auf die Herausforderungen vorbereitet sein, die vor Euch liegen.\n\nZu oft stürmen wir los, ehe wir bereit sind. Ich betrachte es als meine Pflicht gegenüber der Jugend, ganz gleich welchen Stammes, sie auf die Gefahren vorzubereiten, denen sie sich gegenübersehen könnten, wenn sie ihr Haus verlassen haben.", completion = "Grenka war selbst nach {race}-Standards mächtig. Ihr solltet stolz auf Eure heutige Leistung sein.\n\nBeim Test des Glaubens hast du die Kraft des Geistes gezeigt, und jetzt auch Belastbarkeit im Kampf gegen die Harpyien der Wildfedern, doch die Zeit ist reif für einen neuen Test.", sourceObjectiveStatus = "unverified-source-field" }
quests[1151] = { id = 1151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test der Kraft", description = "Zu Zeiten der Alten Götter bewohnten Elementare einen Großteil dieser Welt. Sie beteten die Alten Götter an, und die Götter fesselten die Elementare durch ihre Macht an diese Welt. Als die Alten Götter verbannt wurden, verblassten die Elementare in unserer Welt und kehren jetzt auf Geheiß mächtiger Magier zurück.\n\nAber es gibt Ausnahmen. Einige Elementar waren mächtig genug, aus eigenen Stücken hier zu bleiben. Solch ein Elementar ist Rok'Alim.\n\nSucht Rok'Alim in Tausend Nadeln und tötet ihn, um Eure Kraft zu beweisen.", sourceObjective = "Bringt Fragmente von Rok'Alim zu Dorn Plainstalker in Tausend Nadeln.", progress = "Von den Zentaurenstämmen in Tausend Nadeln wird Rok'Alim auch der Trommler genannt, weil er auf alle Kreaturen, die tapfer oder dumm genug sind, sich ihm in den Weg zu stellen, mit den Fäusten eintrommelt.", completion = "Euer Test der Kraft ist beendet. Ihr habt Kraft und Tapferkeit gezeigt und seid jetzt bereit für den letzten Test, bevor diese Rituale abgeschlossen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1152] = { id = 1152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test der Lehre", description = "Eure Zeit bei mir neigt sich dem Ende zu. Ich bin wissend, aber den Test der Lehre kann ich Euch nicht stellen. Es gilt, Lektionen zu erlernen und Orte zu besuchen, die in der Zuständigkeit anderer liegen.\n\nWenn Ihr bereit seid, dann sucht Braug Dimspirit auf - er ist ein höchst weiser Schamane. Er wird Euch weiter testen, also achtet auf seine Worte, {name}.\n\nWenn Ihr bereit seid, dann sucht den Tunnel, der das Steinkrallengebirge mit Ashenvale verbindet. Dort in der Nähe lebt Braug. Und seid vorsichtig, {name}, die Nachtelfen versuchen vielleicht, Euren Test zu behindern.", sourceObjective = "Sucht Braug Dimspirit in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge.", completion = "Die Tage und Nächte allerorten auf der Welt werden kälter, da die Goblins das Land vergewaltigen, und die Nachtelfen zeigen mit den Fingern auf die jüngeren Völker. Die Verlassenen und die Orcs sind nicht die Einzigen, die man für die Härten in Kalimdor und Lordaeron verantwortlich machen kann. Viele der intelligenten Völker haben zum Schmerz der Welt beigetragen. Dorn weiß das und hat Euch zu mir geschickt, weil Ihr die erforderlichen Attribute besitzt, das auch zu erkennen.\n\nJetzt steht Ihr vor Braug.", sourceObjectiveStatus = "unverified-source-field" }
quests[1153] = { id = 1153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Erzprobe", description = "{class}, Ihr habt mir auch früher schon geholfen. Der Kriegshäuptling ist mit meinen bisherigen Leistungen zufrieden und bittet mich, mit neuer Entschlossenheit fortzufahren. Meine Ehre gebietet, dass ich den Kriegshäuptling wissen lasse, was Ihr alles vollbracht habt, doch zuvor möchte ich Euch abermals um Hilfe bitten.\n\nJüngst kamen Reisende aus dem Süden von einem Ort namens Tausend Nadeln. Dort töteten sie einen Kobold, der eine außergewöhnliche Erzprobe bei sich hatte, wollten sie aber nicht verkaufen. Ich möchte eine Probe dieses Erzes untersuchen.", sourceObjective = "Sucht eine unbearbeitete Erzprobe bei einem Buddler oder Feldmesser der Bruchschnauzen und bringt sie zu Tatternack Steelforge im Camp Taurajo im Brachland.", progress = "Ich sah jene Reisenden wieder, die mir keine Erzprobe verkaufen wollten. Ich spuckte sie an, weil sie dem Kriegshäuptling nicht halfen.\n\nMögen sie im Kampf wie Feiglinge sterben und nicht wie Krieger, wie es das Recht aller Völker sein sollte, die sich mit der Horde verbünden.", completion = "Gute Probe, {name}. Wirklich eine gute Probe.\n\nDiese Reisenden können mich nach Eurer erfolgreichen Rückkehr nicht mehr wegen diesem Erz verspotten.\n\nIch werde mich sofort an die Arbeit machen. Wenn das Material stark genug ist, werde ich dem Kriegshäuptling eine daraus gefertigte Waffe schicken, um ihm unsere Erfolge zu zeigen.\n\nIch werde Eure Hilfe nicht vergessen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1154] = { id = 1154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test der Lehre", description = "Ihr habt Dorns Tests bestanden und wollt jetzt Eure nächste Prüfung absolvieren. Sehr gut. Bisher sind alle Eure Herausforderungen kindisch gewesen. Es ist leicht, Euren Körper zu testen - bei Eurem Verstand sieht das schon anders aus.\n\nIch werde es mit einfachen Worten erklären: sucht das Buch, das ich Euch nenne, lest es und beantwortet meine Fragen nach seinem Inhalt.\n\nWas für ein Buch, werdet Ihr fragen? Das 'Vermächtnis der Aspekte'. Man findet es in den Tiefen des Dor'danil-Grabhügels im südlichen Ashenvale, wo es von den toten Druiden und deren Tötern bewacht wird.", sourceObjective = "Sucht das 'Vermächtnis der Aspekte' und bringt es zu Braug Dimspirit in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge zurück.", progress = "Bringt mir das Buch, wenn Ihr es gelesen habt. Ich werde Euch erst Fragen stellen, wenn Ihr mir das Buch gegeben habt.", completion = "Das ist das Buch, das ich nannte. Dann besteht die Hoffnung, dass Ihr meine Fragen korrekt beantwortet... wenn Ihr nicht vergessen habt, es zu lesen.\n\nSprecht wieder mit mir, wenn Ihr bereit seid, dann stelle ich Euch eine Frage.", sourceObjectiveStatus = "unverified-source-field" }
quests[1159] = { id = 1159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test der Lehre", description = "Gut gemacht, {name}. Ihr habt den ersten Teil des Tests der Lehren bestanden, aber es bleibt noch eine Frage zu beantworten. Aber es ist nicht an mir, diese Frage zu stellen.\n\nBesucht Parqual Fintallas in Lordaeron. Er war ein bedeutender Historiker der Menschen, bevor die Seuche ihn erwischte. Jetzt sucht er immer noch Erleuchtung, freilich einer ganz anderen Art.\n\nEr wird eine weitere Forderung an Euch stellen, bevor er Euch etwas fragt, aber Ihr habt Euch bisher meisterhaft geschlagen - ich bin sicher, Ihr werdet dieses Hindernis überwinden.", sourceObjective = "Sucht Parqual Fintallas in Undercity.", completion = "Braug schickt Euch? Unmöglich.\n\n<Parqual schaut auf und ab.>\n\nDor'Danil gemeistert, einen Sprung des Glaubens gewagt, einen mächtigen Elementar bekämpft und überwältigt? Pah! Ihr seid vermutlich ein Lügner; ein Abenteurer, der Gerede in einer Taverne mitgehört hat. Und jetzt glaubt Ihr, Ihr könnt meinen Test bestehen. So sei es denn ... {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1160] = { id = 1160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test der Lehre", description = "Ich sage Euch, was Ihr suchen müsst und werde Euch sogar meine Frage stellen, aber nicht, weil Ihr Euch beweisen wollt. Wissen ist weit wichtiger als Kraft. Auch wenn andere Euch in ihren Fähigkeiten überlegen sein mögen, Euer Wissen über die Welt ist wertvoller.\n\nGeht zu dem Kloster im Norden Tirisfals. In der dortigen Bibliothek steht ein Buch mit dem Titel Die Anfänge der Bedrohung durch die Untoten. Es wurde von den jetzt verderbten Paladinen benutzt, um sie in meiner Art des Kampfes auszubilden.\n\nBringt es mir.", sourceObjective = "Sucht Die Anfänge der Bedrohung durch die Untoten und bringt es zu Parqual Fintallas in Undercity.", progress = "Ich hoffe, Ihr habt den Scharlachroten Kreuzzug ordentlich leiden lassen, bevor Ihr das Buch gestohlen habt.\n\nMeine Ansichten über ihre Art sind nicht unumstritten. Die Kreuzzügler mögen einst Anhänger des Lichtes gewesen sein, aber jetzt möchten sie alle Kreaturen vernichten, die sich nicht ihrer Religion angeschlossen haben. Sie glauben, dass alle Untoten, Verlassene und andere, gesäubert werden müssen und die, die durch ihre Länder reisen, entweder irrsinnig oder Opfer der starken Magie der Untoten sein müssen. Idioten. Idioten und Narren, allesamt.", completion = "Das ist das Buch, das ich Euch suchen schickte.\n\n<Parqual streicht langsam und zärtlich mit der Hand über das Buch, während er es betrachtet.>\n\nJetzt wünscht Ihr also eine Frage, um zu beweisen, dass Euer Verstand so mächtig ist wie Euer Körper und Geist. Wenn Ihr das Buch lange genug studiert habt, dann stelle ich Euch die Frage und Ihr könnt diese Tests abschließen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1164] = { id = 1164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Dieben stehlen", description = "Die Hure! Das Flittchen! Kenata lebt noch; ihre Familie blüht und gedeiht, während ich leide. Verlassene, wahrhaftig!\n\nMeine Familie wurde Opfer der Seuche. Unser Besitz ebenfalls dahin, während des Kriegs geplündert und niedergebrannt. Und nach alledem haben sie und ihre lausigen Kinder die Stirn, das einzig Kostbare zu stehlen, das ich noch hatte.\n\nMir sind die Sachen, die sie gestohlen haben, längst einerlei. Ich möchte ihre Köpfe!\n\nTötet sie für mich! Geht zum Bauernhof der Dabyries in Arathi, nordöstlich der Zuflucht.", sourceObjective = "Bringt Kenata, Fardel und Marcel Dabyries Köpfe zu Genavie Callow in Undercity.", progress = "Tötet sie alle und bringt mir ihre Köpfe!", completion = "Ihr steht als Racheengel vor mir und ich verneige mich dankbar vor Euch.\n\nNachdem diese Kuh tot ist und ich weiß, dass ihre Brut sich nicht mehr über Azeroth ausbreiten kann, kann ich meine Energie lukrativeren Dingen zuwenden. Ich hoffe, Ihr habt ihren Bauernhof geplündert, als Ihr sie getötet hattet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1166] = { id = 1166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberanführer Mok'Morokks Sorgen", description = "Verbeugen Euch vor Oberanführer Mok'Morokk!\n\nRexxar mich machen zu mächtigem Anführer von Stonemaulklan!\n\nIch gut Anführer. Ich Klan sicher machen.\n\nGroße Drachen kommen und machen Feuer in alte Heimat. Ich klug Oger. Finden neu Heimat für Klan hier.\n\nAlte Heimat so schnell verlassen, ich Sachen vergessen. Winzig {race}, gehen mein Sachen holen. Gehen nach Süden und suchen mein lecker Grog, mein Schnupftabak und mein Geldkassette. Ich Euch mögen, wenn Ihr das tun. Ihr in Flammenbau und Stonemaul Ruinen schauen... sie dort sein, ich sicher!", sourceObjective = "Oberanführer Mok'Morokk in Brackenwall möchte, dass Ihr seinen Grog, seinen Schnupftabak und seine Geldkassette aus dem Dustwallowsumpf holt.", progress = "Ich durstig nach Grog. Ich auch Schnupftabak vermissen. Wo ist Geldkassette? Ihr geht holen für Oberanführer Mok'Morokk!\n\nGeht Süden in alter Heimat suchen. Ich zu beschäftigt, Oger anzuführen.", completion = "Sehr gut, {race}. Ich vermissen Sachen sehr. Ich Euch jetzt mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1167] = { id = 1167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Turm von Althalaxx", description = "Bevor Ihr Athrikus konfrontiert, wäre es vermutlich klug, Balthule zu konsultieren. Zweifellos ist er wachsam in seinem Wachturm gewesen und könnte Informationen über jüngste Entwicklungen haben.", sourceObjective = "Sprecht mit Balthule Shadowstrike beim Turm von Althalaxx.", completion = "Ah, wie schön, Euch wiederzusehen, {name}! Hier geschehen die seltsamsten Dinge, ich bin froh, dass Ihr Euch sehen lasst!\n\nEs war sehr seltsam, {name}. Alles schien normal - jedenfalls so normal, wie es hier sein kann -, und dann schoss plötzlich ein greller Lichtblitz aus dem obersten Turmzimmer. Dann kamen die Schreie. Die Schreie zerrissen die Stille, von Zeit zu Zeit schlugen Blitze in den Boden ein. Was geht hier vor?", sourceObjectiveStatus = "unverified-source-field" }
quests[1168] = { id = 1168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armee des schwarzen Großdrachen", description = "Mok'Morokk wurde von Rexxar zum Oberanführer gemacht. Ihm liegt mehr an Macht als an den Ogern.\n\nSchwarze Großdrachen töten viele Oger. Töten Thargs Frau. Mok'Morokk sagt uns, wir müssen fliehen. Lässt uns hierher kommen.\n\nOger sollten kämpfen. Oger nicht gut im Weglaufen. Mok'Morokk schert sich nur um Mok'Morokk.\n\nFür mich Stonemaul Ruinen Heimat. Mir gefallen im Süden. Dieser Ort nicht Heimat.\n\nHelft Ogern, Armee der schwarzen Großdrachen zu bekämpfen. Ich wollen Rache. Ich wollen nach Hause.", sourceObjective = "Tharg in Brackenwall möchte, dass Ihr 15 Späher der Feuermähnen, 10 Aschenschweife der Feuermähnen und 5 Bannschuppen der Feuermähnen tötet.", completion = "Ihr tötet viele der Armee der schwarzen Großdrachen. Ihr Kriegerheld, {race}.\n\nMacht Tharg glücklich.", sourceObjectiveStatus = "unverified-source-field" }
quests[1169] = { id = 1169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut identifizieren", description = "Während der törichte Narr Mok'Morokk seine Macht genießt und Tharg mit den Dämonen des Kummers und der Rache ringt und um die Führerschaft des Klans buhlt, scheine ich der Einzige zu sein, der die Ursache der Aggression in unserer alten Heimat herausfinden möchte.\n\nWarum der verwirrte Blick, {name}? Erwartet Ihr, dass ich wie ein tumber Grobian spreche, nur weil ich ein Oger bin?\n\nDoch zurück zum Geschäft, bringt mir die Herzen und Zungen der Welpen und Jungtiere. Ich werde die Wurzel dieses Übels finden...", sourceObjective = "Draz'Zilb in Brackenwall hätte gern, dass Ihr ihm 15 sengende Zungen und 15 sengende Herzen bringt.", progress = "Mit den Herzen und Zungen versengter Nachkommen der Armee der schwarzen Großdrachen kann ich herausfinden, welche elende Bestie ihre Brut in unsere Heimat einführte. Wenn wir mehr über unsere Angreifer wissen, können wir versuchen, sie ein für allemal zu vernichten und das Dorf Stonemaul zurückzuerobern.\n\nNatürlich wird es an sich schon eine epische Aufgabe sein, Mok'Morokk zu überzeugen, dass er seine fette, träge Masse aus diesem Dreckloch hebt...", completion = "Zweifellos war es eine gefährliche Sache, diese Herzen und Zungen zu sammeln. Ich werde in die Tiefen des Arkanen vorstoßen, um den Ursprung der schwarzen Bedrohung zu finden, die über unsere einstige Heimat kam.", sourceObjectiveStatus = "unverified-source-field" }
quests[1170] = { id = 1170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Onyxia", description = "Das Dorf Stonemaul wurde von der Brut von Onyxia überrannt. Aber warum sollte die Tochter des Schwarzen-Großdrache-Lords Deathwing über unser Land herfallen?\n\nDas ist sehr beunruhigend. Gewiss wurde Onyxia aus einem anderen Grund hergeschickt, als eine kleine Schar von Ogern zu belagern.\n\nVerständigt unverzüglich Mok'Morokk! Es muss gehandelt werden.", sourceObjective = "Sprecht mit Oberanführer Mok'Morokk in Brackenwall.", completion = "Warum Ihr mir von Großdrachen erzählen? Ich Großdrachen nicht mögen. Mir hier gefallen. Keine Drachen hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[1171] = { id = 1171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Onyxia", description = "Ihr lasst mich jetzt in Ruhe. Sagt Draz'Zilb, wir bleiben hier. Keine schwarzen Großdrachen hier.", sourceObjective = "Sprecht mit Draz'Zilb in Brackenwall.", completion = "Dieser träge Feigling!\n\nMok'Morokks zeigte Kraft, als Rexxar unser Anführer war. Doch kurz nach Rexxars Verschwinden erlag Mok'Morokk den Verlockungen der Macht. Er führte nicht, er forderte. Er dient nicht seinem Volk, sondern erwartet, dass wir ihm dienen.\n\nEs muss etwas geschehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1172] = { id = 1172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Onyxia", description = "Onyxias Brut wurde über das Drachendüster verstreut. Es dürfen auf keinen Fall weitere Welpen schlüpfen.\n\nBegebt Euch eilig zum Drachensumpf in den Marschen von Dustwallow. Gewiss hat sie dort einen Hort angelegt. Sucht die Eier der bösen Großdrachen und vernichtet sie.\n\nWir können das Dorf Stonemaul nie zurückerobern, wenn das Umland eine Brutstätte bleibt.\n\nWas Mok'Morokk angeht ... Für den Jammerlappen habe ich andere Pläne.", sourceObjective = "Draz'Zilb in Brackenwall möchte, dass Ihr 5 Eier von Onyxia zerstört.", completion = "Großartig! Es wird einige Zeit dauern, bis Onyxia wieder Eier legen kann.\n\nIm Namen meines Volkes danke ich Euch, {name}.\n\nIch habe bislang viel von Euch verlangt. Vielleicht könnt Ihr dem Stonemaulklan einen letzten Dienst erweisen.\n\nMok'Morokk ist uns kein guter Anführer. Tharg wäre ein brillanter Anführer, ist aber durch seine Verletzungen und sein Alter behindert. Vertreibt Mok'Morokk mit Gewalt von hier. Erst dann können wir einen neuen Anführer bestimmen und in unsere angestammte Heimat im Süden zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[1173] = { id = 1173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fordert Oberanführer Mok'Morokk heraus", description = "Ihr wagt es, Oberanführer Mok'Morokk herauszufordern?\n\nHa!\n\nIch zerschmettern einen Winzling von {race}!\n\nIhr mir sagen, wenn bereit für ordentliche Tracht Prügel.", sourceObjective = "Besiegt Mok'Morokk und bringt die Nachricht zu Draz'Zilb in Brackenwall.", completion = "Dieser feige Fettwanst Mok'Morokk floh wie ein ängstliches Kind. Ihr habt uns einen großen Dienst erwiesen, {name}.\n\nJetzt kann mein Volk einen neuen Anführer bestimmen, mit dem wir unsere angestammte Heimat ein für allemal zurückerobern.", sourceObjectiveStatus = "unverified-source-field" }
quests[1174] = { id = 1174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gnome gewinnen!" }
quests[1175] = { id = 1175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Straßenunebenheit", description = "Nach dem schweren Zusammenstoß des Red-Thunder-Rennwagen der Goblins und einem Basilisken hat Kronkrider mich angeheuert, um die Strecke zu warten. Keine Ahnung, was die Tiere in der Ebene fressen, dass sie so groß werden, aber wir müssen sie dezimieren, damit sie nicht auf die Fahrbahn laufen, wenn ein Rennen stattfindet.\n\nIch sag Euch was. Wenn ihr ein wenig Profit machen wollt, zieht los und entfernt die Basilisken aus der Gegend.", sourceObjective = "Tötet 10 Salzsteinbasilisken, 10 Salzsteinkristallhäute und 6 Salzsteinstarrer für Rennsteckenleiter Zherin in der schimmernden Ebene.", progress = "Es ist schon schlimm genug, wenn man die Trümmer der Rennwagen beseitigen muss, auch ohne sie aus verbrannten Tierkadavern herauszuklauben.", completion = "Ich hoffe, Ihr habt keine Basilisken auf der Rennstrecke selbst getötet! Es dauert lange, bis die Kadaver in der Sonne verfallen, und ich möchte lieber nicht mit einer Schaufel da raus und sie entsorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1176] = { id = 1176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewicht reduzieren", description = "Wenn es um Rennen geht, zählt jede Kleinigkeit! Ob es sich nun um ein leises Quietschen der Kraftübertragung, eine geringfügige Schwäche der Stoßdämpfer oder ein leichteres Gewicht der Karosserie handelt, man muss alles berücksichtigen.\n\nWir benutzen Geierknochen für kleinere Modifikationen am Chassis unserer Rennwagen, die das perfekte Gleichgewicht zwischen Stärke und Gewicht haben. Und sie sind, was noch besser ist, leicht zu beschaffen, da es in der Salzwüste von Geiern wimmelt.\n\nBringt mir ein paar und ich zahle einen guten Preis dafür.", sourceObjective = "Beschafft 10 hohle Geierknochen für Pozzik in der schimmernden Ebene.", progress = "Habt Ihr die Knochen für mich? Ich wollte gerade die Steueraufhängung leichter machen, möchte das Auto aber nicht zerlegen, solange ich nicht alle erforderlichen Teile habe.", completion = "Großartig! Ich lasse die Crew sofort daran arbeiten. Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[1177] = { id = 1177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunger!", description = "Mud großer Oger.\n\nIch hungrig.\n\nGeht Fische hauen. Bringt Mud Essen.\n\nIhr füttert Mud oder Mud frisst Euch.", sourceObjective = "Mudcrush Durtfeet im nördlichen Dustwallow möchte 12 Schlammflossenköpfe.", progress = "Gebt mir Essen oder ich Euch fressen.", completion = "Ich mag Fischköpfe!\n\nIch Euch jetzt nicht fressen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1178] = { id = 1178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin-Sponsoring", description = "Unser Rennfahrer-Team ist der Stolz aller Goblins. Ihr wärt überrascht, welche Leute unser Team auf die eine oder andere Weise unterstützen.\n\nKennt Ihr Gazlowe? Er treibt auf der ganzen Welt Ersatzteile für uns auf. Er kam sogar mal her, um an einer unserer Aufhängungen zu arbeiten!\n\nVor ein paar Wochen wollte er uns den Prototyp einer neuen Treibstoffeinspritzpumpe schicken, aber sie ist noch nicht eingetroffen. Sonst ist er immer zuverlässig ... Würde es Euch vielleicht etwas ausmachen, nach Ratchet zu gehen und ihn danach zu fragen? Ich will ja nicht drängen, aber die Gnome holen langsam auf!", sourceObjective = "Sprecht mit Gazlowe in Ratchet.", completion = "Pozzik hat Euch geschickt? Wisst Ihr, Pozzik war einer der angesehensten Tüftler in Undermine, bevor er sich zurückzog und an Rennwagen bastelte.\n\nAls er dem Team beitrat, entwickelte er als Erstes die zweimotorigen Rennwagen. Könnte sein, dass das Geschäft leidet, wenn er nicht mehr im Tüftlerverband arbeitet, aber wen interessiert das schon, was? Es geht doch nichts über die Rennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1179] = { id = 1179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brüder Brassbolt", description = "Schon von der schimmernden Ebene gehört, ja? Das ist eine Salzwüste drüben in Kalimdor, direkt südlich vom Canyon der Tausend Nadeln. Der ideale Austragungsort für Rennen, weil es da so flach ist!\n\nDa draußen sind zwei Gnomenbrüder, Freunde von mir, die ihren neuen Raketenwagen erproben, und soweit ich gehört habe, ist er schnell! Hey, so schnell, dass die Fahrer immer verunglücken. Und Gehirnerschütterungen bekommen.\n\nDarum baten sie mich um ein paar Helme für Belagerungsmaschinen, aber ich kann hier nicht weg, meine Pflicht fesselt mich an diesen Ort. Ich kann die Reise also nicht machen!\n\nKönnt Ihr es?", sourceObjective = "Bringt die Kiste mit Schutzhelmen zu Wizzle Brassbolts in der schimmernden Ebene.", progress = "Passt auf, wo Ihr hintretet! Aufpassen, aufpassen, aufpassen!!! Das hier sind empfindliche Teile, und wenn wir gewinnen wollen, muss alles perfekt funktionieren!", completion = "Ah! Longbeard hat Euch mit den Helmen geschickt! Hurrah!\n\nVielleicht können wir jetzt einen Fahrer überreden, unseren Wagen zu fahren...", sourceObjectiveStatus = "unverified-source-field" }
quests[1180] = { id = 1180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin-Sponsoring", description = "Zurück zum Grund Eures Hierseins. Ich weiß, ich habe Pozzik versprochen, dass ich ihm eine neue Treibstoffeinspritzpumpe schicke, aber ich habe sie selbst noch nicht bekommen. Revilgaz drüben in Booty Bay sagte, er würde sie herschicken, aber irgendwie scheint da was schief gelaufen zu sein.\n\nWenn das stimmt, können wir wenig dagegen tun. Aber wir können wenigstens herausfinden, wann sie von Booty Bay abgeschickt wurde.\n\nFragt drüben bei Werftmeister Lozgil nach, er müsste die Frachtbriefe überprüfen können.", sourceObjective = "Sprecht mit Werftmeister Lozgil in Booty Bay.", completion = "Lieferungen nach Ratchet? Lasst mich in den Logbüchern nachsehen...\n\nNein, die letzte vermerkte Sendung nach Ratchet waren Stiefel von Drizzlik. Sonst nicht viel, abgesehen von Baustoffen und Werkzeugen. Definitiv keine Rennwagenteile.", sourceObjectiveStatus = "unverified-source-field" }
quests[1181] = { id = 1181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin-Sponsoring", description = "Ich fürchte, ich kann Euch nicht weiterhelfen, {name}. Wenn Ihr der Sache weiter nachgehen möchtet, würde ich vorschlagen, Ihr geht zum Baron persönlich. Wenn jemand über die Geschäfte von Revilgaz Bescheid weiß, dann Revilgaz selbst.\n\nIhr findet ihn in der Taverne jenseits des Hafens, Obergeschoss.", sourceObjective = "Sprecht mit Baron Revilgaz in Booty Bay.", completion = "Oh, gewiss, natürlich weiß ich, wovon Ihr redet. Neee, ich kann Euch aber nicht helfen. Einige meiner Männer sollten die Blaupausen für die Treibstoffeinspritzpumpe aufspüren, kamen aber mit leeren Händen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1182] = { id = 1182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin-Sponsoring", description = "Wisst Ihr, die Schredder der Venture Company draußen am Nazferitisee (im Norden des Schlingendorntals) wurden mit einer neuartigen Treibstoffeinspritzpumpe ausgerüstet. Ich dachte mir, Pozzik könnte Kapital daraus schlagen, wenn er einige Einzelheiten erfahren könnte. Leider scheint Cozzle, der dortige Großknecht, etwas schlauer zu sein als ich ihm zugestehen wollte.\n\nAber Ihr seht aus, als könntet Ihr es schaffen, die Blaupausen zu finden. Ich weiß, dass er sie in seinem Haus aufbewahrt, aber mit Sicherheit verschlossen und verriegelt.", sourceObjective = "Bringt die Treibstoffreglerblaupausen zu Baron Revilgaz in Booty Bay.", progress = "So ungern ich es zugebe, das Gnomen-Team, das Sie da draußen haben, ist ziemlich gut. Unsere Jungs brauchen jeden Vorteil, den sie bekommen können.", completion = "Lasst mich nur rasch eine Kopie dieser Blaupausen für meine eigenen Notizen machen, dann könnt Ihr sie direkt zu Pozzik bringen. Er soll nicht denken, dass ihn einer seiner Sponsoren im Stich lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1183] = { id = 1183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin-Sponsoring", description = "Ihr solltet zum Aufbruch bereit sein. Bestellt Pozzik schöne Grüße und sagt ihm, wenn er etwas braucht, soll er keine Hemmungen haben, zu fragen. Ich warte auf die baldige Nachricht, dass er den Streckenrekord gebrochen hat!", sourceObjective = "Bringt die Blaupausen der Treibstoffeinspritzpumpe zu Pozzik in der schimmernden Ebene.", progress = "{name}! Habt Ihr die Treibstoffeinspritzpumpe aufspüren können?", completion = "Ich hatte gehofft, sie wäre schon zusammengebaut, aber dies bietet die einmalige Gelegenheit, die Pläne von Grund auf zu verbessern. Danke, {name}. Ich werde einige verbesserte Baupläne skizzieren, das Ding bauen und es schon bald installieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[1184] = { id = 1184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teile des Schwarms", description = "Geht zurück zu Belgrom in Orgrimmar und sagt ihm, dass Moktar in Tausend Nadeln ganz in seinem Sinne handelt. Sagt ihm auch, dass meine Studien voranschreiten und ich hoffe, dass ich bald mehr gelernt habe. Das sollte ihn freuen.", sourceObjective = "Kehrt zu Belgrom Rockmaul in Orgrimmar zurück.", completion = "Ich weiß Eure Anstrengungen zu schätzen, {class}. Der Kriegshäuptling wird gern hören, wie gewissenhaft Ihr Eure Pflicht erfüllt habt.\n\nOh, gewiss werde ich ihm Euren Namen nennen. Er spricht oft mit mir und schätzt meine Meinung hoch.\n\nGeht jetzt, ich habe viel Arbeit vor mir. Und wenn Ihr demnächst mit Korran sprecht und er Neuigkeiten über diese Kreaturen hat, dann kommt wieder zu mir - ich meine, sie sind eine Bedrohung, die man ernst nehmen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[1185] = { id = 1185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter dem Chitin war...", sourceObjective = "Ah, Ihr seid es wieder! Ja, Euch meine ich - also Euch, {name}! Ja, Euereiner!\n\nHe, ich fang noch mal von vorn an!\n\nDas Objekt, das Ihr in Silithus fandet - war in der Tat ein Buch. Es war ein in einem sehr alten Dialekt verfasstes Tagebuch, wir nennen die Sprache heute Darnassisch. Es wird eine Weile dauern, aber ich werde es sehr sorgfältig studieren. Ich dachte, Ihr solltet wissen, dass Euer Fund für den Zirkel äußerst wertvoll ist.\n\nDie Höhlenmutter ist völlig aus dem Häuschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1186] = { id = 1186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der achtzehnte Rennfahrer", description = "Ich werde damit beschäftigt sein, diese neue Treibstoffeinspritzpumpe in unsere Rennwagen einzubauen, aber wenn Ihr dem Team noch weiter helfen möchtet, sprecht mit Razzeric. Er ist unser Fahrer - unser achtzehnter Fahrer, um genau zu sein -, und er nimmt selbst gern Veränderungen an den Rennwagen vor.\n\nAber er ist ein wenig daneben, bemüht Euch daher, nicht zu überrascht zu wirken.", sourceObjective = "Sprecht mit Razzeric in der schimmernden Ebene.", completion = "Ihr, {race}, habt Pozzik geholfen, richtig? Ich war einst wie Ihr, rannte in der Boxengasse herum und machte jede Arbeit, die die Mechaniker mich tun ließen.\n\nJetzt seht mich an! Der Super-Rennfahrer des Goblin-Teams!", sourceObjectiveStatus = "unverified-source-field" }
quests[1187] = { id = 1187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razzerics Basteln", description = "Pozzik ist ein toller Mechaniker, das weiß ich, aber er hat Angst davor, einfach was mit viel Power einzubauen und dann loszudüsen. Aber ich nicht.\n\nWenn Pozzik mit einem Rennwagen fertig ist, nehme ich mir die Zeit und baue eigene Veränderungen ein - Ihr wisst schon, die Steuerung lockern, Teile des Rahmens entfernen und ihm mehr Saft geben!\n\nIch habe einen Zephyriumnachbrenner von Shreev im Gizmorium in Gadgetzan bestellt, aber offenbar musste der Zeppelin, mit dem er geschickt wurde, in den Marschen von Dustwallow notlanden! Ich muss das Ding haben, {name}!", sourceObjective = "Bergt den Zephyriumnachbrenner für Razzeric in der schimmernden Ebene.", progress = "Wie soll ich mich auf der Rennstrecke blicken lassen, wenn ich nicht ein bisschen extra Power habe? Ich sage Euch, das ist ein Witz.", completion = "Seht Euch nur diese Schönheit an! Fünfzehn Pfund robustes Zephyriumpulver! Wenn ich das an meinen Rennwagen festschnalle, bezwinge ich die Rennstrecke so schnell, dass ich die Gnome zweimal schlage!", sourceObjectiveStatus = "unverified-source-field" }
quests[1188] = { id = 1188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit zuerst", description = "Doch wartet, was ist das? Shreev hat die Sicherung aktiviert gelassen. Das reduziert die Menge Energie, die ich aus dem Nachbrenner rausholen kann. Ich sagte ihm, ich wollte sie deaktiviert haben! Das ist nicht gut.\n\nIhr müsst das ins Gadgetzan-Gizmorium in der Tanariswüste bringen und es von Shreev entfernen lassen.", sourceObjective = "Bringt den Zephyriumnachbrenner zu Shreev in Gadgetzan.", progress = "Wir Ihr sicher wisst, können im Gizmorium all Eure Tüftlerwünsche erfüllt werden! Wie kann ich Euch helfen?", completion = "Nur Razzeric würde einen Blick darauf werfen und sagen, dass ich eine Art Sicherung eingebaut habe. Dieser Nachbrenner besteht fast ausschließlich aus Zephyriumsprengstoff. Ich habe ihn schon so umgebaut, dass mehr von seiner Ladung bei der Benutzung freigesetzt wird, aber Razzeric ist immer erst zufrieden, wenn alles hundertundzehnprozentig ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[1189] = { id = 1189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit zuerst", description = "So, ich habe getan, was Razzeric wollte. Sagt ihm nur, er soll vorsichtig sein, wenn er das zündet. Wenn er den kleinsten Fehler macht, fährt er nicht los, sondern ist nur noch ein Brandfleck auf der Rennstrecke.\n\nWäre doch ein Jammer, wenn das passiert. Wer weiß, ob unser neunzehnter Fahrer genauso gut wäre?", sourceObjective = "Bringt den umgebauten Zephyriumnachbrenner zu Razzeric in der schimmernden Ebene.", progress = "Könnt Ihr glauben, dass Pozzik einen Eimer Sand in dem Rennwagen verstaute? Wie soll ich Höchstgeschwindigkeit erreichen, wenn ich einen Eimer Sand unter dem Sitz habe?", completion = "Ja, das ist schon besser! Könnte ich doch nur die Gesichter der Gnome sehen, wenn ich mit diesem Baby durchstarte.\n\nLeider werde ich voll und ganz damit beschäftigt sein, einen neuen Streckenrekord aufzustellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1190] = { id = 1190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempo halten", description = "Die Brassbolts-Brüder haben einen neuen Baustoff entdeckt, das ist die einzig logische Erklärung. Ihre Rennwagen fahren schneller als vorher, aber Design und alle anderen Daten ihrer Probefahrten sind noch dieselben.\n\nWir wissen, dass Rizzle Brassbolts sich fast ununterbrochen mit den Plänen seiner neuen Entdeckung befasst hat.\n\nZamek kann ein Ablenkungsmanöver inszenieren, damit Ihr diese Pläne von ihnen stehlen könnt.", sourceObjective = "Lasst Zamek ein Ablenkungsmanöver inszenieren und stehlt dann Rizzles Pläne für Pozzik in der schimmernden Ebene.", completion = "Mit einer krakeligen Handschrift hastig hingekritzelte Anmerkungen und eine Notiz-Rolle über die Veredelung eines neuen Rohmaterials.", sourceObjectiveStatus = "unverified-source-field" }
quests[1191] = { id = 1191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zameks Ablenkungsmanöver", sourceObjective = "Auf geht’s!", sourceObjectiveStatus = "unverified-source-field" }
quests[1192] = { id = 1192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Induriumerz", progress = "Ich würde gern in verschiedene Teile unserer Rennwagen Indurium integrieren, brauche aber große Mengen Rohindurium, um diese Teile herzustellen.\n\nIhr findet Indurium in der Ausgrabungsstätte Uldaman im Ödland in Khaz Modan, jenseits des Meeres.\n\nDie Gnomen bekommen ihre eigenen Vorräte, wir müssen daher unbedingt selbst welches haben, um mit ihnen Schritt zu halten.", completion = "Exzellent! Ich lasse die Crew sofort an den Teilen arbeiten, die wir für das nächste Rennen brauchen." }
quests[1193] = { id = 1193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die beschädigte Falle", progress = "Vor Euch liegt eine große, beschädigte Falle. Ihrem Aussehen nach zu urteilen, müssen die Oger versucht haben sie zu reparieren, jedoch ohne Erfolg. Eine hastig geschriebene Notiz liegt neben der Falle. Seltsamerweise beschreibt sie ausführlich was benötigt wird, um die Falle zu reparieren: ein Thoriumapparat und etwas Frostöl. Wäre die Falle wieder repariert, könnte ein verbeikommender Oger darin gefangen und so umgangen werden.\n\nEs ist offensichtlich ein glücklicher Zufall, dass nur die wenigsten Oger lesen können.\n\nOffensichtlich.", completion = "Die Thoriumvorrichtung lässt sich problemlos einfügen, und der so entstehende Hohlkörper eignet sich perfekt, um das Frostöl nach unten abfließen zu lassen. Nachdem der letzte Tropfen Öl hineingeschüttet wurde, lässt sich die Falle wieder einrasten.\n\nWehe dem unvorsichtigen Oger der hier vorbeikommt!" }
quests[1194] = { id = 1194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rizzles Baupläne", description = "Rizzles Baupläne beschreiben den Vorgang der Veredelung von Induriumerz. Man kann dem Gekritzel entnehmen, dass Induriumerz an der Ausgrabungsstätte Uldaman der Zwerge im Ödland zu finden ist.\n\nDie anderen Notizen behandeln fast ausschließlich seinen Hitzewiderstand.\n\nAls Briefbeschwerer der Pläne dient ein Klumpen, der wie unbearbeitetes Induriumerz aussieht.", sourceObjective = "Bringt die Induriumerzprobe zu Pozzik in der schimmernden Ebene.\n\nBereitgestellter Gegenstand:", completion = "Indurium? Interessant... Wenn es wirklich einen so hohen Hitzewiderstand hat, wie Ihr sagt, würde das erklären, warum die Gnome jüngst so deutlich bessere Leistungen erzielten.\n\nDiese Probe, die Ihr mir gebracht habt, ist ebenso von unschätzbarem Wert. Ich werde einige Tests damit durchführen können, aber ich brauche mehr davon, damit es uns tatsächlich von Nutzen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[1195] = { id = 1195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die heilige Flamme", description = "Die Galakzentauren von Tausend Nadeln beschützen ein Artefakt aus der Zeit der Erschaffung der Zentauren.\n\nWir würden es gern bergen, benötigen aber eine Phiole Wasser aus einem der Mondbrunnen der Nachtelfen.\n\nUm dieses Wasser zu beschaffen, müsst Ihr zuerst eine Phiole besorgen, wie sie die Dryaden beim Raynewood im Herzen von Ashenvale besitzen. Am Westufer des Falfarren, südlich der Hauptstraße, befindet sich ein Mondbrunnen, in dem Ihr die Phiole füllen könnt.", sourceObjective = "Bringt eine gefüllte geätzte Phiole zu Zangen Stonehoof in Thunder Bluff.", progress = "Wenn wir die gefüllte Phiole haben, können wir sie zu meinem Mitarbeiter Rau in Tausend Nadeln schicken. Er wollte die Phiole Wasser haben, also sollte er wohl auch wissen, wie wir sie nutzen können.", completion = "Sehr gut. Damit sollte Raus Bitte erfüllt sein. Könntet Ihr dies zu ihm bringen? Vielleicht genießt Ihr ja einen Ausflug nach Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1196] = { id = 1196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die heilige Flamme", description = "Bringt die gefüllte Phiole zu Rau Cliffrunner beim Freiwindposten im Südosten von Tausend Nadeln. Ihr gelangt nach Tausend Nadeln, wenn Ihr den großen Aufzug am Südrand des Brachlandes benutzt.\n\nIch wäre nicht überrascht, wenn Ihr uns weiter behilflich sein könntet.", sourceObjective = "Bringt die gefüllte geätzte Phiole zu Rau Cliffrunner im Freiwindposten.", progress = "Ich nehme nicht an, dass Zangen Euch geschickt hat, hm?", completion = "Hm, ja, diese Phiole Wasser sollte für unsere Zwecke perfekt genügen. Da Dryaden und Zentauren gemeinsame Vorfahren haben, können wir mit dem Wasser der Mondbrunnen den Schutz der ewigen Flamme durchbrechen, die das Relikt der Zentauren umgibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1197] = { id = 1197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die heilige Flamme", description = "Wenn Ihr das Wasser benutzt, das Ihr mitgebracht habt, könnt Ihr vorübergehend die Flamme löschen, die das Zentaurenrelikt schützt. Aber der Effekt ist nicht von Dauer, daher müsst Ihr rasch handeln.\n\nIhr findet die Spalthufklippe, die Festung der Zentauren, nördlich von hier. Die Flamme wird in der Spalthufhöhle bewahrt, einem schwer bewachten Teil der Klippe.\n\nAber seid vorsichtig, die Zentauren der Galak sind dort in großer Zahl zugegen und dürften etwas, das ihnen so teuer ist, nicht freiwillig hergeben.", sourceObjective = "Holt den gespaltenen Huf für Rau Cliffrunner im Freiwindposten.", progress = "Ich brenne darauf, den gespaltenen Huf in die Finger zu bekommen. Habt Ihr ihn schon genommen?", completion = "Ich spüre eine seltsame Energie aus dem Huf kommen... Zweifellos werden wir durch seine Untersuchung überraschende neue Informationen über die Zentauren erhalten.\n\nMeinen Dank, {name}. Jetzt muss ich die Mysterien enträtseln, die Ihr mir gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1198] = { id = 1198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Thaelrid", description = "Heutzutage kursieren viele Gerüchte über die Vereinigung der Twilight-Hammer und Naga in der Blackfathom-Tiefe an den Küsten von Ashenvale.\n\nMeine Rolle hier bei der Argentumdämmerung besteht darin, so viele Informationen wie möglich zu sammeln, damit wir wissen, wann und wo Hilfe erforderlich ist.\n\nEs ist jetzt Wochen her, seit ich einen Späher losschickte, um die Aktivitäten in der Blackfathom-Tiefe auszuspähen. Argentumwache Thaelrid hat sich noch nicht zurückgemeldet.\n\nMeine anderen Späher sind mit dringenden Angelegenheiten beschäftigt.\n\nSucht und unterstützt Thaelrid für mich, {name}.", sourceObjective = "Sucht Argentumwache Thaelrid in der Blackfathom-Tiefe auf.", completion = "Gut, dass Dämmerungsbehüter Shaedlass Euch geschickt hat. An diesem Ort der Verderbnis wird ein finsterer Plan geschmiedet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1199] = { id = 1199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Twilight fallen", description = "Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder der Twilight-Hammer, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.\n\nWir glauben, dass die Twilight-Hammer sich mit den Naga verbündet haben und sich in der Blackfathom-Tiefe an den Küsten von Ashenvale zusammenrotten.\n\nWelch schändliche Pläne in den Tiefen des alten Tempels auch immer geschmiedet werden, wir müssen sie vereiteln.\n\nFührt Krieg gegen die Hammer und bringt Beweise Eurer Taten mit. Eure Bemühungen sollen reich belohnt werden.", sourceObjective = "Bringt 10 Twilight-Anhänger zu Argentumwache Manados in Darnassus", progress = "Die Blackfathom-Tiefe war einst ein alter Tempel der Nachtelfen. Ehedem befand sich einer der mächtigsten Mondbrunnen darin. Wer weiß, welches Übel die Twilight-Hammer jetzt dort ausbrüten?\n\nHabt Ihr schon Fortschritte bei ihrer Vertreibung erzielt?", completion = "Ihr seid zweifellos von tapferem und edlem Geblüt, {name}. Die Argentumdämmerung dankt Euch für Euren Einsatz gegen das Böse.", sourceObjectiveStatus = "unverified-source-field" }
quests[1200] = { id = 1200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schurkerei in Blackfathom", description = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'Mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.\n\nDie Kultisten der Twilight-Hammer haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'Mai, um Macht zu erlangen.\n\nBitte, erschlagt Kelris und bringt Selgorm in Darnassus seinen Kopf, {name}.", sourceObjective = "Bringt den Kopf des Twilight-Lords Kelris zu Dämmerungsbehüter Selgorm in Darnassus.", progress = "Zeit ist ein kostbares Gut, {class}.\n\nMeine Rolle hier in Darnassus ist es, sicherzustellen, dass die Argentumdämmerung gedeiht und die bösen Mächte aus Kalimdor vertrieben werden.\n\nSagt rasch, was Euer Begehr ist, oder zieht von dannen.", completion = "Kelris entwischt uns schon seit geraumer Zeit.\n\nOffenbar ist Kelris stets dabei, wenn das Böse in dieser Region sein hässliches Haupt erhebt. Eine Zeit lang hielten wir ihn für tot oder vermisst.\n\nDoch dies scheint logisch zu sein. Als Ihr seine Herrschaft beendet habt, habt Ihr vielen Unschuldigen das Leben gerettet.\n\nBeim Licht! Es ist mehr als schändlich, jemanden den Dienern eines Alten Gottes zu opfern, um persönlich Kapital daraus zu schlagen!\n\nIhr habt eine große Tat vollbracht, {name}. Ich salutiere im Namen der Argentumdämmerung vor Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[1201] = { id = 1201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theramores Spione", description = "Die Horde und die Allianz wahren einen brüchigen Waffenstillstand. Beide Seiten liefern sich Scharmützel und heimliche Angriffe. Wir müssen dafür sorgen, dass die Horde stets die Oberhand behält!\n\nJetzt haben wir die Chance, genau das zu tun.\n\nSpitzel der Allianz haben Stellungen östlich des Dorfs Brackenwall bezogen. Sie spionieren das Dorf aus und melden unsere Bewegungen Theramore, was wir nicht dulden können.\n\nJagt die Spitzel und schaltet sie aus. Schickt eine deutliche Botschaft an ihre Vorgesetzten, dass wir die Anwesenheit ihrer Spione nicht dulden!", sourceObjective = "Tötet 9 Spitzel von Theramore und kehrt dann zu Nazeer Bloodpike in Brackenwall zurück.", completion = "Gute Arbeit. Ihre Spitzel sind geschickt, aber nicht gut genug, den wachsamen Blicken der Horde zu entkommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1202] = { id = 1202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Docks von Theramore", description = "{name}, zwei unserer Spione wurden ausgeschickt, um Dokumente von einem Schiff bei den Docks von Theramore zu stehlen. Sie bekamen die Papiere, wurden aber entdeckt und waren gezwungen, die Dokumente ins Meer zu werfen.\n\nSpäter konnte ein Spion entkommen, die Beute aber nicht bergen. Er informierte mich über sein Scheitern und jetzt gebe ich Euch die Aufgabe.\n\nDie Dokumente sind in einer Schließkiste irgendwo im Wasser unter den Docks von Theramore. Sucht diese Dokumente, {name}, und bringt sie mir.", sourceObjective = "Bringt die Dokumente des Kapitäns zu Nazeer Bloodpike in Brackenwall.", progress = "Habt Ihr die Dokumente gefunden, {name}? Sie enthalten Informationen, die wichtig für die Stabilität der Allianz, und damit auch wichtig für die Sicherheit der Horde sind.", completion = "Ich bewundere Euch, {name}. Dies war keine leichte Mission. Aber die Dokumente, die Ihr gerettet habt, werden von unseren Vorgesetzten hoch geschätzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1203] = { id = 1203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl braucht eine Klinge", description = "Ich habe zu schneiden. Ich kann Euch nicht sagen, was ich schneiden werde, aber... Ich brauche eine Klinge. Eine ganz bestimmte Klinge...\n\nManche Leute sprechen von einem Mondstahlbreitschwert. Ich nenne es eine Schwingklinge.\n\nHelft Ihr mir? Vielleicht findet Ihr sie in der Stadt, vielleicht sprecht Ihr mit einem Schmied und er macht sie eigens.\n\nAber schlaft nicht noch darüber. Was ich schneide, das hält nicht ewig...", sourceObjective = "Bringt ein Mondstahlbreitschwert zu Jarl in den Marschen von Dustwallow.", progress = "Habt Ihr meine Klinge???", completion = "Das ist eine gute Klinge. Sie schwingt gut. Es ist eine gute Schwingklinge. Danke. Danke, danke, danke!!! Jetzt möchte ich sie ausprobieren... \n\nSpäter. Ich probiere sie später aus. Aber wie ich schon sagte... danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[1204] = { id = 1204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammpanzersuppe mit Käfern", description = "Ich arbeite an einem Gericht namens \"Schlammpanzersuppe mit Käfern\". Die wichtigsten Zutaten fehlen mir leider noch immer... aber ich glaube nicht, dass ich einen Fußmarsch durch die Dustwallow-Marschen durchhalten könnte.\n\nNun denn, {name}, könntet Ihr für mich auf die Jagd gehen? Als Erstes brauche ich die Zungen von Schlammpanzerschildkröten. Ihr findet die Schlammpanzer entlang der Küste, hauptsächlich im Bereich der Bucht.\n\nAber ich will nicht jede beliebige Zunge! Ich habe gehört, dass die Zungen von einigen Schlammpanzerschildkröten gespalten sind...\n\nMan sagt, diese gespaltenen Zungen hätten einen charakteristischen Geschmack, und den möchte ich in meinem Gericht...", sourceObjective = "Bringt Morgan Stern in Theramore 8 gespaltene Schlammpanzerzungen.", progress = "Habt Ihr die gespaltenen Zungen gefunden?", completion = "Diese sind ganz exzellent! Danke, {name}!\n\nJetzt werde ich versuchen, durch verschiedene Kochtechniken herauszufinden, wie ihr Geschmack am besten zur Geltung kommt.\n\nVielleicht werde ich ein Gericht kreieren, das des Blauen Eremiten in Stormwind würdig ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[1205] = { id = 1205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammwühler", description = "Schlammwühler ist ein uralter Krokilisk in den Marschen von Dustwallow. Und seine Zeit zum Sterben ist gekommen.\n\nAlte Knochen knirschen, wenn er seinen gewaltigen Leib durch den Sumpf schleppt, und auch wenn er sich noch mit der Kraft und dem Tempo der Jugend bewegt, martert sein alter Körper den großen innewohnenden Geist, ein Geist, dessen Flamme nicht erlischt.\n\nHeutzutage jedoch leidet er unablässig qualvolle Schmerzen. Ihr müsst das Leben dieser edlen Kreatur beenden, {name}. Ihr müsst Schlammwühler Frieden geben.", sourceObjective = "Bringt Schlammwühlers Zahn zu Melor in Thunder Bluff.", progress = "Habt Ihr den Zahn von Schlammwühler, {name}? Habt Ihr das Leiden der Kreatur beendet?", completion = "Sehr gut, {name}.\n\nIch bin sicher, die Jagd war nicht leicht, aber es ist gut zu wissen, dass der Schmerz des Tieres ein Ende gefunden hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[1206] = { id = 1206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl braucht Augen", description = "Augensaft ist ein guter Saft zum Trinken. Leider haben die meisten Tierwesen nur zwei Augen.\n\nAber Spinnen haben eine Menge Augen. Jede Menge. Und Graunebelaugensaft ist lecker. Samtig und salzig! Unzerplatzte Spinnenaugen... Ich schmecke sie schon förmlich.\n\nGraunebelspinnen leben westlich von hier in den Graunebelhöhlen. Glaubt Ihr, die Spinnen wurden nach der Höhle benannt... oder ist es umgekehrt?", sourceObjective = "Bringt 40 unzerplatzte Graunebelaugen zu \"Sumpfauge\" Jarl im Swamplight-Anwesen.", progress = "Wo sind diese Augen?", completion = "Ihr habt die Augen! Ihr habt die Augen! Leckere, leckere Spinnenaugen!\n\nSchöne Augen... wenn man sie anstarrt, starren sie zurück. Die ess ich zuletzt. Sie leisten einem Gesellschaft... draußen im Sumpf.\n\nHallo, kleine Spinnenaugen. Hallo! Ihr seid so lecker wie Hühnchen. Glibberiges, salziges Hühnchen!\n\nMmmh.", sourceObjectiveStatus = "unverified-source-field" }
quests[1218] = { id = 1218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feine Gewürze", description = "Ich koche gern. Leckere Sumpfküche. Frittierte grüne Froschschenkel und dergleichen.\n\nUnd zum Kochen brauch ich Gewürze. Feine Gewürze. Dann mache ich einen Eintopf und topfe ihn ein und schlabber ihn aus und geb Euch auch was ab.\n\nMögt Ihr Eintopf?", sourceObjective = "Bringt 3 feine Gewürze zu \"Sumpfauge\" Jarl in den Dustwallow-Marschen.", progress = "Gewürz. Wir könnten alle etwas Würze in unserem Leben brauchen. Meint Ihr nicht auch?", completion = "Ah, das ist ein Gewürz! Also, hier haben wir den leckeren sumpfigen Eintopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[1219] = { id = 1219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Orc-Bericht", description = "Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.\n\nDas Pergament ist in der Sprache der Orcs verfasst... und sieht wichtig aus.", sourceObjective = "Bringt den Bericht des Spions zu einem Lieutenant in Theramore.", progress = "Habt Ihr Bericht zu erstatten?", completion = "Hm... Ich kann die Sprache der Orcs nicht sehr gut lesen, aber es scheint ein wichtiger Bericht zu sein... von einem Orc-Spion geschrieben!", sourceObjectiveStatus = "unverified-source-field" }
quests[1220] = { id = 1220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Mumm", description = "Captain Mumm sollte den Orcbericht sehen, den Ihr gefunden habt, {name}. Er kennt die Sprache der Orcs besser als die meisten. Und er sollte wissen, dass sich Spione der Horde bei Theramore aufhalten!\n\nDer Captain befindet sich in der Kaserne auf der nordöstlichen Seite der Insel Theramore.", sourceObjective = "Bringt den Bericht des Spions zu Captain Garran Mumm.", progress = "Habt Ihr etwas für mich?", completion = "Ein Bericht von einem Orc-Spion! Wie habt Ihr den gefunden? Egal - mal sehen, was drin steht...", sourceObjectiveStatus = "unverified-source-field" }
quests[1221] = { id = 1221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blaulaubknollen", description = "Blaulaubknollen gelten auf der ganzen Welt als Delikatesse! Aber sie sind rar, sehr rar. Man findet sie nur hier im Brachland, tief in der Erde des Krals von Razorfen.\n\nUnd selbst dann sind sie fast nicht zu finden, wenn man nicht weiß, wo man suchen muss! Darum habe ich diese Schnüffelnasenziesel abgerichtet, damit sie sie für mich aufstöbern. Sie haben unheimlich empfindliche Nasen und riechen eine Knolle aus fünfzig Schritt Entfernung.\n\nEs wird nicht einfach sein, aber wenn Ihr mir ein paar Knollen bringt, bezahle ich Euch gut dafür.", sourceObjective = "Schnappt Euch eine Kiste mit Löchern.\nSchnappt Euch einen Schnüffelnasenleitstecken.\nSchnappt Euch das Handbuch für Schnüffelnasenbesitzer und lest es.\n\nBenutzt im Kral von Razorfen die Kiste mit Löchern, um ein Schnüffelnasenziesel zu beschwören, und benutzt den Leitstecken bei dem Ziesel, damit es nach Knollen sucht.\n\nBringt 6 Blaulaubknollen, den Schnüffelnasenleitstecken und die Kiste mit Löchern zu Mebok Mizzyrix in Ratchet.", progress = "Habt Ihr die Knollen, {name}?", completion = "Prima, Ihr habt sie! Die kann ich meinen Verbindungsleuten für einen satten Preis verkaufen!\n\nDanke für die Lieferung, {name}! Ihr seid ein toller Partner.", sourceObjectiveStatus = "unverified-source-field" }
quests[1222] = { id = 1222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinkis Flucht", description = "Klasse, endlich etwas, das mich nicht essen möchte!\n\nIch brauche Hilfe mit den Tierwesen hier, und Ihr kommt gerade recht, <Jungchen/Lady>.\n\nDer Koch Morgan Stern arbeitet an einem neuen Rezept und hat mich hierher geschickt, um Sumpfbohnenblätter zu sammeln. Ich glaube, er findet sie lecker.\n\nWie auch immer, während ich nach einer Sumpfbohnenpflanze suchte ... Wurde ich umzingelt! Könnt Ihr mir hier raus helfen und auf mich aufpassen, während ich nach den Sumpfbohnen suche?", sourceObjective = "Begleitet \"Stinki\" Ignatz und sprecht dann mit Morgan Stern in Theramore.", completion = "Mr. Ignatz war gerade mit den Sumpfbohnenblättern hier und sagte mir, dass Ihr ihm echt aus der Klemme geholfen habt.\n\nDanke, {name}. Ich werde meinen Onkel bitten, dass er Euch ein Festmahl bereitet, wenn Ihr das nächste Mal den Blauen Eremiten in Stormwind besucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1238] = { id = 1238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Bericht", description = "Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.\n\nDas Pergament ist ein Bericht von einem Orc, der die Stadt Theramore über Wochen ausspionierte.\n\nAls Ihr das Pergament überflogen habt, ist klar, dass es zum Orc-Spionagemeister in Brackenwall gebracht werden muss.", sourceObjective = "Bringt den Bericht des Spions zu Nazeer Bloodpike in Brackenwall.", progress = "Habt Ihr etwas für mich?", completion = "Gute Arbeit, {name} . Unser Agent Marg Nighteye war außerhalb von Theramore stationiert. Seine Aufgabe war es, die Stadt auszuspionieren. \n\nDas ist sein jüngster Bericht und könnte sein letzter sein; nach Eurer Aussage fürchte ich, dass Marg im Sumpf sein Ende fand...", sourceObjectiveStatus = "unverified-source-field" }
quests[1239] = { id = 1239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der abgetrennte Kopf", description = "Ausgiebiges Graben fördert den Kopf eines männlichen Orcs zu Tage, der am Hals abgesägt worden war. Seine Lippen sind zu einer höhnischen Grimasse verzerrt, seine dunklen Augen blicken trotzig.", sourceObjective = "Bringt den Kopf des aufsässigen Orcs zu Nazeer Bloodpike in Brackenwall.", progress = "Habt ihr noch etwas zu berichten, {name}?", completion = "Dies ist der Kopf von Marg Nighteye! Er ist tot, wie ich befürchtete.\n\nSeht euch die Wunde an seinem Hals an! Kann eine Waffe diesen ausgefransten Schnitt gemacht haben, oder wurde unser Agent von einer Bestie angefallen?\n\nDas ist ein Rätsel, das wir lösen müssen, {name}! Wir müssen herausfinden, ob Marg durch die Hände der Allianz starb!", sourceObjectiveStatus = "unverified-source-field" }
quests[1240] = { id = 1240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Troll-Hexendoktor", description = "Wir müssen die Umstände von Margs Tod erfahren! Und das können wir nur, {name}, durch die Hexenmagie der Trolle.\n\nBringt Margs Kopf zu Kin'weelay im Schlingendorntal im Basislager von Grom'gol.\n\nKin'weelay ist der mächtigste Hexendoktor der Darkspeartrolle. Wenn jemand mit Marg Nighteyes Geist sprechen kann, dann er.", sourceObjective = "Bringt den Kopf des aufsässigen Orcs zu Kin'weelay im Schlingendorntal im Basislager von Grom'gol.", progress = "Ihr habt einen wütenden Geist um Euch, Bruder. Was führt Euch zu Kin'weelay?", completion = "Ah, jetzt verstehe ich. Der Geist dieses Orcs ist an unsere Welt gebunden und kocht vor Wut über eine nicht erledigte Aufgabe.\n\nDann reden wir einmal mit diesem wütenden Orc...", sourceObjectiveStatus = "unverified-source-field" }
quests[1241] = { id = 1241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Kürzlich wurde ein Diplomat nach Theramore geschickt, um sich mit Jaina Proudmoore zu treffen. Dieser Diplomat kam nie an.\n\nIch glaube, die Defias sind in diese Verschwörung verwickelt, weiß aber nicht, wie. Das Verschwinden des Diplomaten wurde noch nicht publik, aber lange kann das nicht mehr so bleiben.\n\nAgenten des Königs durchkämmen die Stadt bereits nach Hinweisen, aber ich habe eigene Verbindungsleute, die ich gern einschalten würde.\n\nIm Tal der Helden lebt ein alter Freund von mir namens Jorgen. Sucht ihn, gebt ihm diese Notiz und folgt seinen Anweisungen.", sourceObjective = "Sucht Jorgen in der Stadt Stormwind.", progress = "Hmpf, hoffentlich habt Ihr einen guten Grund, einen Mann beim Angeln zu stören. Ich reagiere ungehalten auf Schnüffler, von Bettlern ganz zu schweigen.", completion = "Hmm... <Jorgen schaut mit zusammengekniffenen Augen zu Euch auf.>\n\nNun gut. Ich helfe Euch, aber nicht, weil ich es will, sondern weil ich verpflichtet bin.\n\nUnd lasst uns eines klarstellen: Ihr wisst viel mehr als Ihr eigentlich solltet. Betrachten wir dies als unser kleines Geheimnis. Plappert nicht in irgendwelchen Tavernen über das, was Ihr herausfindet. Kapiert?", sourceObjectiveStatus = "unverified-source-field" }
quests[1242] = { id = 1242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Bringt diese Notiz zu Elling Trias. Sagt sonst nichts zu ihm. Seid nur höflich und wartet auf seine Antwort. Und keine Bange, er wird antworten.\n\nIch sage Euch das nur noch einmal, {name}: nehmt diese Sache ernst und haltet die Klappe.\n\nIhr findet Trias in seinem Käseladen, Trias' Käse, im Handelsdistrikt. Viel Glück.", sourceObjective = "Bringt Jorgens versiegelte Notiz zu Elling Trias in der Stadt Stormwind.", progress = "Hallo, {name}. Kann ich etwas für Euch tun? Vielleicht würdet Ihr gern unseren speziellen Trias-Cheddar kosten? Oder ein Stück Darnassus-Blauschimmelkäse?", completion = "Pardon, ein Brief für mich? Also da soll mich doch... wenn man arbeitet, bekommt man nicht oft eine Zustellung, die keine Kiste oder ein Fass ist. Mal sehen, worum es geht.\n\n<Elling schaut zu Euch auf, während er den Brief öffnet.>\n\nIhr seht ein wenig nervös aus, alles klar, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[1243] = { id = 1243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Jorgen, alter Pickel! Aha, so soll es also sein, hm?\n\nNa gut, damit kann ich leben. Ich hoffe, er findet den wirbelnden Nether umso früher!\n\nSo wird es ablaufen, {name}. Ich werde meine Verbindungsleute hier kontaktieren, aber Ihr werdet den Großteil der Beinarbeit erledigen, damit ich ein wenig spare.\n\nGeht nach Dunkelhain im Dämmerwald und sucht Behüter Backus - er patrouilliert meist auf der Nordstraße vor der Stadt. Sagt ihm nur, dass Ihr für mich die Aktivitäten der Defias untersucht, dann wird er Euch mit allen verfügbaren Informationen weiterhelfen.", sourceObjective = "Gebt Behüter Backus im Dämmerwald die versiegelte Notiz.", progress = "Es ist nicht eben sicher, durch den Wald zu reisen, {name}. Seid vorsichtig, und wenn Ihr etwas Verdächtiges oder Seltsames seht, meldet es sofort den Behütern. Versucht nicht, auf eigene Faust zu handeln. Wir tragen keine Verantwortung, wenn Euch etwas Schreckliches zustößt.\n\nAber wir wissen beide, dass Ihr nicht auf meine Worte hören und gegen alles kämpfen werdet, was aus der Dunkelheit kommt, nicht? Haha, ja, ihr Abenteurer-Typen ... ihr seid alle gleich.", completion = "Oh, Trias schickt Euch, hm? Das ist etwas anderes.\n\nDann könnt Ihr gegen alle Monster kämpfen, die aus der Dunkelheit kommen mögen. Ich bin sicher, Ihr werdet leicht damit fertig, wenn Ihr der Typ seid, der gern mit seinesgleichen herumhängt.\n\nAlso, was braucht mein Freund an einem so düsteren Tag wie diesem?", sourceObjectiveStatus = "unverified-source-field" }
quests[1244] = { id = 1244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Defiasaktivität? Es gibt immer etwas Aktivität; selbst wenn sie unter sich bleiben, betrachten wir sie als Bedrohung.\n\nAber jetzt, wo ich darüber nachdenke, kam es jüngst zu einer seltsamen Beobachtung. Es muss so zwei Wochen her sein, da hatten sich einige ihrer Agenten in Addles Siedlung versammelt. Dem Bericht glaubte ich zu entnehmen, dass etwas Großes vor sich ging.\n\nWarum seht Ihr da nicht zuerst nach und bringt mir alles, was Ihr findet?\n\nDer Bauernhof liegt südlich der Straße von Westfall direkt am Rand des Dämmerwalds.", sourceObjective = "Sucht die Liste der Defias und kehrt zu Behüter Backus im Dämmerwald zurück.", progress = "Seid vorsichtig da draußen, {name}. Ich weiß, dass Trias Euch hergeschickt hat, aber das bedeutet nicht, dass es da draußen im Wald nichts gibt, das Euch Ärger machen könnte... besonders wenn Ihr die Defias untersucht.", completion = "Ihr seid heil und gesund zurück. Mehr konntet Ihr nicht verlangen, meint Ihr nicht auch?\n\nDann sehen wir mal, was wir hier haben. Das sieht ziemlich offiziell aus, wenn mich meine Erfahrung mit Defiasdokumenten nicht trügt. Es könnte jedoch auch eine Finte sein, um Euch von der Fährte abzubringen, auf die Ihr bei Eurer Suche gestoßen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[1245] = { id = 1245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Boah, das sieht zu komplex aus, um Euch nur auf eine falsche Fährte zu locken. Ich sollte das nicht einmal ansehen. Sprecht mit Trias - er kann es bestimmt verstehen. Und lasst Euch durch NICHTS aufhalten. Dies ist größer als ich. Vielleicht sogar größer als er, aber wir werden sehen.\n\nUnd tut mir einen Gefallen, {name}, sagt keinem, dass ich Euch geholfen habe. Wenn meine Vorgesetzten erfahren, dass ich davon wusste und sie nicht informiert habe, hängen sie mich wahrscheinlich.", sourceObjective = "Bringt die Liste der Defias zu Elling Trias in Stormwind.", progress = "Ich sehe, Ihr seid in einem Stück zurück. Wir wissen beide, dass Ihr nicht wegen Käse hier seid, beenden wir also das Plaudern. Konnte Backus Euch helfen oder seid Ihr noch gar nicht im Dämmerwald gewesen?", completion = "Ja... das ist interessant zu lesen. Jorgen und DeLavey waren klug, mich einzuweihen.\n\nOffenbar haben sich die Defias sehr bemüht, ihren Plan hier abzuschließen. Hmm... was ist das? \"Fist\"? Das ist ein vertrauter Name.", sourceObjectiveStatus = "unverified-source-field" }
quests[1246] = { id = 1246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Ja, jetzt, wo ich darüber nachdenke... Dashel... Dashel irgendwas... Wie war sein Name? FIST! Dashel Stonefist. In manchen Kreisen nennen sie ihn Fist - wahrscheinlich, weil er ein Raufbold ist.\n\nIhr könnt ihn normalerweise in der Altstadt finden - direkt mitten im Zentrum. Redet mit ihm. Wenn es sein muss, dann benutzt ein Schwert oder etwas Schweres und Stumpfes, um ihn zum Reden zu bringen. Und zögert nicht. Wenn er so tief drinsteckt, wie diese Papiere andeuten, wird er Euch freiwillig keine Informationen geben.", sourceObjective = "Sprecht mit Dashel Stonefist in Stormwind.", completion = "Was?!\n\nIhr kommt in meine Gasse und stellt Fragen nach meinen persönlichen Angelegenheiten? Angelegenheiten, mit denen Ihr offenkundig nichts zu tun habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1247] = { id = 1247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Ja, also... hm... Vielleicht weiß ich was über dieses Treffen in Addles Siedlung. Das war, glaube ich, vor ein paar Wochen. Ich hatte wirklich nichts damit zu tun. Meine Rolle war vorbei, als Plan A schief ging... verdammte Abenteurer.\n\nDer Kerl, den wir für Plan B hatten, kam aus Menethil; ein Typ namens Slim. Mehr weiß ich nicht über ihren Ersatzplan.", sourceObjective = "Sprecht mit Elling Trias in Stormwind.", completion = "Wie schön, dass Ihr noch am Leben seid, {name} . Mit Dashel lief demnach alles gut, hm?\n\nIch habe mehr über ihren Plan nachgelesen. Der Name des Diplomaten, auf den sie es abgesehen hatten, wurde zwar nicht genannt, aber es ist von einem Plan B die Rede, der zur Ausführung kam, nachdem der erste Versuch, ihn zu entführen, gescheitert war.\n\nDieser Slim, von dem Dashel sprach, hat hier keinen anderen Namen angegeben, aber wenn Ihr sagt, dass er in Menethil ist, ist das ein Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[1248] = { id = 1248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Ein Verbindungsmann von mir verbringt seinen Ruhestand in der Hafenstadt Menethil im Sumpfland. Er sollte Euch auf Euer Wort hin helfen, wenn Ihr ihm sagt, dass Ihr für mich arbeitet. Sein Name ist Mikhail. Bevor er Stormwind vor ein paar Jahren verließ, erwähnte er, dass er Schankkellner werden wollte.\n\nSprecht mit ihm, sucht diesen Slim und findet heraus, ob es noch etwas über diesen entführten Diplomaten zu wissen gibt. Wir müssen herausfinden, wohin sie ihn gebracht haben, oder wenigstens, wer er ist. In der Liste steht nichts von ihren Plänen nach seiner Entführung.", sourceObjective = "Sprecht mit Mikhail im Sumpfland.", completion = "Willkommen, willkommen, willkommen, {name}. Schön, dass Ihr Euch uns anschließt. Vielleicht heute ein kühles Bier. Oder etwas Hammel?\n\nNennt mir Euren Wunsch und ich sorge dafür, dass er erfüllt wird. Mein Name ist Mikhail und ich freue mich darauf, Euch zu bedienen.\n\nHmm? Wie war das? Trias? So sprecht doch leiser. Es soll doch nicht die ganze Taverne davon hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[1249] = { id = 1249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Ihr sagt, Elling hat Euch geschickt? Dann soll Euch meine Gastfreundschaft zehnfach zuteil werden. Wenn Ihr etwas braucht, fragt nur. Ich tue mein Bestes, Euch zu unterstützen.\n\nHmm, Slim sagt Ihr? Bei dem Namen klingelt nichts, aber ich werde nach ihm Ausschau halten.\n\nSchaut jetzt nicht hin, {name}, aber der Herr dort am Ausgang sieht herüber. Er folgt unserer Unterhaltung etwas zu intensiv, wenn Ihr versteht, was ich meine. Ich an Eurer Stelle würde tun, was ich kann, um ihn zu schnappen, bevor er zur Tür flieht.", sourceObjective = "Schnappt Tapoke Jahn bevor er entkommt und kehrt dann zu Mikhail in Menethil zurück.", progress = "Ist er entronnen? Sah ein wenig zwielichtig aus, wie er uns beobachtet hat.", completion = "Habt ihn erwischt, hm? Gut für Euch. Ich bin überrascht, dass das Slim war.\n\nIch will ehrlich sein, ich hätte nie gedacht, dass ich die Aufregung der unaufrichtigen Untergrundaktivitäten vermissen würde. Alte Gewohnheiten wird man wohl nicht so leicht los. Aber sagt Elling nichts davon - wenn er hört, dass mir die Aufregung fehlt, versucht er wahrscheinlich, mich wieder nach Stormwind zu locken.\n\nIch bin froh, dass ich Euch in Menethil wenigstens ein wenig zu Diensten sein konnte. Wenn Ihr noch etwas braucht, fragt nur.", sourceObjectiveStatus = "unverified-source-field" }
quests[1250] = { id = 1250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Die Defias zahlten mir nicht genug, um für diese Sache zu sterben. Sie entführten den König. Ja, den König von Stormwind, keinen kleinen Diplomaten. Er war auf dem Weg nach Theramore, um sich mit Jaina Proudmoore zu treffen - offenbar eine große Sache und streng geheim. Aber es sind nicht nur die Defias darin verwickelt. Sie arbeiten mit jemandem zusammen. Ich glaube, sie wussten, dass das ihre Kräfte übersteigt.\n\nMeine Aufgabe war es, ihren Mann an Bord des königlichen Schiffes zu bringen, als es im Hafen lag. Der Typ hieß Hendel. Mehr weiß ich nicht. Ich schwöre es!", sourceObjective = "Sprecht mit Mikhail im Sumpfland.", completion = "DER KÖNIG?! Ich meine... der König? Der echte König? Ist das ein Witz? Ihr habt nicht erwähnt, dass Ihr die Entführer des Königs sucht. Ich habe nicht einmal gehört, dass er vermisst wird - das würde erklären, warum bald sein Sohn gekrönt wird.\n\nIch werde Elling sofort informieren. Er sollte wissen, dass Ihr die Spur verfolgt.\n\nIch hätte nie gedacht, dass Jahn Stormwind nur des Geldes wegen verkaufen würde. In manchen Dingen muss doch selbst ein Schurke Ehrgefühl besitzen.\n\nJetzt ist es entscheidend, diesen Hendel zu finden. Und ich denke, da kann ich Euch helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1251] = { id = 1251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ein Eisenschild, vom Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus Zur süßen Ruh war.\n\nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.", sourceObjective = "Bringt den geschwärzten Eisenschild zu Krog in Brackenwall.", progress = "Was habt Ihr denn da, {name}? Beweismittel aus den Trümmern des Gasthauses Zur süßen Ruh?", completion = "Ich gebe ja zu, dass Menschen einen merkwürdigen Geschmack bei der Dekoration haben, aber würden sie einen einfachen Eisenschild benutzen, um ihren Feuerplatz zu schmücken? Vielleicht haben jene, die das Gasthaus niederbrannten, den Schild dort befestigt.\n\nEine Warnung? Eine Drohung?", sourceObjectiveStatus = "unverified-source-field" }
quests[1252] = { id = 1252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenant Paval Reethe", description = "Unter dem Geröll sticht Euch ein Funkeln ins Auge. Kaum sind Schmutz und Asche von dem Objekt gewischt, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.\n\nUnter dem Anker ist der Name \"Lieutenant Paval Reethe\" eingeprägt.", sourceObjective = "Bringt Reethes Abzeichen zu Captain Garran Mumm in Theramore.", progress = "Habt Ihr etwas Interessantes im Gasthaus Zur süßen Ruh gefunden?", completion = "Es bedeutet selten etwas Gutes, wenn mir das Abzeichen einer Wache gebracht wird.\n\nManchmal bedeutet es, dass ein Mann oder eine Frau im Kampf gefallen ist und ich der trauernden Familie die Nachricht überbringen muss. Manchmal erfahren wir nie, was ihnen zugestoßen ist. Und manchmal ist es sogar noch schlimmer.", sourceObjectiveStatus = "unverified-source-field" }
quests[1253] = { id = 1253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ein Eisenschild, vom Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus Zur süßen Ruh war.\n\nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.", sourceObjective = "Bringt den geschwärzten Eisenschild zu Captain Garran Mumm in Theramore.", progress = "Habt Ihr Beweise im ehemaligen Gasthaus Zur süßen Ruh gefunden?", completion = "Hm, ich bin kein Experte für die Herstellung von Waffen und Rüstungen. Für ihre Anwendung, ja, aber nicht für die Herstellung.\n\nDer Schild scheint ganz gewöhnlich wie jeder andere zu sein, abgesehen vom Schaden durch das Feuer, das das Gasthaus verwüstete.", sourceObjectiveStatus = "unverified-source-field" }
quests[1258] = { id = 1258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...und Käfer", description = "Eine weitere Komponente meines neuen Rezepts ist das gepanzerte Bein eines Riesenkrebses. Und die Krebse, die sie in Dustwallow haben - Matschpanzer nennen sie sie -, taugen einfach nichts! Ich fürchte, die einzigen akzeptablen Krebse leben in den Sümpfen des Elends.\n\nDie Schale des Krebsbeins ist das wichtigste Element der Präsentation des Gerichts, daher brauche ich makellose, unverletzte Beine. Ein ausgewachsener Krebs hat möglicherweise nur ein oder zwei Beine, die in Frage kommen, aber ich brauche viel mehr für mein Gericht.\n\nAlso, {name} ... seid Ihr bereit für eine Reise?", sourceObjective = "Bringt 12 makellose Kriecherbeine zu Morgan Stern in Theramore.", progress = "Meine Experimente mit den Schlammpanzerzungen machen gute Fortschritte. Ich hoffe, Eure Krebssuche kommt voran?", completion = "Das sind wunderbare Exemplare, {name}! Die Schalen sind in perfektem Zustand, das Fleisch ist rosa und zart. Ich bin sicher, das Blut eines Küchenchefs fließt in Euren Adern!", sourceObjectiveStatus = "unverified-source-field" }
quests[1259] = { id = 1259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenant Paval Reethe", description = "Ich kenne den Namen Lieutenant Paval Reethe nicht. Am besten erkundigt Ihr Euch bei Adjudant Tesoran. Er hat alle Aufzeichnungen über die Wachen von Theramore, vom Personal bis hin zur Ausrüstung.\n\nEr sollte Euch nach einem Blick in seine Bücher sagen können, wer dieser Reethe ist.", sourceObjective = "Findet bei Adjudant Tesoran in Theramore mehr über Reethe heraus.", completion = "Hallo, {name}. Ihr möchtet Informationen über ein bestimmtes Mitglied der Wache von Theramore? Reethe, richtig?\n\nBitte habt einen Moment Geduld, bis ich das richtige Buch gefunden habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[1260] = { id = 1260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan Stern", description = "Ich entwickle ein neues Menü für das Restaurant. Es soll aus regionalen Gerichten mit einem Hauch von \"Bayou\" bestehen. Ich glaube, meine Kunden im Blauen Eremiten werden es lieben!\n\nIch schickte meinen Neffen Morgan nach Theramore, einer Stadt am Rand der Dustwallow-Marschen. Er sammelt die Rezepte der Einheimischen und ich muss wissen, was er bisher gefunden hat.\n\nDie Reise nach Theramore ist lang. Zu lang für mich. Aber ich wette, ein {class} wie Ihr einer seid, nutzt jede Chance für eine Reise, ja?", sourceObjective = "Sprecht mit Morgan Stern in Theramore.", completion = "Oh, mein Onkel hat Euch geschickt, nicht?\n\nIch habe mich um die Rezepte gekümmert und ein paar Hinweise, aber ich brauche Hilfe.\n\nHilfe von jemandem, der keine Angst vor nassen Füßen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[1261] = { id = 1261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marg spricht", description = "Verfluchter Matschpanzer! Man kann Marg nicht töten! Ah, aber ich bin tot. Also muss er mich getötet haben...\n\nAber meine Mission! Meine Mission! Ihr, {name}, müsst sie beenden.\n\nIn der Nähe von Theramore sah ich eine Gruppe Soldaten der Allianz am Ufer kampieren. Ein Soldat trug einen Anhänger... einen Anhänger mit mehr Edelsteinen, als ihn sich ein Soldat leisten könnte!\n\nIn jener Nacht schlich ich in ihr Lager und stahl den Anhänger, aber nach meiner Rückkehr zum Stützpunkt tötete mich ein Matschpanzerkrebsmann!\n\n{name}, Ihr müsst diesen Matschpanzer finden und den Anhänger retten!", sourceObjective = "Bringt den juwelenbesetzten Anhänger zu Nazeer in Brackenwall.", progress = "{name}, habt Ihr etwas über Margs Schicksal erfahren?", completion = "Dieser Anhänger wurde von einem Soldat aus Stormwind getragen???\n\nDanke, {name}. Ihr habt die Umstände von Margs Tod enträtselt! Doch dieser Anhänger ist ein neues Rätsel, das es zu lösen gilt, und es könnte schlimme Auswirkungen auf die Allianz und die Horde haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[1262] = { id = 1262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei Zor melden", description = "Wie seltsam, dass sich der Anhänger, den Marg stahl, in den Händen eines gemeinen Soldaten befand. Vielleicht hatte sich sein Besitzer verkleidet, oder die Soldaten selbst hatten ihn gestohlen!\n\nWas auch immer, dies ist der Anhänger eines Adligen und wir müssen seinen wahren Besitzer finden, wenn wir das Rätsel lösen wollen.\n\nBringt den Anhänger zu Zor Lonetree in Orgrimmar. Er ist mit der Politik der Allianz vertraut und wird wissen, ob dieser Anhänger etwas mit der Geschichte der Adligen von Stormwind zu tun hat.", sourceObjective = "Bringt den Edelstein-Anhänger zu Zor Lonetree in Orgrimmar.", progress = "Ihr seid von Brackenwall in Dustwallow hierher gereist? Wie geht es Nazeer und wie weit sind seine Bemühungen im Sumpf gediehen?", completion = "Dieser Anhänger wurde mit großem Geschick und Präzision gefertigt, {name}. Kein Orc würde so ein Schmuckstück begehren...\n\nAber viele Menschen könnten es.\n\nIch werde diesen Anhänger untersuchen lassen. Hoffen wir, dass er uns bald seine Geheimnisse preisgibt...", sourceObjectiveStatus = "unverified-source-field" }
quests[1263] = { id = 1263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das brennende Gasthaus <ZU TRATSCH WECHSELN>" }
quests[1264] = { id = 1264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Am Anfang jedes Monats werden die Marines von Kul Tiras bezahlt und verlassen Theramore meist mit anderen Zielen. Viele kommen hierher, um Frauen aufzureißen, zu zechen und ihren Spaß zu haben. Eine dieser Gruppen betrachte ich als Stammgäste der Taverne, und ich glaube, dieser Hendel ist dabei.\n\nKommandant Samaul in Theramore könnte Euch helfen, ihn zu finden, wenn Hendel noch hier stationiert ist. Er ist Proudmoore treu ergeben, aber wenn Ihr Ellings Namen erwähnt, dürfte er Euch helfen... diskret.", sourceObjective = "Sucht Kommandant Samaul in den Marschen von Dustwallow.", completion = "Welche Freude, Euch zu sehen, {name}. Ich bin Kommandant Samaul. Ich kommandiere Miss Proudmoores Truppen hier in Theramore.\n\nZur Zeit bin ich zwar ziemlich beschäftigt, aber falls Ihr irgendwelche Fragen habt, sprecht mich ruhig an. Möglicherweise muss ich es kurz machen, aber ich will Euch gern helfen, wenn Ihr Hilfe braucht.\n\nFalls Ihr vorhabt, die Stadt zu verlassen, rate ich Euch, vorsichtig zu sein. Abgesehen von Ogern, Orcs und Murlocs wimmelt es im südlichen Teil des Sumpfs von schwarzen Großdrachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1265] = { id = 1265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Hendel? Ja, ich kenne den Mann. Aber wozu braucht Ihr einen meiner Soldaten?\n\nHat Elling Euch geschickt, ihn zu finden? Hmm, das gefällt mir ganz und gar nicht. Elling hätte Euch nicht zuerst zu mir geschickt, wenn Euer Anliegen nicht beunruhigend wäre. Ich verstehe, wenn Ihr mir nicht sagen könnt, worum es geht, aber denkt daran: Ich muss dieses Land beschützen. Wenn Ihr vorhabt, die Ruhe zu stören, solltet Ihr mich so viel wie möglich wissen lassen.\n\nIch glaube, Hendel war im ersten Turm außerhalb von Theramore stationiert. Seid vorsichtig.", sourceObjective = "Sucht die Späherwacht nach Spuren des Gefreiten Hendel ab.", completion = "Der Mann namens Hendel, den Ihr sucht, ist nicht hier. Andere Quellen lieferten Lady Proudmoore Informationen, die Ihr wohl bereits kennt. Sie bat mich, Euch zu suchen und bei Eurer Mission zu unterstützen. Wenn Ihr gestattet, sage ich Euch, wo Ihr den Gefreiten Hendel finden könnt, damit er seine gerechte Strafe erhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[1266] = { id = 1266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Der Gefreite Hendel hält sich westlich von hier auf. Im Augenblick ist er auf Wache und beschützt einige von Theramores Spitzeln, während sie ausruhen. Sie behalten Brackenwall, den Stützpunkt der Horde, im Auge und suchen nach allem, das unsere Grenzen bedrohen könnte.\n\nIhr müsstet ihn problemlos finden können; sucht einfach nach Zelten am Straßenrand.\n\nIch muss mich um andere Dinge kümmern, stoße aber bestimmt bald zu Euch. Ihr könnt mich immer im Turm von Lady Proudmoore in Theramore finden, falls Ihr Probleme habt.", sourceObjective = "Sucht den Gefreiten Hendel in den Marschen von Dustwallow.", completion = "Seid gegrüßt. Dies ist ein gefährlicher Ort für einen Spaziergang. Ich würde nicht zu lange bleiben, wenn Euch Euer Leben lieb ist.\n\nWenn Ihr Euch auf kurze Fragen beschränkt, will ich sehen, ob ich Euch helfen kann. Haltet nur nach diesen schmutzigen Ogern Ausschau. Gerüchten zufolge gibt es einen Stützpunkt der Horde in den Sümpfen. Die Spitzel tun, was sie können, um ihn zu finden, aber das ist eine langwierige Angelegenheit und wir kommen nicht voran.", sourceObjectiveStatus = "unverified-source-field" }
quests[1267] = { id = 1267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", sourceObjective = "Sprecht mit Jaina Proudmore im Dustwallowsumpf.", completion = "Ich möchte der Erste sein, der Euch für all das dankt, was Ihr geleistet habt, {name}. Erneut wart Ihr ein unglaublicher Segen für mein Volk und die Bewohner von Stormwind. Es tut mir Leid, dass wir uns nicht unter glücklicheren Umständen kennen gelernt haben.\n\nVersteht bitte auch, dass ich Euch nicht offen für Eure Bemühungen danken kann, aber ich möchte Euch nochmals versichern, dass ich sie wohl zu schätzen weiß.\n\nWenn Ihr in Zukunft einmal nach Theramore kommt, schaut unbedingt bei mir herein, dann werde ich versuchen, Euch über die Lage auf dem Laufenden zu halten.\n\nNochmals danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1268] = { id = 1268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdächtige Hufabdrücke", description = "Reihen von Hufspuren führen von den noch rauchenden Überresten des Gasthauses Zur süßen Ruh weg. Wenigstens einige Abdrücke sind klar erkennbar, weitere Reihen sind im weichen Schlamm des Sumpfs kaum zu sehen.", sourceObjective = "Berichtet Krog in Brackenwall von den verdächtigen Abdrücken beim Gasthaus Zur süßen Ruh.", completion = "Hufabdrücke... Ich schätze, das könnten die Stacheleber gewesen sein. Oder vielleicht sogar die Zentauren. Sie sind im Brachland durchaus nicht so selten. So eine Tat zu begehen ist für mich kein kleines Delikt.\n\nSagte ich es Euch schon? Nicht nur das Gasthaus war niedergebrannt... Frau und Kind des Besitzers wurden getötet. Das ist eine schlimme Sache.\n\nDennoch werde ich Kagoro schicken, damit er herausfindet, wohin die Spuren führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1269] = { id = 1269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenant Paval Reethe", description = "Unter dem Geröll sticht Euch ein Funkeln ins Auge. Kaum sind Schmutz und Asche von dem Objekt gewischt, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.\n\nUnter dem Anker ist der Name \"Lieutenant Paval Reethe\" eingeprägt.", sourceObjective = "Bringt Reethes Abzeichen zu Krog in Brackenwall.", progress = "Habt Ihr Hinweise gefunden, was im Gasthaus Zur süßen Ruh passiert ist?", completion = "Ich kenne diesen Menschen Paval Reethe. Jämmerlich, selbst für seine Art. Er ließ seine Kameraden im Stich und versteckt sich jetzt im Wald.\n\nIch schicke Gog'ron los, um ihn aufzuspüren. Einige andere vermuten, dass er unsere Vorräte stiehlt. Ich glaube, ich sah Ogron nach Südosten gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1270] = { id = 1270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinkis Flucht", description = "Klasse, endlich etwas, das mich nicht essen will!!!\n\nIch brauche Hilfe mit den Tierwesen hier, und Ihr kommt gerade recht, <Jungchen/Mädel>.\n\nEin Goblin aus Ratchet namens Mebok Mizzyrix braucht ein paar Sumpfbohnenblätter für einen Trank oder so... Mir ist ganz ehrlich einerlei, warum - er hat gut bezahlt und ich kenne diesen Sumpf, also bin ich hier.\n\nZu dumm, dass ich umzingelt wurde, bevor ich die Sumpfbohnen fand! Könnt Ihr mir hier raushelfen und auf mich aufpassen, während ich nach Meboks Pflanze suche?", sourceObjective = "Begleitet \"Stinki\" Ignatz und sprecht dann mit Mebok Mizzyrix in Ratchet.", completion = "Stinki war mit den Kräutern hier, die ich wollte, und sagte mir, Ihr habt ihn aus einer misslichen Lage befreit. Gute Arbeit! Ein Freund von Stinki ist ein Freund von mir!\n\nEr bat mich, Euch das zu geben, wenn ich Euch sehen sollte, bevor er wieder nach Süden in die Sümpfe ging.", sourceObjectiveStatus = "unverified-source-field" }
quests[1271] = { id = 1271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festmahl im Blauen Eremiten", sourceObjective = "Mein Neffe sagte, Ihr habt ihn bei seiner Suche in Dustwallow unterstützt und seinem Assistenten aus der Klemme geholfen. Also wir Sterns halten zusammen und vergessen unsere Freunde nicht!\n\nAlso wascht Eure Hände, {name}, denn wir geben Euch zu Ehren eine Party!", sourceObjectiveStatus = "unverified-source-field" }
quests[1272] = { id = 1272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Reethe <ZU TRATSCH WECHSELN>" }
quests[1273] = { id = 1273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befragt Reethe", description = "Es hat lange gedauert, aber ich fand Reethe. Für einen Menschen hatte er sich gut versteckt.\n\nOgron hatte Angst, nach der langen Zeit im Sumpf könnte er verrückt sein. Ihr kommt mit mir, denn wir brauchen Antworten von ihm.", sourceObjective = "Geht mit Ogron und sprecht mit Reethe, dann kehrt zu Krog in Brackenwall zurück.", completion = "Hmpf. Es ist gut, dass Reethe nicht mehr im Sumpf herumlungert. Ein Jammer, dass Menschen so empfindlich sind, dass er sich nicht von einer kleinen Pfeilwunde erholen konnte.\n\nScheinbar hat dieser Teil des Rätsels nirgendwohin geführt und wir müssen es anderswo versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1274] = { id = 1274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Pardon, <werter Herr/holde Dame>. Bischof DeLavey bat mich, Abenteurer zu suchen, die ihm in einer delikaten Angelegenheit helfen könnten.\n\nWenn Ihr so gut sein könntet, heimlich zur Burg Stormwind zu reiten und mit ihm zu sprechen, sobald es Euch genehm ist - er wäre Euch sicherlich für Eure Hilfe dankbar. Und nochmals, bitte seid diskret. Es ist eine wichtige Angelegenheit.", sourceObjective = "Sucht Bischof DeLavey in der Burg Stormwind.", completion = "Hallo, {name}. Ich bin Bischof DeLavey.\n\nDa Ihr mich nach meinen Angelegenheiten hier in der Burg fragt, hat Euch zweifellos der junge Thomas erfolgreich überredet, unserem Königreich zu helfen. Er verstand es stets meisterlich, meine Bitten zu erfüllen.\n\nIch habe leider keine Zeit für lange Erklärungen, daher fasse ich mich kurz... und bitte behaltet die Angelegenheit für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[1275] = { id = 1275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erforschung der Verderbnis", description = "Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist?\n\nIch fürchte, die Blutelfen werden auf ähnliche Weise deformiert. Azeroth darf kein weiteres Volk abscheulicher Monster hervorbringen.\n\nIch möchte die Hirnstämme der Satyrn und Naga untersuchen, damit ich daraus folgern kann, welches Schicksal die Elfen erwartet. In der Blackfathom-Tiefe, an der Küste von Ashenvale, werdet Ihr sowohl Satyrn als auch Naga finden.\n\nEs ist eine lange Reise, {name}.", sourceObjective = "Gershala Nightwhisper in Auberdine möchte 8 verderbte Hirnstämme.", progress = "Wenn ich genügend Proben habe, kann meine wahre Arbeit beginnen. Mit den verderbten Hirnstämmen der Satyrn und Naga der Blackfathom-Tiefe kann ich versuchen, einen Zusammenhang zwischen den Mutationen zu finden.\n\nMit diesem Wissen verhindern wir vielleicht, dass die Blutelfen noch deformierter und böser werden.", completion = "Ihr seid weit gereist und habt zweifellos großen Gefahren getrotzt.\n\nEure Taten waren selbstlos. Es dient ganz Azeroth, wenn Ihr mir bei meinen Forschungen helft. Ich danke Euch für alles, was Ihr getan habt, {name}.\n\nWenn Ihr mich nun entschuldigen wollt, ich habe viel Arbeit ...", sourceObjectiveStatus = "unverified-source-field" }
quests[1276] = { id = 1276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ah, jetzt erinnere ich mich! Mosarn ist ein angesehener Schmied in Thunder Bluff. Ich wusste, ich habe den Namen schon einmal gehört.\n\nAls Dank belohnte mich der irdene Ring mit einem von Mosarn hergestellten Satz Rüstungen. Sehr gute Arbeit.\n\nVielleicht kann er Euch mehr über den Schild sagen, den er anfertigte.\n\nEs ist nicht viel, aber da wir aus Reethe nichts Nützliches herausbekamen, haben wir nichts anderes.", sourceObjective = "Bringt den geschwärzten Eisenschild zu Mosarn in Thunder Bluff.", progress = "Guten Tag, {class}. Kann ich Euch mit etwas behilflich sein?", completion = "Ja, Ihr habt gewiss Recht. Das ist ein Schild, den ich gemacht habe.\n\nIch fürchte aber, ich kann Euch nicht viel mehr sagen, {name}. Ich stelle so viele Schilde und Rüstungen her, ich kann unmöglich über alle Bescheid wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1281] = { id = 1281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jims Lied <ZU TRATSCH WECHSELN>" }
quests[1282] = { id = 1282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie nennen ihn den lächelnden Jim", description = "Ich kann nicht anders, der alte Jim da tut mir Leid. Er war nicht immer so. Hatte eine Zeitlang ein Gasthaus im Sumpf, wunderbares Lokal.\n\nHört zu, ich will wirklich nicht darüber sprechen. Besprecht es mit Captain Mumm, wenn es sein muss.", sourceObjective = "Sprecht mit Captain Garran Mumm in Theramore.", completion = "James Hyal ist sein richtiger Name. Er eröffnete ein Gasthaus an der Grenze des Brachlandes. Wollte eine hübsche Unterkunft für Reisende daraus machen...\n\nVielleicht war er größenwahnsinnig, aber eine Weile lief das Gasthaus recht gut. Dann verloren wir die Herrschaft über die Straßen im Sumpf und die Oger übernahmen sie.\n\nJames war zu störrisch, seinen Traum aufzugeben und in unsere sicheren Mauern zu kommen, und das Gasthaus Zur süßen Ruh wurde bis auf die Grundmauern niedergebrannt. Wir ermitteln, hatten aber noch kein Glück. Wenn Ihr mir helfen wollt, seht zu, was Ihr in dem Geröll findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1283] = { id = 1283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer im Gasthaus Zur süßen Ruh <ZU TRATSCH WECHSELN>" }
quests[1284] = { id = 1284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdächtige Hufabdrücke", description = "Reihen von Hufspuren führen von den noch rauchenden Überresten des Gasthauses Zur süßen Ruh weg. Wenigstens einige Abdrücke sind klar erkennbar, weitere Reihen sind im weichen Schlamm des Sumpfs kaum zu sehen.", sourceObjective = "Berichtet Captain Garran Mumm in Theramore von den verdächtigen Abdrücken beim Gasthaus Zur süßen Ruh.", completion = "Hufabdrücke, hm? Stimmt es, dass es in den Ländern nahe den Marschen von Dustwallow eine außergewöhnlich hohe Zentaurenaktivität gibt? Bei den kurzen Ausflügen ins Brachland fanden wir ihre Lager und Anlagen im gesamten Areal.\n\nIch schicke Falgran Hastil, einen unserer Fährtenleser, damit er feststellt, wohin die Abdrücke führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1285] = { id = 1285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daelins Männer", description = "Reddon... Redpath... Oh, da haben wir ihn! Lieutenant Paval Reethe.\n\nTrat den Wachen von Theramore zusammen mit den meisten Rekruten bei, die mit Lady Proudmoore über das Meer kamen. Meldete sich mit sechzehn Jahren zu den Marines in Kul Tiras. Herausragende Dienste, Beförderungen...\n\nIst als vermisst eingetragen.", sourceObjective = "Kehrt mit den Informationen über Reethe zu Captain Garran Mumm in Theramore zurück.", completion = "Vermisst? Das wäre Tesorans barmherzige Umschreibung für einen Verräter.\n\nZweifellos ist er einer der Narren, die so treu zu Admiral Daelin standen, dass er zum Verräter wurde. Ist das nicht eine köstliche Ironie? Die Deserteure beschuldigen uns, dass wir die Allianz verraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1286] = { id = 1286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Deserteure", description = "Es war ein ständiger Kampf, in den Marschen präsent zu bleiben, aber durch die Kraft unserer Entschlossenheit konnten wir mehrere Wachtürme in diesem Gebiet zur Verteidigung halten.\n\nDie aktuellsten Informationen und Späherberichte, die ich bekam, deuten darauf hin, dass eine Gruppe Deserteure sich in unserem alten Turm bei der verlassenen Wacht, südöstlich des Gasthauses, eingenistet hat.\n\nAnführer der Deserteure ist ein Mann namens Jacken. Seht zu, ob Ihr Informationen über ihn bekommt.\n\nSeid gewarnt, {name}. Er könnte sich als harte Nuss erweisen.", sourceObjective = "Sammelt Informationen über Reethe von Balos Jacken und den Deserteuren in den Marschen von Dustwallow.", completion = "Hat Mumm Euch geschickt? Konnte seine Drecksarbeit nicht selbst erledigen, was...", sourceObjectiveStatus = "unverified-source-field" }
quests[1287] = { id = 1287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Deserteure", description = "Reethe? Dieser Feigling?\n\nWir warfen ihn aus dem Lager hinaus, weil er dauernd die Vorräte der Oger in Brackenwall plündern wollte. So viele sind wir nicht, dass wir es mit diesen hirnlosen Schlägern aufnehmen könnten.\n\nEr hat das Fass zum Überlaufen gebracht, daher haben wir ihn sich selbst überlassen.\n\nAlso ich hab Euch geholfen ... Warum helft Ihr jetzt nicht uns und vergesst, dass Ihr uns gefunden habt?", sourceObjective = "Sprecht mit Captain Garran Mumm in Theramore über Reethe.", completion = "Ich schicke Lieutenant Caldwell, damit er sich um die Deserteure bei der verlassenen Wacht kümmert. Darüber hinaus befehle ich ihm Reethe zu suchen. Der Sumpf ist nicht so groß und ungangbar, dass er ihn nicht finden könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[1288] = { id = 1288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mumms Bericht", description = "Ihr habt gute Arbeit geleistet, {name}, die Beste, die ich je von einem Amateur sah.\n\nLady Proudmoore bat mich, sie über diese delikate Situation auf dem Laufenden zu halten, aber ich habe eine Weile nicht mit ihr gesprochen.\n\nIch wollte ihr meinen Bericht später bringen, aber es scheint mir passender, wenn Ihr mit ihr darüber sprecht. Ihr könnt ihre Fragen wahrscheinlich besser beantworten als ich.", sourceObjective = "Bringt Mumms Bericht zu Lady Jaina Proudmoore in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[1301] = { id = 1301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "James Hyal", description = "Bevor ich hier im Blauen Eremiten arbeitete, wurde ich von einem der besten Küchenchefs und Gastwirte ausgebildet, die ich kenne. Sein Name war James Hyal. Alles, was ich besitze und im Leben erreicht habe, verdanke ich ihm.\n\nIch frage mich, was er wohl so treibt... Sein Bruder Vincent und er wollten in einer Taverne im Hafen von Menethil arbeiten, aber ich habe lange nichts von ihm gehört.\n\nWenn Ihr jemals in diese Gegend kommen solltet, könntet Ihr ihm dann Grüße von mir bestellen?", sourceObjective = "Sprecht mit Vincent Hyal im Hafen von Menethil.", completion = "James? Oh, der ist schon vor einer Weile fort.\n\nIch schätze, er hat seine patriotische Ader entdeckt. Ist auch nicht so schwer zu verstehen. Bei dem ganzen Wahnsinn in Lordaeron folgten viele Leute Jaina Proudmoore, als sie über das Meer kam.", sourceObjectiveStatus = "unverified-source-field" }
quests[1302] = { id = 1302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "James Hyal", description = "Mein Bruder James fuhr mit Lady Proudmoore über das Meer. Als Letztes hörte ich, dass die Kämpfe dort drüben beigelegt waren und James irgendwo auf dem Kontinent ein Gasthaus eröffnete. Wo immer er sein mag, ich bin sicher, seine Geschäfte blühen. Er war ein verdammt guter Koch.\n\nAber ich habe eine Weile nichts mehr von ihm gehört - zu sehr mit seinem Gasthaus beschäftigt, denke ich. Der Amtmann in Theramore könnte Euch vielleicht zu ihm führen.", sourceObjective = "Sprecht mit Amtmann Lendry in Theramore.", completion = "James Hyal, James Hyal... Warum kommt mir der Name so bekannt vor?\n\nNatürlich! Der Vorfall im Gasthaus Zur süßen Ruh. Wenn Ihr Informationen habt, was dort geschehen ist, beschwöre ich Euch, mit Captain Mumm darüber zu sprechen. Er leitet die Ermittlungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1318] = { id = 1318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die offene Rechnung der Gordok", description = "Nun Ihr de' König sein, vielleicht Ihr kriegen zurück wertvolles Artefakt der Gordok von gruseligen Elf, der sich selbst nennen Prinz! König vor Euch hat versagt, so wie alle Könige seit Tortheldrin - de' gruselige Elf - es gestohlen hat, von damaligen Gordokkönig!\n\nArtefakt heißen Stulpen der Gordokmacht. Alte Zeit Geschichten sagen, nur wahre König de' Gordok kann sie zurückholen. Alte Zeit Geschichten sagen auch, der gruselige Elf ist immer noch hier - Ihr finden es und es werden Eure mächtigen Stulpen, für immer! Yar, ich zeigen!", sourceObjective = "Findet die Stulpen der Gordokmacht und bringt sie zu Captain Kromcrush in Düsterbruch.\n\nKromcrush zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[1319] = { id = 1319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ich kann Euch leider nicht weiterhelfen, {name}, schicke Euch aber zu jemandem, der es kann. Caz Twosprocket, einer unserer besten Schmiede, arbeitet in der Schmiede.\n\nBringt ihm den Schild und hört Euch an, was er zu sagen hat.", sourceObjective = "Zeigt den geschwärzten Eisenschild Caz Twosprocket in Theramore.", progress = "Etwas, das ich mir ansehen soll?", completion = "Hm... interessantes Stück Eisen habt Ihr da. Definitiv nicht von einem der Schmiede, die ich diesseits des Meeres kenne, und gewiss nicht mein Werk.", sourceObjectiveStatus = "unverified-source-field" }
quests[1320] = { id = 1320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ah, das hätte ich fast übersehen... Der Ledergurt an der Rückseite muss verbrannt sein, aber er war offenbar für eine große Person gemacht. Ich schätze, für einen Tauren.\n\nMehr kann ich Euch nicht sagen. Sagt Captain Mumm, es tut mir Leid, dass ich nicht mehr helfen konnte.", sourceObjective = "Sprecht mit Captain Garran Mumm in Theramore.", completion = "Das sind keine sehr ergiebigen Informationen, aber wir müssen sie berücksichtigen. Hoffentlich fügen sich noch ein paar Teile dieses Puzzles zusammen und ergeben ein hoffnungsvolleres Bild der Geschehnisse.", sourceObjectiveStatus = "unverified-source-field" }
quests[1321] = { id = 1321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Hmm... Ich sehe nichts Ungewöhnliches an diesem Schild. Do'gol, der Schmied, sollte ihn sich ansehen. Vielleicht kann er uns mehr sagen, aber große Hoffnungen würde ich mir nicht machen...", sourceObjective = "Zeigt den geschwärzten Eisenschild Do'gol in Brackenwall.", progress = "Etwas für mich, {class}?", completion = "Das ist ein guter Schild. Sehr stark, schwer, gut. Aber Do'gol braucht ihn nicht. Ich mache Schilde, ich kaufe sie nicht, {name}.\n\nDas solltet Ihr wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1322] = { id = 1322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Hmmm, hier am Rand des Schildes steht etwas geschrieben, aber durch die Brandspuren kann man es kaum lesen.\n\nIch brauche Säure, um ihn zu reinigen. Das Gift der Dunkelzahnspinnen im Sumpf würde helfen. Bringt mir ihre Giftsäcke und ich reinige diesen Schild.", sourceObjective = "Bringt 6 säurehaltige Giftbeutel zu Do'gol in Brackenwall.", progress = "Habt Ihr die Beutel der Spinnen bekommen?", completion = "Ich mag keine Spinnen, die so groß sind, dass ich mich nicht darauf setzen und sie zerquetschen kann.\n\nDanke, dass Ihr sie geholt habt, {name}. Jetzt reiße ich sie auf und gieße den Inhalt auf den Schild...", sourceObjectiveStatus = "unverified-source-field" }
quests[1323] = { id = 1323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Oh, ich glaube, ich habe zu viel Säure auf den Schild geschüttet. Lasst mich ein wenig rubbeln...\n\nHm, schwer zu lesen, sieht aber wie der Name Mosarn aus. Nie von ihm gehört. Vielleicht weiß Krog etwas. Krog kennt viele Leute.", sourceObjective = "Sprecht mit Krog in Brackenwall.", completion = "Mosarn? Kommt mir bekannt vor... Ich komm nicht drauf. Vielleicht fällt es mir später wieder ein.\n\nWahrscheinlich ist es nicht wichtig. Ein Schild kann von überall stammen und keine Bedeutung haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[1324] = { id = 1324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Was?! Ihr kommt hierher und werft mir vor, ich mache mit den Defias gemeinsame Sache und glaubt, ich höre mir diese Beleidigungen an? Etwas sagt mir, dass Ihr das schon lange verdient habt.", sourceObjective = "Besiegt den Gefreiten Hendel in den Marschen von Dustwallow.", completion = "Ich versichere Euch, wir sind alle außer uns wegen der jüngsten Ereignisse, aber lasst ihn uns zum Verhör nach Theramore bringen, dann sehen wir, ob wir den König finden.\n\nIch bin sicher, Milady Proudmoore möchte Euch für Eure Hilfe danken. Sprecht mit Ihr, wenn Ihr einen Moment Zeit habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1338] = { id = 1338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormpikes Bestellung", description = "Es gibt einen Rüstungsschmied bei den Zwergen, dessen Arbeit ich sehr bewundere. Sein Name ist Furen Longbeard und seine Fertigkeit unübertroffen. Ich brauche einen neuen Schild und muss einen von ihm haben!\n\nDas Problem ist... Furen lebt weit im Süden im Zwergendistrikt von Stormwind. Im Menschenland! Ich kann mir nicht vorstellen, warum er dort lebt, so weit weg von Ironforge. Die Menschen müssen ihn fürstlich bezahlen, damit er dort bleibt!\n\nWenn Ihr reisen wollt und nichts gegen das Geldverdienen habt, würdet Ihr Furen dann meine Bitte nach einem Schild überbringen?", sourceObjective = "Bringt Stormpikes Bitte zu Furen Longbeard in Stormwind.", progress = "Ein Brief aus dem Zwergenland? Ich frage mich, wer von so weit aus dem Norden kommen mag...\n\nBitte lasst mich die Bestellung sehen.", completion = "Ah, eine Bitte von einem der Stormpikes. Das ist ein stolzer Klan erstklassiger Zwerge. Und reich sind sie auch.\n\nDanke, {name}. Ich werde noch heute Abend mit der Arbeit am Schild von Gebirgsjäger Stormpike beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1339] = { id = 1339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebirgsjäger Stormpikes Aufgabe", description = "Ich hörte, Gebirgsjäger Stormpike sucht nach einem Läufer. Jemand, der eine Reise für ihn unternimmt. Wie wäre es? Seid Ihr ein {race}, der für den Job geeignet ist?\n\nWenn ja, findet Ihr Stormpike auf der Spitze des nördlichen Wachturms.", sourceObjective = "Sprecht mit Gebirgsjäger Stormpike.", completion = "Ganz recht. Ich habe eine Aufgabe, die ich auf Wache nicht erledigen kann. Sie wird Euch weit vom Loch Modan wegführen.\n\nDie perfekte Chance auf ein Abenteuer!", sourceObjectiveStatus = "unverified-source-field" }
quests[1358] = { id = 1358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probe für Helbrim", description = "Ein Kollege in Kalimdor, Apotheker Helbrim, untersucht die Auswirkungen von Lordaerons Toxinen auf die Wildtiere von Kalimdor. Er wäre an einer Probe der Wolfherzen interessiert, die Renferrel mir geschickt hat.\n\nHelbrim lebt im Brachland in einem Dorf, das Crossroads heißt. Um ihn zu erreichen, müsst Ihr per Zeppelin zur Orc-Hauptstadt Orgrimmar reisen und dann zu Fuß Richtung Süden nach Durotar. Geht durch das Brachland nach Westen und Ihr erreicht bald den Ort Crossroads.", sourceObjective = "Bringt die Wolfherzprobe zu Apotheker Helbrim ins Brachland.", progress = "Habt ihr ein Päckchen für mich?", completion = "Ah, sehr gut. Wenn die ersten Berichte wahr sind, kann die Giftigkeit dieser Herzen uns weiteren Fortschritt im Wissen über Gifte bringen.\n\nDas ist eine willkommene Lieferung, {name}. Ihr habt Eure Belohnung wohl verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[1359] = { id = 1359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinges Lieferung", description = "Die Wolfherzen, die Ihr beschafft habt, verfügen über ein Merkmal, das es in ähnlichen Proben nicht gibt. Sie verfügen über eine Giftigkeit, die für genau die Wölfe tödlich sein müsste, in denen die Herzen schlagen!\n\nEs ist unglaublich und wir müssen das weiter untersuchen. Ich habe einige Proben der gewonnenen Herzen aufbewahrt. Bringt sie zu meiner Kollegin, Apothekerin Zinge. Ihr findet sie in unserem Hauptquartier in Undercity.", sourceObjective = "Bringt die Wolfherzproben zu Apothekerin Zinge nach Undercity.", progress = "Habt Ihr etwas für mich?", completion = "Ah ja, die Herzproben, von denen Renferrel sprach. Ich bin ganz erpicht darauf, mit ihnen Experimente durchzuführen... für die Königliche Apothekervereinigung ist es immer von Interesse, wenn neue Toxinformen entdeckt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[1360] = { id = 1360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbeschaffte Schätze", description = "Ich hatte selbst eine gute Arbeitsstelle als Buddler an der Uldaman-Ausgrabungsstätte im Ödland... das heißt, bis diese verfluchten Troggs auftauchten. Ich konnte gerade noch mit heiler Haut entkommen, das war alles. In dem Chaos habe ich meinen wertvollsten Besitz zurückgelassen. Natürlich ist er in meiner Truhe sicher vor den Troggs, aber die befindet sich mitten unter ihnen.\n\nIch wäre in Eurer Schuld, sowohl in Ehre als auch in Münze, wenn Ihr sie für mich besorgen könntet! Eine Truhe mit meinem Namen darauf befindet sich am Ende der nördlichen Bankenhalle. Dorthin müsst Ihr gelangen.", sourceObjective = "Holt Krom Stoutarms wertvollen Besitz aus seiner Truhe in der nördlichen Bankenhalle von Uldaman und bringt den Schatz zu ihm nach Ironforge.", progress = "Na, konntet Ihr die Troggs lange genug in Schach halten, um zu meiner Truhe zu gelangen und Euch meinen Schatz zu schnappen?", completion = "Ah, ich fühle mich wieder komplett - ich danke Euch sehr.\n\nManche Zwerge schätzen den Glanz von Metall und andere schätzen den Glanz von Edelsteinen... aber ein Stoutarm ohne einen liebevoll gehüteten Bierkrug ist kein Stoutarm!", sourceObjectiveStatus = "unverified-source-field" }
quests[1361] = { id = 1361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regthar Deathgate", description = "Ein Krieger der Horde, Regthar Deathgate, rekrutiert Agenten für einen Einsatz im Land Desolace. Sprecht mit ihm, wenn Ihr Euch freiwillig melden wollt. Er lebt im Brachland in einer Reihe von Bunkern westlich von Crossroads.\n\nUnd schärft Eure Waffen. Desolace ist ein vom Krieg zerrissener Ort.", sourceObjective = "Sprecht mit Regthar Deathgate.", completion = "Ja, ich rekrutiere. Die Mission führt nach Desolace und geht gegen die Zentauren dort. Ich fasse mich kurz, damit Ihr rasch beginnen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1362] = { id = 1362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kolkar von Desolace", description = "Die Kolkarzentauren leben in Desolace. Ihre Truppen sind in das Brachland vorgestoßen. Das ist bekannt. Agenten der Horde kümmern sich dort um sie.\n\nAber so lange die Zentauren in Desolace so stark sind, werden sie immer eine Bedrohung sein. Mit der Zeit schaffen wir uns diese Bedrohung vom Hals.\n\nSprecht mit Felgur Twocuts beim Geistwandlerposten in Desolace. Seine Aufgabe war es, Informationen über die Zentauren zu sammeln. Er weiß bestimmt, wie man am besten mit den Kolkar von Desolace fertig wird.", sourceObjective = "Sprecht mit Felgur Twocuts beim Geistwandlerposten in Desolace.", completion = "Seid Ihr auf Befehl von Regthar hier? Dann seid Ihr hier, um es den Zentauren zu zeigen. Gut.\n\nIch hoffe, Ihr seid erholt. Ich weiß nicht, wie unsere Kampagne gegen die Zentauren enden wird, aber ich weiß, es wird ein langer Kampf sein.\n\nNehmt Platz und hört zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[1363] = { id = 1363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazens Befehl", description = "Als Verwalter der Arbeit hier in der Bibliothek der Akademie der Arkanen Künste und Wissenschaften liegt es in meiner Verantwortung, dafür zu sorgen, dass alle magischen Folianten und Rollen stets erfasst sind. Wer weiß, was Schlimmes geschehen würde, fielen einige dieser verzauberten Texte in die falschen Hände?\n\nDabei fällt mir ein ... mein Assistent Dellis machte letzte Woche einen schrecklichen Fehler. In der Bibliothek ist er recht tüchtig, aber inkompetent, wenn er die Tore von Stormwind hinter sich lässt. Seid ein Held und helft dem alten Dellis, ja?", sourceObjective = "Sprecht mit Akolyth Dellis in Stormwind.", completion = "Es war nicht meine Schuld. Wirklich nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1364] = { id = 1364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazens Befehl", description = "Meister Mazens Anweisungen waren ganz klar: Bringt einen sehr wichtigen Essay zu Behüter Mahar Ba in der Burg Nethergarde.\n\nAber ich bin noch nie in den verwüsteten Landen gewesen. Die Reise war beängstigend!\n\nAls ich an die Sümpfe des Elends kam, bog ich falsch ab und war plötzlich von grässlichen pflanzenartigen Sumpfwesen umzingelt. Sie schienen mich angreifen zu wollen, also lief ich weg. Doch in meiner Hast ließ ich den Essay fallen. Ich bin sicher, eine der Bestien hat ihn genommen.\n\nKönntet Ihr bitte versuchen, ihn zu holen und zu Mahar Ba zu bringen?", sourceObjective = "Rettet Khadgars 'Abhandlungen über dimensionale Konvergenz' und bringt sie zu Behüter Mahar Ba in der Burg Nethergarde.", progress = "Was führt Euch in die Burg Nethergarde, {race}?", completion = "Ah, grandios!\n\nIch fürchtete schon geraume Zeit, Meister Mazen in der Akademie der Arkanen Künste und Wissenschaften könnte meine Anfrage nach Khadgars 'Abhandlungen über dimensionale Konvergenz' übersehen haben.\n\nAngesichts der vielen seltsamen Vorkommnisse wird er bestimmt mit Anfragen überschwemmt.\n\nWenn Ihr mich jetzt entschuldigen würdet, ich muss sofort mit meinen Forschungen beginnen. Endlich Einblick in ein Genie wie Khadgar zu bekommen, erfüllt mich mit freudiger Erregung.", sourceObjectiveStatus = "unverified-source-field" }
quests[1365] = { id = 1365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Dez'hepah", description = "Die Kolkar sind nicht die einzigen Zentauren von Desolace. Viele Klans ziehen durch diese trockenen Ebenen, bekämpfen einander und sterben. Und es ist gut, dass sie sich untereinander bekämpfen, denn sie sind stark und brutal. Vereinten sich die Zentauren gegen uns, wären sie ein schrecklicher Gegner.\n\nWir müssen sie erledigen, bevor sie sich zusammentun.\n\nEuer erster Schritt ist, den Kolkarklan zu schwächen. Macht das, indem Ihr den Anführer Khan Dez'hepah besiegt.\n\nDas Dorf Kolkar liegt nordöstlich von hier. Geht, und möge Euch das Glück hold sein.", sourceObjective = "Bringt Khan Dez'hepahs Kopf zu Felgur Twocuts in Desolace.", progress = "{name}, habt Ihr Khan Dez'hepah besiegt?", completion = "Gut gemacht. Das rasche Vorgehen gegen die Kolkar zeugt von Kraft, und Kraft verstehen die Zentauren am besten.\n\nDer Tod des Anführers der Kolkar wird diesen Klan nicht schwächen, aber den anderen eine Pause gewähren.", sourceObjectiveStatus = "unverified-source-field" }
quests[1366] = { id = 1366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zentaurenkopfgeld", description = "Da Ihr die Zentaurenklans jetzt eingeschüchtert habt, wird es Zeit, sie bluten zu lassen. Wenn Ihr durch Desolace reist, jagt Zentauren. Mir ist gleich, welchen Klan Ihr jagt. Sammelt nur Ohren. Bergeweise Ohren.\n\nWenn Ihr ihre Zahl dezimiert, schwächt Ihr ihre Entschlossenheit und macht alle Gedanken an Expansion zunichte.\n\nGute Jagd, {name}.", sourceObjective = "Bringt 15 Zentaurenohren zu Felgur Twocuts in Desolace.", progress = "Wie ist Eure Ohrensammlung, {name}? Groß?", completion = "Inzwischen müssen die Zentauren Euren Namen kennen. Ich bin sicher, sie kennen ihn und respektieren und fürchten ihn. Und genau wie Euch kennen sie das Banner, unter dem Ihr reitet.\n\nDas Banner der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[1367] = { id = 1367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianz mit den Magram", description = "Um die Zentauren zu schlagen, müssen wir ihren Hass gegen sie wenden. Wir verbünden uns mit einem Klan und lernen durch ihn, wie wir alle Klans besiegen können.\n\nWenn Ihr Euch mit den Magram verbünden wollt, dann tötet ihre Gegner, die Gelkis. Das wird Euch den Respekt der Magram einbringen. Wenn Ihr genug verdient habt, dann trefft Euch mit dem Sprecher der Magram Warug am Rand des Dorfes Magram im Südosten von Desolace.", sourceObjective = "Baut Euch einen freundlichen Ruf bei den Magram auf und sprecht dann mit Warug.", completion = "Die Gelkis weinen, wenn sie Euren Namen hören, {name}. Sie fürchten und hassen Euch. Sie hassen Euch so sehr wie die Magram!\n\nVielleicht seid Ihr so stark wie die Magram. Wir werden sehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[1368] = { id = 1368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianz mit den Gelkis", description = "Um die Zentauren zu schlagen, müssen wir ihren Hass gegen sie wenden. Wir verbünden uns mit einem Klan und lernen durch ihn, wie wir alle Klans besiegen können.\n\nWenn Ihr Euch mit den Gelkis verbünden wollt, dann tötet ihre Gegner, die Magram. Wenn Ihr Euch den Respekt der Gelkis verdient habt, dann trefft Euch mit der Schamanin der Gelkis Uthek der Weisen am Rand des Dorfes Gelkis im Südwesten von Desolace.", sourceObjective = "Baut Euch einen Ruf als freundliche Person bei den Gelkis auf und sprecht dann mit Uthek der Weisen.", completion = "Die Erde spricht zu mir. Und sie sagt, Ihr habt viele Magram getötet. Das ist gut.\n\nWenn Ihr ein Freund der Gelkis seid, dann hört zu. Ich habe weitere Aufgaben für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[1369] = { id = 1369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrochene Tränen", description = "Die Gelkis glauben, dass unsere Zentaurenmutter Theradras uns beschützt. Sie sind dumm. Niemand beschützt die Zentauren. Die Magram brauchen keinen Schutz! Wir sind die Stärksten!\n\nZeigt den Gelkis, dass sie dumm sind. Geht zu der Höhle in ihrem Dorf. Sie horten Kristalle in dieser Höhle, die Tränen von Theradras. Zerstört die Tränen und bringt mir die zerbrochenen Stücke!", sourceObjective = "Wahrt Euren Ruf bei den Magram und bringt 3 zerbrochene Tränen zu Warug im Dorf Magram.", progress = "Wenn Ihr nicht unser Feind seid, dann tut Ihr, was ich verlange!", completion = "Ihr habt die Tränen! Jetzt wissen die Gelkis, dass Theradras ihnen nicht helfen wird. Sie wird nicht weinen, wenn wir sie zerschmettern! Die Magram werden herrschen!\n\nEs war klug, uns zu helfen, {name}. Wir sind die Stärksten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1370] = { id = 1370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebstahl von Vorräten", description = "Wenn wir nicht im Krieg sind, jagen wir wegen Fleisch. Fleisch gibt uns Kraft und volle Bäuche kämpfen besser als leere.\n\nSo ist es bei den Magram. Sie lagern extra Fleisch ein, damit sie zwischen den Jagdausflügen länger kämpfen können. Wenn man ihr Dorf im Osten überfällt und ihre Fleischvorräte raubt, wird ihre Kraft schwinden.", sourceObjective = "Bringt 6 Taschen primitiv getrocknetes Fleisch zu Uthek der Weisen im Dorf Gelkis.", progress = "Kommt wieder, wenn Ihr Euch der Gelkis abermals als würdig erwiesen habt!", completion = "Gut. Ich kann das laute Magenknurren der Magram aus ihrem weit entfernten Dorf hören!\n\nIch gebe dieses Fleisch den Gelkis. Und wir werden viele Tage ohne Unterbrechung kämpfen können.\n\nWas Ihr getan habt, war gut für die Gelkis, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1371] = { id = 1371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gizmo für Warug", description = "Vor langer Zeit kam ein kleiner Gnom nach Desolace. Er hatte Pferde und einen Karren, und auf dem Karren viele seltsame Dinge. Komische Dinge. Dinge, die in verschiedenen Farben brannten. Dinge, die sich bewegten und doch nicht lebten. Ich tötete den kleinen Gnom, aber vorher ... brachte er mich zum Lachen.\n\nIch behielt mein liebstes Ding von dem Wagen. Es war ein Mensch aus Holz, der mir zuwinkte, bis ich ihn schlug und zerbrach.\n\nIch will einen Neuen. Besorgt mir einen Neuen!", sourceObjective = "Wahrt Euren Ruf bei den Magram und bringt eine hochentwickelte Zielattrappe zu Warug im Dorf Magram in Desolace.", progress = "Wenn Ihr nicht unser Feind seid, dann tut Ihr, was ich verlange!", completion = "Ja, genau so etwas hatte ich! Ich bringe sie wieder dazu, sich zu bewegen. Das bringt mich zum Lachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1372] = { id = 1372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts als die Wahrheit", description = "Auf Befehl von Varimathras wurde unsere Expeditionsstreitmacht ausgeschickt, um das untere Azeroth zu vermessen.\n\nBeim Spähen bemerkte ich einen Spitzel der Menschen, der den Bettlerschlupfwinkel ausspionierte. Ehe ich ihn festnehmen konnte, schnappten ihn einige unserer ... Orcbrüder ... und brachten ihn nach Stonard, ihrer Festung in den Sümpfen des Elends.\n\nIch möchte unseren Orcverbündeten ... helfen. Sie sahen unser Lager hier nicht, dennoch wollte ich sie unterstützen.\n\nIch arbeitete hier mit Faustin, um ein ... Wahrheitsserum für unseren Freund in Stonard zu entwickeln.", sourceObjective = "Sprecht mit Apotheker Faustin im Bettlerschlupfwinkel.", completion = "Zraedus erzählte mir gerade von dem neugierigen kleinen Spitzel, ehe Ihr gekommen seid.\n\nWirklich ein Problem. Ein Naseweis, der im Bettlerschlupfwinkel herumschnüffelt, hat uns gerade noch gefehlt.\n\nIch bin sicher, die Orcs in Stonard können es kaum erwarten, zu hören, was unser Freund zu sagen hat. Da sie unsere, ähem, Verbündeten sind, müssen wir ihnen helfen, von dem Menschen alle Informationen zu bekommen.\n\nArbeitet mit mir, {name}, und wir bringen ein Wahrheitsserum nach Stonard.\n\nFür die Horde!\n\n... war das richtig?", sourceObjectiveStatus = "unverified-source-field" }
quests[1373] = { id = 1373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ongeku", description = "Ihr müsst noch mehr beweisen und Eure nächste Aufgabe führt Euch weit weg, daher werden die Gelkis die Magram vorerst ohne Euch bekämpfen.\n\nDie Erde flüstert jenen, die zuhören, viele Geheimnisse zu. Ein Geheimnis, von dem ich höre, betrifft einen roten Kristall. Er heißt Draenethyst und ist neu auf unserer Erde. Er stammt von einem Ort, wo Berge fliegen und Dämonen herrschen.\n\nBringt mir einen Splitter Draenethyst; er macht meine Magie stark! Der Splitter befindet sich an einem Ort namens Sümpfe des Elends und ist im Besitz von Ongeku, dem Verirrten.", sourceObjective = "Wahrt Euren Ruf bei den Gelkis und bringt einen Draenethystsplitter zu Uthek der Weisen im Dorf Gelkis in Desolace.", progress = "Zeigt mir, dass Ihr ein Freund der Gelkis seid, {name}.", completion = "Ja, das ist der Splitter, von dem die Erde flüsterte. Ich spüre starke Magie darin! Ich werde diese Magie gegen die Feinde der Gelkis einsetzen.\n\nIhr habt eine weitere Aufgabe für uns erledigt, {name}. Vielleicht werden wir Euch bald Freund nennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1374] = { id = 1374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Jehn", description = "Die Erde spricht zu mir und sagt, dass die Magram schwach werden. Jetzt ist es Zeit, ihren Khan zu töten!\n\nBringt mir den Kopf des Magramkahns Jehn!", sourceObjective = "Bringt Khan Jehns Kopf zu Uthek der Weisen im Dorf Gelkis in Desolace.", progress = "Zeigt mir, dass Ihr ein Freund der Gelkis seid, {name}.", completion = "Khan Jehn war stark, aber dumm. Er dachte, seine Kraft wäre groß. Er sah nicht, dass Erdmagie stärker ist. Ohne Anführer werden die Zentauren der Magram fallen und die Gelkis eines Tages herrschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1375] = { id = 1375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Shaka", description = "Ihr helft den Magram und ich mag Euch. Tötet jetzt den Khan der Gelkis! Er ist Khan Shaka und ich will seinen Kopf! Ich möchte seinen Kopf ansehen und ihn auslachen!", sourceObjective = "Wahrt Euren Ruf bei den Magram und bringt den Kopf von Khan Shaka zu Warug im Dorf Magram in Desolace.", progress = "Erledigt diese Aufgabe für die Magram und ich helfe Euch.", completion = "Khan Shaka ist tot! Ich stecke seinen Kopf auf eine Lanze und nehme ihn mit, damit Shaka die Kraft der Magram sehen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[1380] = { id = 1380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Hratha", description = "{name}, Ihr habt uns gegen die Magram geholfen. Jetzt helft uns dabei, die Maraudine zu schlagen! Tötet den Anführer ihres Klans, Khan Hratha!\n\nUm ihn herauszufordern, blast das Kriegshorn der Maraudine. Es befindet sich auf einem hohen Steilhang im Tal der Speere.\n\nDoch um das Horn zu blasen, müsst Ihr erst ein Kriegshornmundstück erwerben. Diese Teile sind selten und sind ausschließlich im Besitz der vertrauenswürdigsten Maraudinezentauren.\n\nNachdem das Horn geblasen wurde, werden Zentauren kommen. Tötet sie, bis Hratha auftaucht.\n\nKhan Hratha besitzt ein Stück eines... Schlüssels. Bringt es mir...", sourceObjective = "Wahrt Euren Ruf bei den Gelkis und bringt das Schlüsselfragment der Maraudine zu Uthek der Weisen im Dorf Gelkis.", progress = "Ist Khan Hratha tot? Habt Ihr das Schlüsselfragment?", completion = "Er ist tot! Khan Hratha ist tot! Und jetzt werden die Maraudine untergehen! Wenn die Gelkis dieses Land regieren, {name}, werden wir uns Euer erinnern. Und die Geister der Erde werden für alle Zeiten Euren Namen singen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1381] = { id = 1381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Hratha", description = "Der Khan der Gelkis ist tot, und jetzt werden die Maraudine fallen! Tötet Hratha, den Khan der Maraudine!\n\nUm ihn herauszufordern, blast das Horn auf dem hohen Steilhang im Tal der Speere. Doch um das Horn zu blasen, braucht Ihr erst ein Kriegshornmundstück. Um ein Mundstück zu erwerben, müsst Ihr Zentauren der Maraudine töten. Tötet sie so lange, bis Ihr ein Mundstück findet. Dann blast das Horn.\n\nTut dies, und Zentauren der Maraudine werden zum Turm kommen. Tötet sie, bis Khan Hratha auftaucht. Khan Hratha besitzt ein Stück eines Schlüssels. Gebt mir dieses Stück...", sourceObjective = "Wahrt Euren Ruf bei den Magram und bringt das Schlüsselfragment der Maraudine zu Warug im Dorf Magram in Desolace.", progress = "Tut, was ich verlange. Beweist mir, dass Ihr ein Verbündeter der Magram seid!", completion = "Khan Hratha ist tot! Jetzt sind die Magram die stärksten aller Zentauren! Wir werden die anderen zerschmettern und Desolace beherrschen!\n\nWir werden uns Euer erinnern, {name}, und unsere Hufen werden Euch verschonen, wenn alle anderen zertrampelt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[1382] = { id = 1382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsame Allianz", description = "Wir können von Glück reden, dass die Zentauren sich untereinander bekämpfen, denn als vereinigte Kraft könnte sie nichts aufhalten. Ja, das kommt uns zu Gute und wir sollten unseren Vorteil ausbauen.\n\nEiner der Zentaurenklans, der Gelkisklan, führt einen brutalen Krieg gegen den Magramklan. Wenn wir die Magram angreifen, können wir vielleicht eine Allianz mit den Gelkis schmieden.\n\nSprecht mit Uthek der Weisen im Randbezirk der Gelkislager im Südwesten von Desolace. Durch sie könnten wir eine Allianz mit den Gelkis schmieden.", sourceObjective = "Baut eine freundliche Beziehung zu den Gelkis auf und sprecht dann mit Uthek der Weisen.", completion = "Unter den Gelkis raunt man erführchtig Euren Namen. Ihr habt viel Blut der Magram an den Händen. Das ist gut.\n\nVielleicht ist es auch gut, wenn wir reden. Erzählt, was Ihr für die Gelkis tun könnt und was wir für Euch tun können..", sourceObjectiveStatus = "unverified-source-field" }
quests[1383] = { id = 1383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts als die Wahrheit", description = "Mir schwebt genau das richtige Serum vor. Es wird die Wahrheit genau so behandeln, wie die Wahrheit behandelt werden sollte.\n\nFür dieses Gebräu brauche ich mehrere Schattenpantherherzen aus dem Sumpf. Außerdem brauche ich den verzauberten Fungus des Morastlords, der dort haust. Ich bin sicher, jemand, der so tüchtig ist wie Ihr, {name}, kann ihn überreden, sich von einigen zu trennen.\n\nDie schwierigste Aufgabe wird sein, einen Tiefschreitertumor aus dem fernen Desolace zu beschaffen. Nur sehr selten werden die Riesen dort krank, sodass ein Tumor entsteht.\n\nUnd jetzt fort mit Euch!", sourceObjective = "Apotheker Faustin im Bettlerschlupfwinkel braucht 5 Schattenpantherherzen, Morastlordfungus und einen Tiefschreitertumor.", progress = "Dieser Spitzel in Stonard wird bestimmt ganz... offen... wenn er mein Spezialserum getrunken hat. Ha-ha!\n\nDie erforderlichen Zutaten sind nicht leicht zu beschaffen. Schattenpanther kommen im Sumpf häufig vor, aber genug Herzen für unsere Zwecke zu beschaffen, kann schwierig sein. Und der Morastlord kann so eine heikle Bestie sein.\n\nWas den Tiefschreitertumor angeht, die sind schrecklich schwer zu finden. Aber die chemische Reaktion, die ich damit auslösen kann, ist unübertroffen.", completion = "Großartig, {name}! Und gerade rechtzeitig. Wie Zraedus mir sagte, hat der Spitzel sich von seinen Verletzungen erholt und kann von den Orcs verhört werden.\n\nGebt mir einen Augenblick, um das Gif..., ich meine das Wahrheitsserum vorzubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1384] = { id = 1384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfall auf die Kolkar", description = "Die Kolkarzentauren glauben, ihre Magie sei stark. Die wissen nicht, was Magie ist! Nie und nimmer würden die richtige Magie überhaupt erkennen!\n\nIhr werdet ihnen zeigen, dass ihre Magie schwach ist. Geht zu den Kolkar im Nordosten und tötet sie. Nehmt ihre Glücksbringer. Bringt mir die Glücksbringer und ich werfe sie ins Feuer und lache!", sourceObjective = "Wahrt Euren Ruf bei den Gelkis und bringt 10 kunstlose Glücksbringer zu Uthek der Weisen im Dorf Gelkis in Desolace.", progress = "Habt Ihr die Glücksbringer? Habt Ihr den Kolkar gezeigt, dass sie schwach sind?", completion = "Ihr habt etwas Gutes für die Gelkis getan. Die Kolkar sind schwach und werden sterben. Ihre Magie ist jämmerlich und wird sie nicht retten. Ihr habt ihnen das gezeigt und ihre Angst wird sie noch schwächer machen!\n\nUnd in unserem Land sterben die Schwachen schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[1385] = { id = 1385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutale Politik", description = "Desolace ist ein Land im Krieg. Die Zentauren führen Krieg untereinander und wir glauben, der Sieger wird marschieren und unsere Festungen bedrohen. Das können wir nicht dulden.\n\nWir müssen lernen, wie man die Zentauren schlägt, und dazu... müssen wir uns mit einem der Klans verbünden. Die Zentauren der Magram führen Krieg mit den Gelkis. Wenn Ihr gegen die Gelkis kämpft, dann erwägen die Magram vielleicht eine Allianz.\n\nErringt die Gunst der Magram und sprecht dann mit Warug im Dorf Magram im Südosten von Desolace.", sourceObjective = "Baut Euch einen freundlichen Ruf bei den Magram auf und sprecht dann mit Warug.", completion = "Viele Gelkis fielen Euch zum Opfer. Das gefällt mir. Vielleicht könnt Ihr noch mehr, das mir gefällt. Vielleicht könnt Ihr und die Magram Freunde sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1386] = { id = 1386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Kolkar", description = "Die Kolkar halten sich für stark, aber wir lachen über sie! Wir lachen und wir töten sie! Tötet auch Ihr sie. Zeigt mir, dass Ihr Kolkar genauso wie wir töten könnt. Geht nach Norden und tötet sie alle!", sourceObjective = "Haltet Euren Ruf bei den Magram aufrecht. Tötet 12 Zentauren der Kolkar, 12 Späher der Kolkar sowie 6 Raufer der Kolkar und kehrt dann zu Warug ins Magramdorf in Desolace zurück.", completion = "Die Kolkar fürchten Euch jetzt! Hoffentlich habt Ihr gelacht, als Ihr sie getötet habt. Es ist gut, wenn man beim Töten lacht, dann sieht der Gegner, dass er schwach ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[1387] = { id = 1387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zentaurenkopfgeld", description = "Viele Klans bilden das Volk der Zentauren. Jeder hat seinen Anführer und eine Agenda, aber alle Klans haben eines gemeinsam: Grausamkeit.\n\nWenn wir je Frieden finden wollen, müssen die Zentauren entfernt werden. Und ich übertrage Euch die Aufgabe, genau das zu tun.\n\nWenn Ihr durch Desolace zieht, jagt Zentauren und sammelt ihre Ohren. Bringt mir viele, viele Ohren.\n\nMacht das im Dienst der Allianz, {name}, und wir sind dem Ende des Krieges einen Schritt näher.", sourceObjective = "Bringt 15 Zentaurenohren zu Corporal Melkins bei der Nijelspitze in Desolace.", progress = "Habt Ihr einen Bericht, {name}?", completion = "Ah, die Ohren. Gut gemacht.\n\nEure Verdienste um die Allianz stehen außer Frage, {name}. Das Blut, das Ihr in Desolace vergossen habt, wird zweifellos zahllose Leben retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1388] = { id = 1388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts als die Wahrheit", description = "Alles läuft genau nach Plan, {name}. Ich möchte, dass Ihr dieses Wahrheitsserum dem Todespirscher Zraedus gebt. Er wird Euch zeigen, wie man es richtig... anwendet.\n\nHa-ha!", sourceObjective = "Gebt Faustins Wahrheitsserum dem Todespirscher Zraedus im Bettlerschlupfwinkel.", progress = "Ich hoffe, Ihr habt Euch unserem teuren Freund, dem Apotheker Faustin, als nützlich erwiesen.", completion = "Ich wusste, der alte Faustin würde sich was Gutes ausdenken! Ihr wart zweifellos eine enorme Hilfe.\n\nKommen wir nun zum Geschäft, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[1389] = { id = 1389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenethystkristalle", description = "Die Verirrten, die im Fallow Heiligtum leben, sehen aus wie wir, aber sie sind Monster... die üblen Unbilden auf unserem Trek nach Azeroth haben sie wahnsinnig gemacht. Einst waren sie unsere Brüder, doch nun leben sie im Fallow Heiligtum im Osten und fangen oder töten alle, die sich in die Nähe wagen.\n\nUnd sie haben uns etwas Heiliges gestohlen - Draenethystkristalle.\n\nUns fehlt die Kraft, das Fallow Heiligtum zu betreten und unseren gestohlenen Draenethyst von ihren Hütten und Lagerfeuern zu holen, aber ohne diese Kristalle... könnten auch wir vom rechten Weg abkommen.", sourceObjective = "Bringt 6 Draenethystkristalle zu Magtoor im sicheren Hafen in den Sümpfen des Elends.", progress = "Habt Ihr die Kristalle?", completion = "Danke, {name}. Wir stehen in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[1391] = { id = 1391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts als die Wahrheit", description = "Wir müssen mit einer gewissen Diskretion vorgehen. Immerhin werdet Ihr nicht da reinspazieren und den Narren überzeugen, Faustins Gebräu zu trinken, richtig?\n\nAber wenn es eines gibt, zu dem die Menschen nicht nein sagen können, dann ist es Fusel. Ich nehme Faustins Serum und mische es in dieses Bier. Der arme Kerl wird garantiert keine Hemmungen haben, wenn es darum geht, ein Gebräu zu kippen.\n\nGeht hastig nach Stonard in den Sümpfen des Elends, {name}. Und schweigt schön stille über unsere kleine Mission ...", sourceObjective = "Bringt Zraedus' Bräu zu Spitzel Marksen in Stonard.", progress = "Bitte habt Erbarmen mit mir! Ich habe Informationen, die über die Bande der Allianz hinausgehen. Ich hege keine Sympathie für die Horde, aber hier findet ein politischer Verrat statt, der ans Licht gebracht werden muss!", completion = "Ein Getränk für mich? Wie gütig. Sie haben mich seit Tagen nichts mehr trinken lassen. Ich trinke das rasch und dann erzähle ich Euch, was ich herausgefunden habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[1392] = { id = 1392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noboru der Knüppel", description = "Noboru verseuchte die Draenei des sicheren Hafens seit Monaten; sein Knüppel ist ein Symbol der Brutalität, die sie sich von den Verirrten gefallen lassen mussten.", sourceObjective = "Bringt Noborus Knüppel zum Anführer des sicheren Hafens in den Sümpfen des Elends.", progress = "Seid gegrüßt. Und willkommen im sicheren Hafen.", completion = "Habt Ihr die Waffe des verhassten Noboru? Ist er denn tot?\n\nDas ist ein Freudentag für den sicheren Hafen. Noboru und seine Bande waren ein Schrecken für uns, denn sie zogen durch die Sümpfe und töteten jeden Draenei, der ihren Weg kreuzte. Er war eine unmittelbare Bedrohung für unser Überleben und wir hatten nicht die Kraft, ihm zu trotzen.\n\nWir sind glücklich, einen Freund in Euch zu haben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1393] = { id = 1393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galens Flucht", description = "Bitte helft! Diese Kreaturen werden mich fressen!\n\nHelft mir hier raus und ich gebe Euch einen großen Schatz! Er ist in meinem Lager im Sumpf im Norden von Stonard, aber in einer Geldkassette eingeschlossen, die man mit einem Trick öffnet, den nur ich beherrsche.\n\nWenn ihr mir zur Flucht verhelft, zeige ich ihn Euch.", sourceObjective = "Eskortiert Galen, bis er außer Gefahr ist, sucht dann sein Lager in den Sümpfen des Elends und öffnet seine Geldkassette.", completion = "Das Schlüsselloch dieser Geldkassette ist voll von schwarzem Harz. Man kann sie unmöglich öffnen.\n\nAber Galen erzählte Euch von einem geheimen Schalter an der Unterseite des Kastens... \n\n... Nach einer kurzen Suche findet Ihr den Schalter. Der Schalter kippt und die Geldkassette öffnet sich...", sourceObjectiveStatus = "unverified-source-field" }
quests[1394] = { id = 1394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Überfahrt", description = "Ihr habt Eure Sache gut gemacht, {name}. Ihr habt meinen Test und die Tests vor meinem bestanden. Kehrt zu Dorn in Tausend Nadeln zurück. Er wird die Veränderung in Euch spüren und sehen, dass Euer Verstand, Körper und Geist stark genug sind, dass Ihr für Eure Bemühungen belohnt werden solltet.\n\nBleibt dem Gleichgewicht treu, das Ihr während all dieser Prüfungen gezeigt habt, {name}. Wenn Ihr das tut, wird Dorn Euch irgendwann noch einmal prüfen.", sourceObjective = "Sprecht mit Dorn Plainstalker in Tausend Nadeln.", completion = "Ah, {name}. Es ist lange her, seit Ihr mein Heim das letzte Mal betreten habt. Anscheinend sind viele Monde vergangen, seit Ihr den ersten Schritt auf Eurem Weg gegangen seid.\n\nUnd jetzt kehrt Ihr stärker als einst zu mir zurück... erleuchteter. Das freut mich. Und Ihr solltet gerecht belohnt werden, weil ihr meine Tests bis zum Ende durchgehalten habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1395] = { id = 1395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte für Nethergarde", description = "Diese Kiste mit Kraftsteinen muss in die Burg Nethergarde in den verwüsteten Landen. Sie werden ihre Macht nicht lange halten, daher können wir sie nicht mit der nächsten Karawane aufgeben.\n\nIhr müsst sie nehmen, und zwar schnell.\n\nBringt sie zu Rüstmeister Lungertz in der Burg Nethergarde. Um die Burg zu erreichen, müsst Ihr nach Osten über den Gebirgspass der Totenwinde, dann nach Osten durch die Sümpfe des Elends und dann nach Süden durch die verwüsteten Lande.\n\nSeid vorsichtig, {name}. Ihr müsst durch gefährliche Länder und dürft doch nicht verzagen.", sourceObjective = "Bringt die Kiste mit den Kraftsteinen zu Rüstmeister Lungertz, bevor die Kraft verbraucht ist.", progress = "Hallo! Stört Euch nicht an dem Durcheinander, so ist das immer in der Burg Nethergarde.\n\nHabt ihr denn etwas für mich?", completion = "Ah, die Kraftsteine! Die Magier werden sich freuen, die zu sehen!\n\nVielen Dank, {name}. Ich weiß, Eure Reise von Dunkelhain war nicht leicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1396] = { id = 1396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauernde Tierwelt", description = "Meine Karawane sollte zur östlichen Küste ziehen, aber wir erreichten unser Ziel nicht. Verirrte haben uns angegriffen, die Wachen getötet und die Vorräte verstreut.\n\nIch allein habe ihren Angriff überlebt. Ich habe geschworen, die verbliebenen Vorräte zu schützen, aber wilde Kreaturen schleichen in der Nähe herum. Bitte helft mir, mein Lager gegen diese Bestien zu verteidigen!", sourceObjective = "Tötet 8 junge Sägezahnkrokilisken, 10 Trauerspinner sowie 10 Sumpfjaguare und kehrt dann zu Behüter Biggs in den Sümpfen des Elends zurück.", completion = "Die Geräusche der Tiere klingen jetzt leiser, ferner. Danke, {name}. Hoffentlich kommen sie nicht zurück!", sourceObjectiveStatus = "unverified-source-field" }
quests[1398] = { id = 1398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibholz", description = "Ich stehe tief in Eurer Schuld, {name}. Ein ehrenhaftes Herz schlägt in Eurer Brust. Und jetzt habe ich eine andere Aufgabe, für die ich demütig um Eure Mithilfe bitte.\n\nWenn ich Nethergarde erreichen soll, dann muss ich diesen Wagen reparieren. Und dafür ... brauche ich Holz. Starkes, trockenes Holz - nicht das schimmelige, krumme Holz der Sumpfbäume.\n\n{name}, geht nach Osten zur Küste und sucht nach in der Sonne getrocknetem Treibholz. Bringt es mir.", sourceObjective = "Bringt 8 Stücke sonnengetrocknetes Treibholz zu Behüter Biggs in den Sümpfen des Elends.", progress = "Habt Ihr das Treibholz gefunden, {name}?", completion = "Dieses Holz ist leicht, aber fest. Danke, {name}. Es ist genau richtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[1418] = { id = 1418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neeka Bloodscar", description = "Das Ödland ist unwirtlich und liegt nahe am Land des Loch Modan, das von der Allianz beherrscht wird, daher wird die Kommunikation zwischen Stonard und den Ödland-Außenposten von Kargath oft unterbrochen.\n\nBeweist Euch, {name}. Reist ins Ödland und sprecht mit Neeka Bloodscar, der obersten Späherin des Kargath-Außenpostens. Sprecht mit ihr und bringt mir ihren Bericht.", sourceObjective = "Sprecht mit Neeka Bloodscar.", completion = "Helgrum möchte einen Bericht, hm? Ich sandte einen Kundschafter nach Stonard, das ist noch keine drei Tage her. Hat er seine Mission nicht erfüllt? Wenn Stonard meinen Bericht nicht hat, muss er versagt haben.\n\nHoffen wir, dass der nächste Läufer, den ich schicke, mehr Fertigkeiten oder mehr Glück hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[1419] = { id = 1419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kojoten-Diebe", description = "Habt Ihr viele Tage im Ödland verbracht, {class}? Habt Ihr sein Herz gespürt? Habt Ihr den Bestien getrotzt, die durch die staubigen Ebenen schleichen? Dann wird es aber höchste Zeit.\n\nKlippenkojoten sind zähe Burschen. Zäh und tollkühn genug, dass sie sich nach Kargath schleichen und unsere Essensvorräte stehlen. Helft mit, den Außenposten von diesen Dieben zu befreien!\n\nJagt Klippenkojoten, {name}. Jagt sie und bringt mir ihre Kieferknochen. Bringt mir genügend und ich glaube Euch vielleicht, wenn Ihr sagt, dass Ihr das Ödland kennt.", sourceObjective = "Bringt 30 Kojotenkieferknochen zu Neeka Bloodscar in Kargath.", progress = "Habt Ihr die Kieferknochen?", completion = "Das ist eine nette Sammlung Kieferknochen, {name}. Jetzt werden diese Kojoten nicht mehr unsere Vorräte nach Futter durchwühlen.\n\nGut gemacht. Die Kojoten des Ödlandes sind keine leichte Beute. Eure Tat zeigt mir, dass Ihr hier tatsächlich überleben könntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1420] = { id = 1420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht für Helgrum", description = "Ich schrieb einen neuen Bericht für Helgrum in Stonard. Bringt ihn zu ihm.\n\nUnd wenn Ihr Euch als Kundschafter betrachtet, kommt nicht vom Weg ab. Oder fallt einem Feind in die Hände.", sourceObjective = "Bringt Neekas Bericht zu Helgrum dem Hurtigen in Stonard.", progress = "Ihr seid zurück. Habt Ihr einen Bericht?", completion = "Danke, {name}. Neekas Bericht entnehme ich, dass die Allianz selbst auch Probleme hat. Und wir können feststellen, dass einige Feinde gemeinsame Feinde sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1421] = { id = 1421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Karawane", description = "Ich wurde während des Angriffs der Verirrten betäubt, aber bevor mir schwarz vor Augen wurde, sah ich einen unserer Wagen, der zum Fallow Heiligtum gezerrt wurde, zum Dorf der Verirrten im Norden.\n\nEine Karawanentruhe mit wertvollen Reagenzien war in diesem Wagen, Reagenzien, die unabdingbar für die Studien der Hexer der Burg Nethergarde sind. Sucht die Truhe und holt diese Reagenzien, {name}. Holt sie und bringt sie mir.", sourceObjective = "Sucht die Karawanentruhe im Fallow Heiligtum, beschafft Euch die Reagenzien der Hexer und bringt sie zu Behüter Biggs.", progress = "Habt Ihr die Hexerreagenzien, {name}?", completion = "Ah, Ihr habt sie gefunden! Damit können die Hexer in Nethergarde ihre Arbeit fortsetzen. Ich weiß nicht, was sie tun, aber es hat mit dem Dunklen Portal in den verwüsteten Landen zu tun und ist wichtig für die Sicherheit der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[1422] = { id = 1422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr aus dem Meer", description = "Warum unterhaltet Ihr Euch nicht mit Katar, während ich an Eurer Waffe arbeite? Er erwähnte, dass er Hilfe bei Patrouillen am Strand braucht, und mir wäre es lieber, Ihr würdet Euren Geist und Eure Waffen trainieren, anstatt Euch mit den anderen Tunichtguten in diesem Lager zu betrinken.", sourceObjective = "Sprecht mit Katar in den Sümpfen des Elends.", completion = "Schweigt einen Moment, {class}. Trotz der dumpf tosenden Brandung könnt Ihr das abscheuliche Gluckern der Fischmenschen hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[1423] = { id = 1423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorenen Vorräte", description = "Dieses Fass ist klein, aber stabil. Seine Ritzen sind mit einem gelben, duftenden Wachs versiegelt. Auf der Unterseite des Fasses stehen die Worte:\n\nRÜSTMEISTER LUNGERTZ\n\nBURG NETHERGARDE", sourceObjective = "Bringt die verlorenen Vorräte zu Rüstmeister Lungertz.", progress = "Habt Ihr etwas für mich?", completion = "Ah, vielen Dank, {name}! So viele Vorräte gehen auf dem Weg von Dunkelhain hierher verloren. Es tut gut zu sehen, dass einige davon wiederbeschafft werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[1424] = { id = 1424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tränenteich", description = "Der Kriegshäuptling schickt uns, die seltsamen Vorkommnisse im Tempel von Atal'Hakkar zu untersuchen.\n\nDie Trolle des Stammes der Atal'ai sind ein Stamm dunkler Zauberkundiger, die dafür bekannt sind, verbotene Magie auszuüben. Ihr könnt Euch vorstellen, wie erstaunt wir waren, als wir hier eintrafen und feststellten, dass der Tempel versunken war.\n\nDie grünen Großdrachen hüten nun die Stelle und spielen sich als Beschützer von Azeroth auf.\n\nWir müssen herausfinden, was geschehen ist. Forscht rund um den Tränenteich und sammelt Artefakte der Atal'ai. Damit kann ich dieses Rätsel lösen.", sourceObjective = "Fel'Zerul in Stonard möchte, dass Ihr 10 Artefakte der Atal'ai sammelt.", progress = "Niemand weiß, welche dunklen Rituale im Tempel von Atal'Hakkar durchgeführt wurden. Aber wir wissen, dass große und mächtige magische Kräfte benutzt wurden.\n\nWir müssen so viel wir können über diese Magie lernen. Vielleicht erweisen sich die Zauber der Atal'ai als nützlich für die Horde.\n\nWenn Ihr genügend Artefakte der Atal'ai rings um den Tränenteich gesammelt habt, verstehe ich vielleicht, was sich die Trolle erhofften und was so schrecklich schief gegangen ist.", completion = "Euer Geschick beim Aufspüren der Artefakte der Atal'ai verdient höchstes Lob, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1425] = { id = 1425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überbringen der Lieferung", description = "Während ich diesen Wagen repariere, {name}, habe ich eine letzte Aufgabe für Euch.\n\nIch habe die wichtigsten Vorräte eingepackt, die ich vor den Angriffen der Oger retten konnte. Bringt sie zur Burg Nethergarde. Die Burg schmiegt sich an die nördlichen Hügel der verwüsteten Lande und wacht über das Dunkle Portal.\n\nFolgt der Straße nach Osten, um Nethergard zu erreichen. Geht an der Gabelung nach Süden in die verwüsteten Lande und bei der nächsten Gabelung nach links. Folgt der Straße, {name}, und seid wachsam.", sourceObjective = "Bringt die Ladung für Nethergarde zu Rüstmeister Lungertz in der Burg Nethergarde.", progress = "Habt Ihr etwas mit mir zu schaffen?", completion = "Was? Ein Päckchen von Briggs' Karawane? Wir dachten, es wäre verloren, genau wie er.\n\nDanke, {name}. Mit etwas Glück befinden sich bei diesen Vorräten die dringend benötigten Reagenzien Azorankristalle. Unser Vorrat wird knapp...", sourceObjectiveStatus = "unverified-source-field" }
quests[1426] = { id = 1426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr aus dem Meer", description = "Ich mag weder das Meer noch die Kreaturen, die ich aus seiner Tiefe kommen sah. Es ist eine mächtige, aber blinde Herrin; launisch und brutal. Es wäre mir ein Vergnügen, die Fischmenschen zu Hunderten zu töten, wenn es in meiner Macht stünde. Eine kleine Freude ist es mir wenigstens, sie durch die Hände all derer sterben zu sehen, die den Willen der Horde erfüllen.\n\nUnd damit sind wir bei Euch, {class} . Wie viele könnt Ihr besiegen? Würdet Ihr Euch mit dem Mächtigsten ihrer Art messen?", sourceObjective = "Tötet 10 Marschenmurlocs, 10 Marschentintenspucker und 10 Marschenfleischfresser und kehrt dann zu Katar in den Sümpfen des Elends zurück.", progress = "Ich bin geduldig. Geduldig und ewig wie ein alter Kankstein von Draenor. Die Fischmenschen werden unsere Grenzen nicht passieren - nicht solange ich stehe. Hätten wir eine Armee, würde ich diese Welt und alle anderen von ihnen säubern. Ich spüre, wie mein Hass lodert, wenn ich nur von ihnen spreche.", completion = "Das Meer wirkt weit und unbarmherzig, doch Ihr habt es mit dem Blut seiner eigenen Brut besudelt. Die Fischmenschen kennen den Schmerz. Durch ihre Dummheit müssen sie ihre Reihen nach der Verheerung, die Ihr über sie brachtet, neu auffüllen, und das ist gut.\n\nSollen ihre gurgelnden Schreie das Brüllen der Brandung noch bis weit in die Nacht übertönen. Ich werde jedes Mal lächeln, wenn einer von ihnen verstummt.\n\nKehrt zu mir zurück, wenn Ihr noch mehr Fischmenschen töten wollt. Ich werde Euch gern abermals belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1427] = { id = 1427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr aus dem Meer", description = "Sprecht wieder mit Tok'Kar, bevor Ihr Euch ausruht. Während Ihr fort wart, hat er, glaube ich, ein paar Waffen vollendet. Für Eure Hilfe würde er Euch eine davon anbieten. Ihr tätet gut daran, ihre Kraft an den Fischmenschen zu erproben, wenn Ihr bereit seid ... aber nur, um mich weiterhin zu erfreuen.", sourceObjective = "Sprecht mit Tok'Kar in den Sümpfen des Elends.", completion = "Ah, {name}, Ihr seid zurück. Gut. Ich habe weitere Waffen für unseren Kampf gegen die Murlocs hergestellt. Da Ihr uns frisches Sägezahnfleisch gebracht und ein Lächeln auf Katars Gesicht gezaubert habt, biete ich Euch eine davon an.", sourceObjectiveStatus = "unverified-source-field" }
quests[1428] = { id = 1428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortwährende Gefahr", description = "Freut mich zu sehen, dass Euer Hass auf die Fischmenschen mit meinem wächst.\n\nSucht mehr von ihnen am Strand entlang, und wenn Ihr genug vom Gefecht habt, kommt zu mir zurück. Dann sprechen wir über eine Belohnung für Eure Ausdauer.", sourceObjective = "Tötet 10 Marschentintenspucker, 10 Marschenfleischfresser und 10 Marschenorakel und kehrt dann zu Katar in den Sümpfen des Elends zurück.", progress = "Erst wenn das Meer und all seine Kinder verstummt sind, werde ich zufrieden sein... besonders diese abstoßenden Fischmenschen.", completion = "Gut gemacht, {class}. Ich möchte mehr von ihrem Blut sehen. Mögen alle Fischmenschen verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
